local config = {
  ui_story_5080_50800100_1_dialog_content = "While our tactics in this battle were very successful, with all due respect, your plan was extremely risky.",
  ui_story_5080_50800100_2_dialog_content = "Heh, desperate times call for desperate measures.",
  ui_story_5080_50800100_3_dialog_content = "Still, I'm a little surprised you, of all people, think it's risky.",
  ui_story_5080_50800100_4_dialog_content = "Reporting in! Special Operation A4 was a success, and our operatives safely returned!",
  ui_story_5080_50800100_5_dialog_content = "The new report has been submitted for your approval.",
  ui_story_5080_50800100_6_dialog_content = "Understood. Anything else?",
  ui_story_5080_50800100_7_dialog_content = "Yes, Grand Marshal. Some of the operatives have made personal requests, which I have also submitted to you.",
  ui_story_5080_50800100_8_dialog_content = "Just tell me.",
  ui_story_5080_50800100_9_dialog_content = "They wish to be reassigned to another squad. More precisely, they no longer wish to operate under their current leader.",
  ui_story_5080_50800100_10_dialog_content = "So...",
  ui_story_5080_50800100_11_dialog_content = "The unfortunate leader is...",
  ui_story_5080_50800100_12_dialog_content = "It's Captain <color=#FFB400>Rachel</color>, ma'am.",
  ui_story_5080_50800100_13_dialog_content = "Understood.",
  ui_story_5080_50800100_14_dialog_content = "I knew it...",
  ui_story_5080_50800100_15_dialog_content = "This is the fourth time now. Has she really not changed at all, Hiiro?",
  ui_story_5080_50800100_16_dialog_content = "My apologies, Grand Marshal. I failed to help my subordinate.",
  ui_story_5080_50800100_17_dialog_content = "Looks like we'll have to do something about this.",
  ui_story_5080_50800100_18_dialog_content = "I think it's time to put her on that mission.",
  ui_story_5080_50800100_19_dialog_content = "I'm grateful that you're willing to give her another chance.",
  ui_story_5080_50800100_20_dialog_content = "It's just... Is it really helping when her wings are already damaged?",
  ui_story_5080_50800100_21_dialog_content = "Under no circumstances are we allowed to lose such an excellent captain.",
  ui_story_5080_50800100_22_dialog_content = "I just hope it will have some sort of impact on her.",
  ui_story_5080_50800100_23_dialog_content = "There's no telling if it will work, but maybe a new fledgling is what she needs to spread her wings and fly high again.",
  ui_story_5080_50800100_24_dialog_content = "Carleen, watch your left foot!",
  ui_story_5080_50800100_25_dialog_content = "Duck, PlayerName! Stay focused!",
  ui_story_5080_50800100_26_dialog_content = "Thanks... Vice! Watch your back!",
  ui_story_5080_50800100_27_dialog_content = "Not a chance!",
  ui_story_5080_50800100_28_dialog_content = "Why are there suddenly so many Eclipsites...?",
  ui_story_5080_50800100_29_dialog_content = "We're on the edge of the Rediesel Desert, remember? There are still plenty of areas out here that haven't been cleared.",
  ui_story_5080_50800100_30_dialog_content = "Still, there are way too many of them... Why is Commander Hiiro's <color=#FFB400>subordinate</color> waiting for us all the way out here? It makes no sense...",
  ui_story_5080_50800100_31_dialog_content = "Listen closely, Vice. The mission I'm about to assign to you comes from the Grand Marshal herself.",
  ui_story_5080_50800100_32_dialog_content = "For this top-secret mission, you'll be working under a certain person's command, and will assist her in completing her mission.",
  ui_story_5080_50800100_33_dialog_content = "You're permitted to bring any companions you deem necessary to the mission, even those not from Illumina.",
  ui_story_5080_50800100_34_dialog_content = "I'm certain the Grand Marshal has her reasons for allowing this.",
  ui_story_5080_50800100_35_dialog_content = "I don't think I've ever heard of a mission like this, Commander Hiiro. Who exactly is the person in question?",
  ui_story_5080_50800100_36_dialog_content = "You should be no stranger to her. After all, she is one of your seniors—",
  ui_story_5080_50800100_37_dialog_content = "Her name is <color=#FFB400>Rachel.</color>",
  ui_story_5080_50800100_38_dialog_content = "They just don't stop coming. Are you sure this is the right way, Vice?",
  ui_story_5080_50800100_39_dialog_content = "I'm sure of it. According to the map, this is the best possible route.",
  ui_story_5080_50800100_40_dialog_content = "The captain we're looking for is the one who sent you that map, right? How can you be so trusting of someone we've never even met before?",
  ui_story_5080_50800100_41_dialog_content = "You do seem especially serious about this mission, Vice.",
  ui_story_5080_50800100_42_dialog_content = "I would even say you're enthusiastic about it. You were preparing for the mission well before the sun rose today.",
  ui_story_5080_50800100_43_dialog_content = "Well, that's because... This person is a legend of the 3rd Legion.",
  ui_story_5080_50800100_44_dialog_content = "When I was still at the academy, we learned all about her brilliant achievements and were expected to follow her example.",
  ui_story_5080_50800100_45_dialog_content = "She was already a highly decorated captain before she was my age!",
  ui_story_5080_50800100_46_dialog_content = "A legend of the 3rd Legion... Why haven't we heard about her before?",
  ui_story_5080_50800100_47_dialog_content = "I'm not sure why, but after she suddenly disappeared one day, no one ever saw her again...",
  ui_story_5080_50800100_48_dialog_content = "Graah—",
  ui_story_5080_50800100_49_dialog_content = "There are too many Eclipsites.",
  ui_story_5080_50800100_50_dialog_content = "This place is a terrible landing zone...",
  ui_story_5080_50800100_51_dialog_content = "What if I ask <color=#FFB400>Soroz</color> to come pick us up now? Wait, it would only draw even more Eclipsites.",
  ui_story_5080_50800100_52_dialog_content = "That would even put this captain in danger!",
  ui_story_5080_50800100_53_dialog_content = "Looks like we don't have a choice. Carleen, I'll contain the Eclipsites while you make a break for higher ground!",
  ui_story_5080_50800100_54_dialog_content = "What? Don't lose focus, PlayerName! Get back behind me!",
  ui_story_5080_50800100_55_dialog_content = "Graaah!",
  ui_story_5080_50800100_56_dialog_content = "(They're attacking from beneath the sand?! No good, I can't dodge in time!)",
  ui_story_5080_50800100_57_dialog_content = "PlayerName!",
  ui_story_5080_50800100_58_dialog_content = "You should learn to protect yourself before worrying about others, <color=#FFB400>Caelestite One</color>.",
  ui_story_5080_50800100_59_dialog_content = "This was just a small test. Was it really that difficult for you?",
  ui_story_5080_50800100_60_dialog_content = "No matter. Assessing your true strength is also one of my responsibilities.",
  ui_story_5080_50800100_61_dialog_content = "Are you okay, PlayerName?",
  ui_story_5080_50800100_62_dialog_content = "I-I'm fine... Who's that person...",
  ui_story_5080_50800100_63_dialog_content = "A woman with a piercing gaze, surrounded by drones...",
  ui_story_5080_50800100_64_dialog_content = "And wearing the uniform of an elite captain...",
  ui_story_5080_50800100_65_dialog_content = "You must be...!",
  ui_story_5080_50800100_66_dialog_content = "Are you the captain of the <color=#FFB400>Eagleeye Squad</color>? Th-Thank you for saving PlayerName!",
  ui_story_5080_50800100_67_dialog_content = "<color=#FFB400>Eagleeye</color>... There's no need to mention that anymore.",
  ui_story_5080_50800100_68_dialog_content = "The Commander said you've been working together for a long time now. How could you still make so many amateur mistakes?",
  ui_story_5080_50800100_69_dialog_content = "You invest far too many unnecessary emotions in your squadmates, Caelestite.",
  ui_story_5080_50800100_70_dialog_content = "In my opinion, your lancer is more than capable of protecting you and fending for herself.",
  ui_story_5080_50800100_71_dialog_content = "Rather than abandoning your position so recklessly, you should have just let Vice pick off the more important targets.",
  ui_story_5080_50800100_72_dialog_content = "And you. You're a captain too, aren't you?",
  ui_story_5080_50800100_73_dialog_content = "Y-Yes, ma'am!",
  ui_story_5080_50800100_74_dialog_content = "Your specialty lies in scouting as well. There's no reason for you... to get in over your head.",
  ui_story_5080_50800100_75_dialog_content = "(Is she... showing concern for Vice?)",
  ui_story_5080_50800100_76_dialog_content = "For a three-person squad facing waves of Eclipsites, your first priority should be to break through the enemy's ranks quickly.",
  ui_story_5080_50800100_77_dialog_content = "With a sniper in the squad, the offense should be left almost entirely to the lancer while the others focus on their objective.",
  ui_story_5080_50800100_78_dialog_content = "But since you chose to fight defensively... Lancer, why do you keep diverting your attention to protect your sniper? Considering she's more agile than you, you should focus on protecting the person behind you.",
  ui_story_5080_50800100_79_dialog_content = "(S-So strict.)",
  ui_story_5080_50800100_80_dialog_content = "Somehow, I'm reminded of someone...",
  ui_story_5080_50800100_81_dialog_content = "Why are you all staring at me?",
  ui_story_5080_50800100_82_dialog_content = "But still, I find it difficult to place my trust in someone who tested us in such a dangerous way.",
  ui_story_5080_50800100_83_dialog_content = "... It makes no difference to me. My original understanding was that only two people were assigned to this mission; I didn't expect the princess of Lumopolis to be here as well.",
  ui_story_5080_50800100_84_dialog_content = "You looked into my background?",
  ui_story_5080_50800100_85_dialog_content = "Don't be so surprised. I figured all of this out just by looking at you.",
  ui_story_5080_50800100_86_dialog_content = "As for you, The Last Caelestite... Per Illumina's regulations, outsiders are not allowed on our missions. But since the Commander was willing to make an exception for you, I have nothing else to say.",
  ui_story_5080_50800100_87_dialog_content = "Sh-Should I be grateful for that...?",
  ui_story_5080_50800100_88_dialog_content = "My name is Rachel. I'll be your commanding officer for this mission.",
  ui_story_5080_50800100_89_dialog_content = "Uh, nice to meet you. I'm...",
  ui_story_5080_50800100_90_dialog_content = "During this mission, we'll be conducting operations as a cohesive unit. Once the mission is complete, the squad will be dismissed; until then, we will communicate using code names.",
  ui_story_5080_50800100_91_dialog_content = "You are Caelestite One.",
  ui_story_5080_50800100_92_dialog_content = "You are Hatchling Two.",
  ui_story_5080_50800100_93_dialog_content = "...",
  ui_story_5080_50800100_94_dialog_content = "As for you, princess of Lumopolis, you are a complete outsider to the Illumina Federation's military. However, since you arrived together, it means that you have also agreed to the mission's conditions.",
  ui_story_5080_50800100_95_dialog_content = "From now on, I will refer to you as the White Lancer.",
  ui_story_5080_50800100_96_dialog_content = "Am I supposed to agree to that? I expected as much from an Illumina soldier...",
  ui_story_5080_50800100_97_dialog_content = "This is highly disrespectful.",
  ui_story_5080_50800100_98_dialog_content = "This must be how our special forces operate. I don't think she means anything by it, Carleen.",
  ui_story_5080_50800100_99_dialog_content = "The three of you can call me Eagle Hunter Zero or Captain.",
  ui_story_5080_50800100_100_dialog_content = "Understood... Eagle Hunter Zero.",
  ui_story_5080_50800100_101_dialog_content = "(She seemed so caring just a minute ago... why does she suddenly feel so cold and distant?)",
  ui_story_5080_50800100_102_dialog_content = "Captain Rach—Captain! You may not know me, but I was one of your juniors. Even though I was in a different field of study, I knew all about you.",
  ui_story_5080_50800100_103_dialog_content = "All about... me...?",
  ui_story_5080_50800100_104_dialog_content = "That's right! When I was still in school, we heard all about your achievements and how you led the Eagleeye Squad.",
  ui_story_5080_50800100_105_dialog_content = "Commander Hiiro will always tell us to learn from your example whenever you come back from a successful mission.",
  ui_story_5080_50800100_106_dialog_content = "Even though much has happened since then, and even though I rarely return to Illumina because of my adventures with PlayerName, I still look up to you.",
  ui_story_5080_50800100_107_dialog_content = "We could only guess what had happened when we stopped hearing about you. But it's clear now that you and the Eagleeye Squad must have been on a secret mission, right?",
  ui_story_5080_50800100_108_dialog_content = "...",
  ui_story_5080_50800100_109_dialog_content = "And with you in charge of our mission, I'm sure it'll be a huge success! This is the perfect opportunity for me to study your work in action too.",
  ui_story_5080_50800100_110_dialog_content = "Let's set the idle banter aside for now. Come with me so we can discuss the mission.",
  ui_story_5080_50800100_111_dialog_content = "(It looks like she doesn't want to bring up the past at all... But why? She's a legend after all...)",
  ui_story_5080_50800100_112_dialog_content = "For this mission, I'll lead you deep into the desert, the Rediesel Wrench's territory, to investigate the presence of a unique Eclipsite.",
  ui_story_5080_50800100_113_dialog_content = "This type of Eclipsite commands the power of lava. As such, it only appears in high-temperature environments, where it tends to leave clear signs of its movements.",
  ui_story_5080_50800100_114_dialog_content = "Eclipsites such as these pose a serious threat, and must be handled cautiously.",
  ui_story_5080_50800100_115_dialog_content = "All of you must follow my command without deviation if you want to avoid any unexpected casualties.",
  ui_story_5080_50800100_116_dialog_content = "Furthermore, there will be times when I have to investigate other matters. You're free to move on your own during those times.",
  ui_story_5080_50800100_117_dialog_content = "What other matters, may I ask?",
  ui_story_5080_50800100_118_dialog_content = "Tell me, do you know anything about the <color=#FFB400>Freebird</color> Squad?",
  ui_story_5080_50800100_119_dialog_content = "I can't say that I do... Sorry.",
  ui_story_5080_50800100_120_dialog_content = "Then there's nothing for you to worry about. It lies outside the scope of our mission, so there's no need for you to assist me... Though you're welcome to give me any clues you might find.",
  ui_story_5080_50800100_121_dialog_content = "We're pretty good friends with Sinsa. If our mission is to investigate Eclipsites, we should try asking him for help.",
  ui_story_5080_50800100_122_dialog_content = "I see... Perhaps this is why the Grand Marshal selected you for this mission. Exchanging information could prove both useful and efficient. You have my permission to make contact with him, now go.",
  ui_story_5080_50800100_123_dialog_content = "Huh? But what about you, Captain...?",
  ui_story_5080_50800100_124_dialog_content = "As an officer of the Illumina Federation, I have no business to discuss with desert outlaws. If we were to see one another, I'd have no choice but to apprehend them and bring them to justice.",
  ui_story_5080_50800100_125_dialog_content = "Now go. I still have my own matters to investigate.",
  ui_story_5080_50800100_126_dialog_content = "All by yourself? But this place is so dangerous, Captain... Shouldn't we split into pairs instead?",
  ui_story_5080_50800100_127_dialog_content = "Given your history of fighting alongside one another, your combat synergy will be more effective without the addition of an unfamiliar fighter such as myself.",
  ui_story_5080_50800100_128_dialog_content = "Now make your way to the Rediesel Wrench's base camp and begin gathering intel—That's an order.",
  ui_story_5080_50800100_129_dialog_content = "I'll rendezvous with you at a later time.",
  ui_story_5080_50800100_130_dialog_content = "And just like that, she's gone.",
  ui_story_5080_50800100_131_dialog_content = "Lack of manners aside, she's an undeniably capable soldier.",
  ui_story_5080_50800100_132_dialog_content = "... Hey, Vice? I'm still thinking about something Rachel said just now.",
  ui_story_5080_50800100_133_dialog_content = "That Freebird Squad she mentioned... Could it be connected to the Eagleeye Squad somehow?",
  ui_story_5080_50800100_134_dialog_content = "I'm not sure. They might be similar in name only, but... Huh? The Freebird Squad is actually from Illumina...",
  ui_story_5080_50800100_135_dialog_content = "If our current mission is to investigate a certain Eclipsite's presence, why is the Captain also investigating one of your fellow squads?",
  ui_story_5080_50800100_136_dialog_content = "I don't see the connection at all... But judging by her character, I doubt she would do something for no reason.",
  ui_story_5080_50800100_137_dialog_content = "Oh, you're making me curious too... Anyway, Chief Philyshy must have the answer. Let me just ask her.",
  ui_story_5080_50800100_138_dialog_content = "Meow? A surprise communication from Vice. Did you run into some sort of problem?",
  ui_story_5080_50800100_139_dialog_content = "I just wanted to ask if you had any information concerning a group known as the Freebird Squad?",
  ui_story_5080_50800100_140_dialog_content = "Hmm... Well, the naming convention sounds like our own, but it's definitely from a while ago. I'm sure I can dig something up in our files.",
  ui_story_5080_50800100_141_dialog_content = "Thank you, Chief Philyshy. I'm so curious about it. I'll be sure to bring you some top-notch fish jerky the next time we meet!",
  ui_story_5080_50800100_142_dialog_content = "As long as the information isn't classified, it won't hurt to share it with you—But either way, I'll be expecting that fish!",
  ui_story_5080_50800100_143_dialog_content = "Sorry for the wait, meow! It says here that the Freebird Squad existed nearly forty years ago. They were an elite special operations team with over a dozen highly dangerous missions flawlessly completed.",
  ui_story_5080_50800100_144_dialog_content = "But during their final mission, they were dispatched to the Rediesel Desert in search of a certain something. And that mission... ended in failure, meow.",
  ui_story_5080_50800100_145_dialog_content = "Unfortunately, the rest of the details in this file are so highly classified that I don't even have the authorization to view them.",
  ui_story_5080_50800100_146_dialog_content = "What? There are files that even you can't access?",
  ui_story_5080_50800100_147_dialog_content = "I can't even see the name of their squad's leader... But when something is this classified for this long, it usually implies that a person defected from the Federation.",
  ui_story_5080_50800100_148_dialog_content = "This is some pretty interesting stuff. Where did you come across this name, meow?",
  ui_story_5080_50800201_1_dialog_content = "I wonder what's taking Sinsa so long?",
  ui_story_5080_50800201_2_dialog_content = "They're far from us right now, and they're all too busy working on some sort of project.",
  ui_story_5080_50800201_3_dialog_content = "...",
  ui_story_5080_50800201_4_dialog_content = "Are you okay, Vice? Why do you look so serious?",
  ui_story_5080_50800201_5_dialog_content = "Huh? Oh, I'm fine... I'm just wondering why the Captain brought up a squad from such a long time ago.",
  ui_story_5080_50800201_6_dialog_content = "Not only that, but a squad whose captain was suspected of desertion.",
  ui_story_5080_50800201_7_dialog_content = "Considering how she does things, I'd say she probably specializes in gathering intelligence.",
  ui_story_5080_50800201_8_dialog_content = "Maybe that's what she's doing: gathering intelligence on the suspected deserter?",
  ui_story_5080_50800201_9_dialog_content = "Possibly, but that was almost forty years ago. What would be the point of continuing such an old investigation?",
  ui_story_5080_50800201_10_dialog_content = "Could it be that Rachel is somehow connected to that person?",
  ui_story_5080_50800201_11_dialog_content = "The Freebird Squad... And the Eagleeye Squad...",
  ui_story_5080_50800201_12_dialog_content = "Yo! What's with all the serious faces?",
  ui_story_5080_50800201_13_dialog_content = "Sinsa!",
  ui_story_5080_50800201_14_dialog_content = "Long time no see! You're looking much stronger now too! Have you finally decided to work for us?",
  ui_story_5080_50800201_15_dialog_content = "Uh, that's probably still...",
  ui_story_5080_50800201_16_dialog_content = "Hahaha! Don't worry about it. You can find us whenever you decide! So what brings you here today, huh?",
  ui_story_5080_50800201_17_dialog_content = "Actually, we're here on a special mission... Do you know about any unique or abnormal Eclipsites here in the desert?",
  ui_story_5080_50800201_18_dialog_content = "Eh? Such as...?",
  ui_story_5080_50800201_19_dialog_content = "Uh, let me think... Maybe one that looks burning? Or one that hangs around volcanoes?",
  ui_story_5080_50800201_20_dialog_content = "What are you talking about? There are tons of Eclipsites lurking around the volcanoes.",
  ui_story_5080_50800201_21_dialog_content = "Yes, but these Eclipsites are particularly drawn to volcanoes, and can even wield the power of lava.",
  ui_story_5080_50800201_22_dialog_content = "They're abnormally strong, and they leave obvious signs of their movements wherever they go.",
  ui_story_5080_50800201_23_dialog_content = "Can you think of any Eclipsites that fit the bill?",
  ui_story_5080_50800201_24_dialog_content = "Lava Eclipsites... No way. It's been over a decade...",
  ui_story_5080_50800201_25_dialog_content = "So you do know something about them?",
  ui_story_5080_50800201_26_dialog_content = "Please tell us what you know. We need as much information on them as possible right now.",
  ui_story_5080_50800201_27_dialog_content = "As far as most folks are concerned, this stuff is ancient history. It also has a lot to do with our family...",
  ui_story_5080_50800201_28_dialog_content = "But since it's so important to you guys, I guess I can tell you about it.",
  ui_story_5080_50800201_29_dialog_content = "I know about the Eclipsites you're looking for... Or rather, the past members of the <color=#FFB400>Rediesel Wrench</color> had a blood feud with them.",
  ui_story_5080_50800201_30_dialog_content = "What do you mean by that?",
  ui_story_5080_50800201_31_dialog_content = "It happened during the <color=#FFB400>Darkover Crisis</color>. Back then, I was just a snot-nosed errand boy for the leader of the Rediesel Wrench.",
  ui_story_5080_50800201_32_dialog_content = "One day, the Eclipsites tore through our old home like a sandstorm, and we had no choice but to leave it behind.",
  ui_story_5080_50800201_33_dialog_content = "To buy us time to escape, our leader took some of our best fighters to cover our rear.",
  ui_story_5080_50800201_34_dialog_content = "I still remember what I saw that day... A real monster, one that scorched the sand beneath its feet into molten glass...",
  ui_story_5080_50800201_35_dialog_content = "Huh?",
  ui_story_5080_50800201_36_dialog_content = "What, didn't you hear me? I said...",
  ui_story_5080_50800201_37_dialog_content = "Huh?!",
  ui_story_5080_50800201_38_dialog_content = "Whoa—!",
  ui_story_5080_50800201_39_dialog_content = "I'm sorry! Help me, <color=#FFB400>Cursed Warrior</color>!",
  ui_story_5080_50800201_40_dialog_content = "Look out, PlayerName!",
  ui_story_5080_50800201_41_dialog_content = "Ahhh—Stop it, now!",
  ui_story_5080_50800201_42_dialog_content = "Aaaaaahhh—",
  ui_story_5080_50800201_43_dialog_content = "Sorry, sweetie, but nothing can stop the power of music!",
  ui_story_5080_50800201_44_dialog_content = "Thank goodness for the <color=#FFB400>Cursed Warrior</color> and his freakish strength!",
  ui_story_5080_50800201_45_dialog_content = "Zeta? Barbara and Tiny One too?! What are you doing?!",
  ui_story_5080_50800201_46_dialog_content = "You just crash your way into the base with your truck, that's just...",
  ui_story_5080_50800201_47_dialog_content = "There's no time to explain! Now hop in!",
  ui_story_5080_50800201_48_dialog_content = "Hah?!",
  ui_story_5080_50800201_49_dialog_content = "Don't tell me you didn't hear me, <color=#FFB400>Cursed Warrior</color>?! Those footsteps from a distant land—",
  ui_story_5080_50800201_50_dialog_content = "She's here! The Hunter of the Sands!",
  ui_story_5080_50800201_51_dialog_content = "Look over there! It's—",
  ui_story_5080_50800201_52_dialog_content = "<size=45>Rachel!!!</size>",
  ui_story_5080_50800201_53_dialog_content = "And just who's that? Alright Zeta, you have five seconds to tell me what kind of a mess you got yourselves into!",
  ui_story_5080_50800201_54_dialog_content = "Oh, this is bad...",
  ui_story_5080_50800201_55_dialog_content = "The airbag pinned me in place. I can't get out!",
  ui_story_5080_50800201_56_dialog_content = "Just hang on, I'll bust you out.",
  ui_story_5080_50800201_57_dialog_content = "No! We need to get away from her! She's the Minion of the Demon King!",
  ui_story_5080_50800201_58_dialog_content = "Bandits of the Rediesel Desert! Hand over what you've stolen!",
  ui_story_5080_50800201_59_dialog_content = "Hmph, you've got some nerve, lady.",
  ui_story_5080_50800201_60_dialog_content = "With a closer look, you're from Illumina, aren't you?",
  ui_story_5080_50800201_61_dialog_content = "Wait! Sinsa, Rachel, just listen to us...",
  ui_story_5080_50800201_62_dialog_content = "Quiet!",
  ui_story_5080_50800201_63_dialog_content = "An Illumina soldier who tried to hunt down a bunch of our kids, and forced them to crash their car into our base...",
  ui_story_5080_50800201_64_dialog_content = "Some desert outlaws with the audacity to steal my comrades-in-arms... I will show you no mercy!",
  ui_story_5080_50800201_65_dialog_content = "Looking for a fight, eh? Good! It's been too long since I've thrown punches at you people!",
  ui_story_5080_50800201_66_dialog_content = "Come at me!",
  ui_story_5080_50800201_67_dialog_content = "This isn't right! Vice, Carleen, we have to stop them!",
  ui_story_5080_50800201_68_dialog_content = "We'll do it together, now let's go!",
  ui_story_5080_50800202_1_dialog_content = "Annoying flying pests—I'll crush every last one of you!",
  ui_story_5080_50800202_2_dialog_content = "What else do you get now?",
  ui_story_5080_50800202_3_dialog_content = "Don't move. Unless you want to get blasted into the sky, that is...",
  ui_story_5080_50800202_4_dialog_content = "So you planted explosives on me just now, huh? Not bad.",
  ui_story_5080_50800202_5_dialog_content = "At this distance, neither of us will survive the blast.",
  ui_story_5080_50800202_6_dialog_content = "And yet you don't seem scared at all... I like that! Now, let's find out what happens next!",
  ui_story_5080_50800202_7_dialog_content = "I'm more than willing to lay down my life if it means taking down the leader of the Rediesel Wrench...",
  ui_story_5080_50800202_8_dialog_content = "Hey, hey, hey! Stop it already, you two!",
  ui_story_5080_50800202_9_dialog_content = "The mission, Captain! Think of the mission!",
  ui_story_5080_50800202_10_dialog_content = "What will the others do if something happens to you, Sinsa?!",
  ui_story_5080_50800202_11_dialog_content = "The kids here still need you!",
  ui_story_5080_50800202_12_dialog_content = "\"Kids\"?",
  ui_story_5080_50800202_13_dialog_content = "Boo-hoo—",
  ui_story_5080_50800202_14_dialog_content = "Let's just put down the weapons and figure out what's going on, okay?",
  ui_story_5080_50800202_15_dialog_content = "I'm the one who provoked the Demon King's Minion. I'll take full responsibility, so just let my friends go!",
  ui_story_5080_50800202_16_dialog_content = "...",
  ui_story_5080_50800202_17_dialog_content = "What's going on here, Zeta?",
  ui_story_5080_50800202_18_dialog_content = "It all started with the legend of Zeta, the greatest warrior of all time—",
  ui_story_5080_50800202_19_dialog_content = "After painstakingly practicing the art of racing, I was still unable to defeat the Witch of the Racetrack in a contest of speed.",
  ui_story_5080_50800202_20_dialog_content = "I was sure it had something to do with her having the Last Caelestite as an ally, so I decided to search for a powerful comrade of my own.",
  ui_story_5080_50800202_21_dialog_content = "That was when I found Barbara, the <color=#FFB400>Supernova Songstress</color> and Regina arguing about some kind of singing competition!",
  ui_story_5080_50800202_22_dialog_content = "\"O mighty warrior Zeta, please lend me your strength!\"",
  ui_story_5080_50800202_23_dialog_content = "\"With you by my side, I can draw a greater crowd than Regina could ever hope for! My audience is the source of my power!\"",
  ui_story_5080_50800202_24_dialog_content = "\"Sounds like a good time! Just don't forget about me: Zeta's loyal <color=#FFB400>Weapon Master</color>!\"",
  ui_story_5080_50800202_25_dialog_content = "Ah! Could these be the allies I seek? They must have been drawn in by my majesty!",
  ui_story_5080_50800202_26_dialog_content = "And so, we set off on our glorious journey to tour the furious desert and gather even more fans!",
  ui_story_5080_50800202_27_dialog_content = "And with our latest and greatest invention, the <color=#FFB400>Rediesel Super Idol-mobile</color>, we rode into battle—",
  ui_story_5080_50800202_28_dialog_content = "What? Could you please just get to the important part?!",
  ui_story_5080_50800202_29_dialog_content = "... Sigh.",
  ui_story_5080_50800202_30_dialog_content = "As our party ventured through the desert with our song burning in our hearts, I suddenly noticed something!",
  ui_story_5080_50800202_31_dialog_content = "A lone falcon perched atop the sands.",
  ui_story_5080_50800202_32_dialog_content = "\"I bet we could use this little guy for lighting or sound!\"",
  ui_story_5080_50800202_33_dialog_content = "Those were my Weapon Master's words—But I could see its true strength for myself.",
  ui_story_5080_50800202_34_dialog_content = "So I decided to bring the eagle along as a member of our party!",
  ui_story_5080_50800202_35_dialog_content = "But not long afterward, a wicked being came chasing after the eagle. She was relentless in her pursuit, and she even attacked us.",
  ui_story_5080_50800202_36_dialog_content = "Her shots were some of the most fearsome I've ever seen. I was too scared to stop the car... I mean, I was too scared for the safety of my companions!",
  ui_story_5080_50800202_37_dialog_content = "So you crashed full-speed into our home?!",
  ui_story_5080_50800202_38_dialog_content = "I-I had faith that the Cursed Warrior would be able to stop us in time!",
  ui_story_5080_50800202_39_dialog_content = "Heavens, Zeta...",
  ui_story_5080_50800202_40_dialog_content = "... I've had enough.",
  ui_story_5080_50800202_41_dialog_content = "Return <color=#FFB400>Eagle Hunter Three</color> to me right now.",
  ui_story_5080_50800301_1_dialog_content = "So its name is <color=#FFB400>Eagle Hunter Three</color>, huh... That's such a cool name!",
  ui_story_5080_50800301_2_dialog_content = "Fine... Seeing as how <color=#FFB400>Eagle Hunter Three</color> already has an owner, I'll give it back... Just stop fighting, please...",
  ui_story_5080_50800301_3_dialog_content = "Hey! Where do you think you're going?!",
  ui_story_5080_50800301_4_dialog_content = "You're not just gonna walk away after wrecking our camp and hurting these poor kids, are you?!",
  ui_story_5080_50800301_5_dialog_content = "Regardless of what you say, they're the ones who stole <color=#FFB400>Eagle Hunter Three</color> from me first.",
  ui_story_5080_50800301_6_dialog_content = "That may be, but we Rediesel bandits got each other's backs no matter what.",
  ui_story_5080_50800301_7_dialog_content = "So you still want to fight?",
  ui_story_5080_50800301_8_dialog_content = "Give it a rest already, you two!",
  ui_story_5080_50800301_9_dialog_content = "What's going on out here? The whole place is a mess and everyone looks so nervous!",
  ui_story_5080_50800301_10_dialog_content = "J-Jeriah?!",
  ui_story_5080_50800301_11_dialog_content = "And just what are you doing here, huh?",
  ui_story_5080_50800301_12_dialog_content = "It's not like I wanted to come... But didn't you hear the volcano rumbling just now, Sinsa?",
  ui_story_5080_50800301_13_dialog_content = "The Roaring Volcano has awakened, just like it did <color=#FFB400>fifteen years ago</color>.",
  ui_story_5080_50800301_14_dialog_content = "What?",
  ui_story_5080_50800301_15_dialog_content = "Hey boss! Are you alright?",
  ui_story_5080_50800301_16_dialog_content = "We finally cleared out most of the wreckage out there. Is everyone okay?",
  ui_story_5080_50800301_17_dialog_content = "Tiny One! Barbara! Zeta! Where are you three?",
  ui_story_5080_50800301_18_dialog_content = "Don't just come barging in, you guys!",
  ui_story_5080_50800301_19_dialog_content = "We're talking about important stuff! Hey! Knock it off, you idiots—!!!",
  ui_story_5080_50800301_20_dialog_content = "They're saying the Roaring Volcano is awake again. Is it true?",
  ui_story_5080_50800301_21_dialog_content = "Are you okay, Zeta? You're not hurt, are you?",
  ui_story_5080_50800301_22_dialog_content = "Nope! I'm perfectly fine, Princess Kindheart!",
  ui_story_5080_50800301_23_dialog_content = "Even I heard the rumbling just now. There's no doubt about it: the Roaring Volcano is active once again.",
  ui_story_5080_50800301_24_dialog_content = "The last time it erupted was during the <color=#FFB400>Darkover Crisis</color>, and it's been dormant ever since. What could have happened—",
  ui_story_5080_50800301_25_dialog_content = "<size=45>All of you shut up already!!!</size>",
  ui_story_5080_50800301_26_dialog_content = "Damn it, where'd that Illumina jerk go?!",
  ui_story_5080_50800301_27_dialog_content = "Huh? What Illumina jerk? You're not talking about me, are you?",
  ui_story_5080_50800301_28_dialog_content = "Huff—Huff—",
  ui_story_5080_50800301_29_dialog_content = "*gasping* We... should be safe... here.",
  ui_story_5080_50800301_30_dialog_content = "D-Don't talk, just try to catch your breath.",
  ui_story_5080_50800301_31_dialog_content = "That was close. If we weren't on good terms with Sinsa, that would've been an even bigger disaster.",
  ui_story_5080_50800301_32_dialog_content = "Thankfully, your quick thinking allowed us to escape while he was distracted.",
  ui_story_5080_50800301_33_dialog_content = "... I had a feeling those people would be unreasonable.",
  ui_story_5080_50800301_34_dialog_content = "After all, they're nothing but bandits and deserters.",
  ui_story_5080_50800301_35_dialog_content = "That's not it!",
  ui_story_5080_50800301_36_dialog_content = "The Rediesel Wrenches aren't that bad... If we had just approached Sinsa nicely, he would've been perfectly reasonable!",
  ui_story_5080_50800301_37_dialog_content = "They've been living in the Rediesel Desert for years too. If anyone knows more about the Freebird Squad, it's them...",
  ui_story_5080_50800301_38_dialog_content = "Debating the credibility of a bunch of deserters is pointless, so let's just drop it.",
  ui_story_5080_50800301_39_dialog_content = "While you were gathering intel in their camp, I managed to find tracks of our target. Come with me.",
  ui_story_5080_50800301_40_dialog_content = "You could at least hear me out...",
  ui_story_5080_50800301_41_dialog_content = "Take a look. The sand here has been scorched, and the area has traces of volcanic ash.",
  ui_story_5080_50800301_42_dialog_content = "There's no mistake. It's just up ahead.",
  ui_story_5080_50800301_43_dialog_content = "But... There are multiple sets of tracks.",
  ui_story_5080_50800301_44_dialog_content = "It's possible that our target has already reproduced itself. Stay alert.",
  ui_story_5080_50800301_45_dialog_content = "Targets sighted, Captain!",
  ui_story_5080_50800301_X45_dialog_content = "Graah... Urk—",
  ui_story_5080_50800301_46_dialog_content = "Is this... lava? No, they're Eclipsites!",
  ui_story_5080_50800301_47_dialog_content = "They're completely different than anything we've ever seen before. They look like walking piles of lava...",
  ui_story_5080_50800301_48_dialog_content = "You're right, and their strange appearance makes it hard to pinpoint their weak parts.",
  ui_story_5080_50800301_49_dialog_content = "With that intense heat protecting them, I doubt ranged attacks will have much of an effect.",
  ui_story_5080_50800301_50_dialog_content = "Prepare for battle.",
  ui_story_5080_50800301_51_dialog_content = "But...",
  ui_story_5080_50800301_52_dialog_content = "Your strength is more than a match for them, White Lancer. Since you're best suited to fighting head-on, you'll stand at the front of our formation.",
  ui_story_5080_50800301_53_dialog_content = "Sorry, but you still have no authority over me.",
  ui_story_5080_50800301_54_dialog_content = "You can summon the power of a flying steed, right? You should use it to launch surprise aerial attacks during combat.",
  ui_story_5080_50800301_55_dialog_content = "Judging from the composition of their bodies, it seems difficult for them to maintain their full-body protection. Finding even the smallest break in their defenses will make your attacks fatal.",
  ui_story_5080_50800301_56_dialog_content = "...",
  ui_story_5080_50800301_57_dialog_content = "While White Lancer engages the Eclipsites in combat, Hatchling Two, use your Rapid Torrent to attack them from afar.",
  ui_story_5080_50800301_58_dialog_content = "Regardless of type, all Eclipsites will expose their weak points when under heavy attack. That will be your moment to strike.",
  ui_story_5080_50800301_59_dialog_content = "They're sure to lose balance as soon as we exploit their weaknesses, which will allow White Lancer to go in for the killing blow.",
  ui_story_5080_50800301_60_dialog_content = "Roger!",
  ui_story_5080_50800301_61_dialog_content = "The Eagle Hunters and I will provide suppressive fire and funnel the Eclipsites towards White Lancer.",
  ui_story_5080_50800301_62_dialog_content = "The constant firepower should prevent them from grouping together, making it easier to pick them off one by one.",
  ui_story_5080_50800301_63_dialog_content = "That's quite the strategy... We'll do as you say then.",
  ui_story_5080_50800301_64_dialog_content = "(Even though she's only seen them in combat once, Rachel knows exactly their abilities and how to use them to their fullest potential...)",
  ui_story_5080_50800301_65_dialog_content = "Caelestite One.",
  ui_story_5080_50800301_66_dialog_content = "Yes!",
  ui_story_5080_50800301_67_dialog_content = "You'll be in charge of commanding this battle.",
  ui_story_5080_50800301_68_dialog_content = "Huh?",
  ui_story_5080_50800301_69_dialog_content = "Even the most thorough combat preparations can be rendered useless in the heat of battle.",
  ui_story_5080_50800301_70_dialog_content = "Your unique ability to perceive light trails makes you a far more capable commander for this fight.",
  ui_story_5080_50800301_71_dialog_content = "... Not only that, you three have plenty of experience fighting as a team.",
  ui_story_5080_50800301_72_dialog_content = "If anyone should lead them into battle... It's you.",
  ui_story_5080_50800301_73_dialog_content = "Rachel, you...",
  ui_story_5080_50800301_74_dialog_content = "That's \"Captain\" to you.",
  ui_story_5080_50800301_75_dialog_content = "Now prepare for battle, Caelestite One!",
  ui_story_5080_50800302_1_dialog_content = "Look out, Captain!",
  ui_story_5080_50800302_2_dialog_content = "Urgh... Now, White Lancer!",
  ui_story_5080_50800302_3_dialog_content = "Piercing Veils!",
  ui_story_5080_50800302_4_dialog_content = "Oh no, the Captain's injured! We have to...",
  ui_story_5080_50800302_5_dialog_content = "Focus on the battle, Hatchling Two! There's still another Eclipsite going towards you!",
  ui_story_5080_50800302_6_dialog_content = "Eagle Hunter One, Eagle Hunter Two, prepare to intercept!",
  ui_story_5080_50800302_7_dialog_content = "Graaaaah—!",
  ui_story_5080_50800302_8_dialog_content = "... Just in time.",
  ui_story_5080_50800302_9_dialog_content = "That was close... I think we got the last of them.",
  ui_story_5080_50800302_10_dialog_content = "What was that just now, Hatchling Two?",
  ui_story_5080_50800302_11_dialog_content = "I...",
  ui_story_5080_50800302_12_dialog_content = "Do not let your emotions cloud your judgment, soldier.",
  ui_story_5080_50800302_13_dialog_content = "Even if I get hurt, the mission comes before anything else. Remember that.",
  ui_story_5080_50800302_14_dialog_content = "We wiped out an entire squadron of powerful Eclipsites. This wound is the smallest price we could have paid for our victory.",
  ui_story_5080_50800302_15_dialog_content = "Tell me... after spending so much time with your friends, have you forgotten what it means to be a soldier of Illumina?",
  ui_story_5080_50800302_16_dialog_content = "N-No, ma'am... That's not it at all.",
  ui_story_5080_50800302_17_dialog_content = "You're being way too harsh, Rachel. Vice was just worried about you.",
  ui_story_5080_50800302_18_dialog_content = "... Code names, Caelestite One. Losing your focus on the battlefield could have dire consequences. What if she had gotten injured just now as well?",
  ui_story_5080_50800302_19_dialog_content = "If you follow my instructions and the mission still results in failure, then the blame falls on me.",
  ui_story_5080_50800302_20_dialog_content = "I take full responsibility for the safety and well-being of my subordinates... So long as you put your trust in me.",
  ui_story_5080_50800302_21_dialog_content = "As a veteran captain, everything you said just now is entirely true.",
  ui_story_5080_50800302_22_dialog_content = "I understand and agree with your way of thinking.",
  ui_story_5080_50800302_23_dialog_content = "Carleen?",
  ui_story_5080_50800302_24_dialog_content = "Oh... Vice, are you alright?",
  ui_story_5080_50800302_25_dialog_content = "Uh-huh...",
  ui_story_5080_50800302_26_dialog_content = "These Eclipsites... Take a look at their corpses...",
  ui_story_5080_50800302_27_dialog_content = "Captain, you're still bleeding...",
  ui_story_5080_50800302_28_dialog_content = "Just let her be. She won't listen to you anyway.",
  ui_story_5080_50800302_29_dialog_content = "She's carrying a weight that none of us can comprehend.",
  ui_story_5080_50800302_30_dialog_content = "I know the look in her eyes all too well. I've seen it so many times back in Lumopolis...",
  ui_story_5080_50800302_31_dialog_content = "I've been fighting on the front lines for a long time now, and I've seen more Eclipsites than I can count.",
  ui_story_5080_50800302_32_dialog_content = "But I've never encountered Eclipsites like this before.",
  ui_story_5080_50800302_33_dialog_content = "Judging from their heads, these Eclipsites have been outside the Dark Zone for a very long time.",
  ui_story_5080_50800302_34_dialog_content = "Furthermore, their anatomy indicates that their evolution was not geared towards combat.",
  ui_story_5080_50800302_35_dialog_content = "Their flesh is highly heat-resistant, and their bodies can store significant amounts of energy... These Eclipsites evolved in order to adapt to their environment.",
  ui_story_5080_50800302_36_dialog_content = "Strangely enough, their corpses remain for much longer than those of other Eclipsites...",
  ui_story_5080_50800302_37_dialog_content = "... I noticed something too. They all look remarkably similar.",
  ui_story_5080_50800302_38_dialog_content = "Very perceptive of you to notice... Aside from your emotional tendencies, you are a worthy reconnaissance captain.",
  ui_story_5080_50800302_39_dialog_content = "Sorry, but what do you mean by \"remarkably similar\"? Don't most Eclipsites look alike?",
  ui_story_5080_50800302_40_dialog_content = "I'd say the other Eclipsites are exactly the same.",
  ui_story_5080_50800302_41_dialog_content = "Many soldiers thought that Eclipsites don't reproduce in the normal sense.",
  ui_story_5080_50800302_42_dialog_content = "These Eclipsites, on the other hand, appear to have descended from a common ancestor... they look alike, but they aren't exactly the same.",
  ui_story_5080_50800302_43_dialog_content = "The traits they possess are similar to those that are passed down from parents to offspring.",
  ui_story_5080_50800302_44_dialog_content = "Our records indicate that the last investigation into these Eclipsites was over thirty years ago.",
  ui_story_5080_50800302_45_dialog_content = "They're smaller than the ones observed back then, and less powerful too. This may be the result of some unknown form of reproduction...",
  ui_story_5080_50800302_46_dialog_content = "Correct.",
  ui_story_5080_50800302_47_dialog_content = "During the <color=#FFB400>Darkover Crisis</color>, plenty of people in the Rediesel Wrench saw these Eclipsites. Compared to the ones from before, the Eclipsites you defeated were almost comically weak.",
  ui_story_5080_50800302_48_dialog_content = "Jeriah?! How is this—don't just show up like a this!",
  ui_story_5080_50800302_49_dialog_content = "Well, I'm assigned to this entire desert after all.",
  ui_story_5080_50800302_50_dialog_content = "You... How did you slip past Eagle Hunter Three's detection?",
  ui_story_5080_50800302_51_dialog_content = "Oh, is that the name of your drone? It appears to be malfunctioning a little.",
  ui_story_5080_50800302_52_dialog_content = "What? Eagle Hunter Three, return!",
  ui_story_5080_50800302_53_dialog_content = "Still, I never expected to hear the volcano rumble like it did fifteen years ago or see these guys again...",
  ui_story_5080_50800302_54_dialog_content = "What do you know about them?",
  ui_story_5080_50800302_55_dialog_content = "Heheh, I'm here looking for <color=#FFB400>answers</color>, same as you.",
  ui_story_5080_50800302_56_dialog_content = "Eagle Hunter Three's transmitter has been damaged. There's also something strange attached to it...",
  ui_story_5080_50800302_57_dialog_content = "Hello? Can you guys hear me? Hellooo—",
  ui_story_5080_50800302_58_dialog_content = "That voice...",
  ui_story_5080_50800302_59_dialog_content = "Zeta?",
  ui_story_5080_50800302_60_dialog_content = "Thanks to my brilliant <color=#FFB400>Weapon Master</color>, we were able to take this, uh... What did you call it again?",
  ui_story_5080_50800302_61_dialog_content = "Oh right, we \"hacked\" it! What a cool-sounding thing to do... Anyway, we hacked your drone and attached this communicator to it.",
  ui_story_5080_50800302_62_dialog_content = "If you want us to <color=#FFB400>fix it</color>, meet us at the home of Jeriah the Enchantress.",
  ui_story_5080_50800302_63_dialog_content = "... Don't look at me! Do you really think I would've come up with a name like that?",
  ui_story_5080_50800302_64_dialog_content = "The enemy has tampered with Eagle Hunter Three. I need to repair it right away—",
  ui_story_5080_50800302_65_dialog_content = "!!!",
  ui_story_5080_50800302_66_dialog_content = "My toolkit... When did it get incinerated?!",
  ui_story_5080_50800302_67_dialog_content = "You were so focused on the mission earlier that when you got hurt, your toolkit also got scorched.",
  ui_story_5080_50800302_68_dialog_content = "They said they're waiting for us at your home. What's your connection to all of this, Courier?",
  ui_story_5080_50800302_69_dialog_content = "Like I said, I just came looking for answers. I'm not here for any other reason.",
  ui_story_5080_50800302_70_dialog_content = "However, I sense a very familiar presence from you.",
  ui_story_5080_50800302_71_dialog_content = "Why don't we all go back together? We may even find a few more answers if we do.",
  ui_story_5080_50800302_72_dialog_content = "...",
  ui_story_5080_50800302_73_dialog_content = "Jeriah's a senior member of the Courier Union. We can trust her.",
  ui_story_5080_50800302_74_dialog_content = "Then let's go.",
  ui_story_5080_50800401_1_dialog_content = "Sorry for putting you out like this, Jeriah.",
  ui_story_5080_50800401_2_dialog_content = "Don't worry about it, now have a seat. This isn't the first time anyway.",
  ui_story_5080_50800401_3_dialog_content = "Hmm...",
  ui_story_5080_50800401_4_dialog_content = "Ah! Get down! The Rediesel Wrench's camp is just up ahead!",
  ui_story_5080_50800401_5_dialog_content = "Don't worry, they have their hands full right now.",
  ui_story_5080_50800401_6_dialog_content = "Argh, this thing's completely busted!!! Zeta, you little monster... Just wait till I get my hands on you!!!",
  ui_story_5080_50800401_7_dialog_content = "Hey, isn't that Jeriah's car? Hey, Jeriah! Food's ready, if you want to grab a bite with us!",
  ui_story_5080_50800401_8_dialog_content = "Next time!",
  ui_story_5080_50800401_9_dialog_content = "Suit yourself! I'll just go ask Azure then.",
  ui_story_5080_50800401_10_dialog_content = "Slow down a little, Jeriah. There are lots of traps up ahead.",
  ui_story_5080_50800401_11_dialog_content = "Thanks for the reminder.",
  ui_story_5080_50800401_12_dialog_content = "Yo Jeriah, take a look at this book! Does it really say \"How to Become the Boss of the Rediesel Wrench\" on the cover? Those jerks better not be messing with me just because I can't read too well!",
  ui_story_5080_50800401_13_dialog_content = "Of course it doesn't say that. If you want them to stop, then learn how to read.",
  ui_story_5080_50800401_14_dialog_content = "Thanks again for bringing us those tools on your last run, Jeriah. I'll squeeze you in sometime this week to work on your car.",
  ui_story_5080_50800401_15_dialog_content = "Sounds like a deal.",
  ui_story_5080_50800401_16_dialog_content = "Jeriah... I think you've changed since the last time I saw you.",
  ui_story_5080_50800401_17_dialog_content = "You used to live in such a hard-to-find place, but now you're on friendly terms with everyone in the Rediesel Wrench.",
  ui_story_5080_50800401_18_dialog_content = "Heheh, how good of you to notice, PlayerName.",
  ui_story_5080_50800401_19_dialog_content = "Everyone changes over time.",
  ui_story_5080_50800401_20_dialog_content = "Thanks to you, I've also started to think about building connections with others.",
  ui_story_5080_50800401_21_dialog_content = "... H-Hey, Vice? It's a little tight back here—",
  ui_story_5080_50800401_22_dialog_content = "If you want your music to reach every corner of the world, then you should play it loud, loud, LOUD!",
  ui_story_5080_50800401_23_dialog_content = "Go ahead, do your best! The loudest person in the room is always the dumbest!",
  ui_story_5080_50800401_24_dialog_content = "Failure, frustration, and fear made you run from me!",
  ui_story_5080_50800401_25_dialog_content = "And nothing makes me madder than a coward!",
  ui_story_5080_50800401_26_dialog_content = "Zeta's not good at driving just yet! But a true friend would never get upset!",
  ui_story_5080_50800401_27_dialog_content = "Is something wrong, Vice? You look unwell...",
  ui_story_5080_50800401_28_dialog_content = "I-It's nothing... Captain, you really shouldn't try to change your bandages on such a bumpy car ride.",
  ui_story_5080_50800401_29_dialog_content = "I can tend to your wounds once we arrive, so please don't push yourself.",
  ui_story_5080_50800401_30_dialog_content = "It's fine, I'm used to working alone.",
  ui_story_5080_50800401_31_dialog_content = "This is nothing... Besides, there's no need to be so polite. I'm not much older than you.",
  ui_story_5080_50800401_32_dialog_content = "You're only a year younger than me, yet you've already managed to become an outstanding captain. There's no need to be so respectful.",
  ui_story_5080_50800401_33_dialog_content = "You're an Illumina scout, yes? From your clothes, I assume you're also an elite soldier.",
  ui_story_5080_50800401_34_dialog_content = "I can tell that you're different from the other little birds. You're a true bird of prey, aren't you?",
  ui_story_5080_50800401_35_dialog_content = "What kind of mission would require the services of someone like you?",
  ui_story_5080_50800401_36_dialog_content = "That's highly classified, and also none of your business.",
  ui_story_5080_50800401_37_dialog_content = "I hate to say it, but fate can be so unpredictable at times.",
  ui_story_5080_50800401_38_dialog_content = "Well, I'm sure there's a good reason for a hunter such as yourself to appear in a place like this.",
  ui_story_5080_50800401_39_dialog_content = "Look, young Sinsa, those <color=#FFB400>tracks</color> again.",
  ui_story_5080_50800401_40_dialog_content = "They're just like the ones Kafka found. These must be the <color=#FFB400>tracks</color> Jeriah was talking about before.",
  ui_story_5080_50800401_41_dialog_content = "I told you not to call me that... Anyway, these tracks are just globs of lava, aren't they?",
  ui_story_5080_50800401_42_dialog_content = "Why would there be lava in a place like this?",
  ui_story_5080_50800401_43_dialog_content = "Maybe we'll find out more if we keep going?",
  ui_story_5080_50800401_44_dialog_content = "Hey, Roy! These are Eclipsite remains, aren't they? They've been torn to pieces, but there's no denying it, right?",
  ui_story_5080_50800401_45_dialog_content = "Someone took them out... But what's even stranger is that their bodies still haven't disappeared.",
  ui_story_5080_50800401_46_dialog_content = "Take a good look at 'em, Roy. Are they the same as <color=#FFB400>the Eclipsite</color> you saw back then?",
  ui_story_5080_50800401_47_dialog_content = "Fifteen years ago, when we were trying to escape... When <color=#FFB400>the boss</color> tried to buy us more time before <color=#FFB400>that Eclipsite</color>...",
  ui_story_5080_50800401_48_dialog_content = "You're the only one who can confirm it.",
  ui_story_5080_50800401_49_dialog_content = "They look similar to <color=#FFB400>that Eclipsite</color> but are not the same. If anything, they look like its <color=#FFB400>descendants</color>.",
  ui_story_5080_50800401_50_dialog_content = "Damned monster... So it's been reproducing all these years, huh?",
  ui_story_5080_50800401_51_dialog_content = "Time to go hunting! We'll track <color=#FFB400>that thing</color> back to its nest and destroy it once and for all!",
  ui_story_5080_50800401_52_dialog_content = "We're in the volcano's vicinity, and the temperature is definitely much hotter. Looks like young Jeriah was right—the volcano really is awake again.",
  ui_story_5080_50800401_53_dialog_content = "Why do the tracks just disappear here?",
  ui_story_5080_50800401_54_dialog_content = "These footprints belong to different Eclipsites... Maybe they messed things up.",
  ui_story_5080_50800401_55_dialog_content = "The Roaring Volcano is actually located deep underground. There could be even more paths hidden just beneath our feet.",
  ui_story_5080_50800401_56_dialog_content = "And without a clear target in sight, running blind would be too dangerous.",
  ui_story_5080_50800401_57_dialog_content = "Quit hiding already, you giant coward! Come out and face me!",
  ui_story_5080_50800401_58_dialog_content = "I'm not the same snot-nosed punk from fifteen years ago, now show yourself! It's time to end to this!!!",
  ui_story_5080_50800401_59_dialog_content = "Damn it!!!",
  ui_story_5080_50800401_60_dialog_content = "Stop it, Sinsa! This whole place could come crashing down any second—Ahhh—!",
  ui_story_5080_50800401_61_dialog_content = "<color=#e8d9bb>The walls tremble as Sinsa's punches echo deeper into the cave. Soon, the shuffling of countless Eclipsites can be heard.</color>",
  ui_story_5080_50800401_62_dialog_content = "The cave's about to collapse, but it sounds like our old friend is finally coming out to greet us!",
  ui_story_5080_50800401_63_dialog_content = "Look over there, Roy! That's them, isn't it?",
  ui_story_5080_50800401_64_dialog_content = "Took 'em long enough to show up! Their nest must be close by!",
  ui_story_5080_50800401_65_dialog_content = "Be careful, young Sinsa... Let's make this quick.",
  ui_story_5080_50800401_66_dialog_content = "Hmph, I'm not stopping until my wrench has had its fill. Let's go, Roy!",
  ui_story_5080_50800402_1_dialog_content = "Come in and make yourselves at home. I don't have much, since I almost never have people over—",
  ui_story_5080_50800402_2_dialog_content = "Behold! A masterpiece by the one and only Zeta!",
  ui_story_5080_50800402_3_dialog_content = "Wow! It's so lifelike!",
  ui_story_5080_50800402_4_dialog_content = "Ha! This is nothing for a legendary warrior like myself!",
  ui_story_5080_50800402_5_dialog_content = "Breaking in and putting up a bunch of drawings again, I see?",
  ui_story_5080_50800402_6_dialog_content = "Your home is way too old-fashioned, Enchantress! Take this wonderful drawing to liven up your living space with a bigger smile, as it's a courtesy of the legendary Zeta!",
  ui_story_5080_50800402_7_dialog_content = "... Never mind. Just try not to break anything.",
  ui_story_5080_50800402_8_dialog_content = "And stop calling me Enchantress already. If anyone deserves that title, it's Miss Naroxel.",
  ui_story_5080_50800402_9_dialog_content = "I've never met her, but her name sounds super cool! Oh, by the way, here's your mail!",
  ui_story_5080_50800402_10_dialog_content = "We sorted out that messy stack of envelopes and threw the trash for you.",
  ui_story_5080_50800402_11_dialog_content = "Really? How very kind of you.",
  ui_story_5080_50800402_12_dialog_content = "Heehee, it's only right that I properly repay you for all the quest rewards you've given me!",
  ui_story_5080_50800402_13_dialog_content = "Sure, now could you please stop getting paint on the mail? As for the rest of you, don't just stand there. Have a seat.",
  ui_story_5080_50800402_14_dialog_content = "You've really changed a lot, Jeriah... You seem much happier now that you've made connections with so many other people.",
  ui_story_5080_50800402_15_dialog_content = "And I couldn't be happier for you!",
  ui_story_5080_50800402_16_dialog_content = "Is that so? These kids can be a handful sometimes, but at least my days aren't so boring anymore.",
  ui_story_5080_50800402_17_dialog_content = "Eagle Hunter Three is a bionic drone with both combat and reconnaissance capabilities, and is the product of Illumina's most cutting-edge technology... Are you sure you two can fix it?",
  ui_story_5080_50800402_18_dialog_content = "Just leave it to my Weapon Master!",
  ui_story_5080_50800402_19_dialog_content = "Let's start with a little poke test. Left, right, left... Yep, it looks like the transmitter was busted by excessive impact.",
  ui_story_5080_50800402_20_dialog_content = "See? Nothing's outside the reach of our proud Weapon Master's abilities!",
  ui_story_5080_50800402_21_dialog_content = "Well then? Can you do it?",
  ui_story_5080_50800402_22_dialog_content = "I'll definitely try my best!",
  ui_story_5080_50800402_23_dialog_content = "Lend me your tools. I should be able to help as well.",
  ui_story_5080_50800402_24_dialog_content = "These drones are my partners in combat... I'm not willing to hand them over so easily.",
  ui_story_5080_50800402_25_dialog_content = "Don't be so worried, Eagle Huntershot the Hero of Neutrality!",
  ui_story_5080_50800402_26_dialog_content = "...",
  ui_story_5080_50800402_27_dialog_content = "Don't mind Zeta, that's just how she is.",
  ui_story_5080_50800402_28_dialog_content = "Now that I know these eagles are your cherished companions, I wouldn't lay a finger on them.",
  ui_story_5080_50800402_29_dialog_content = "It's my fault this one was injured, so please let me take care of it for you!",
  ui_story_5080_50800402_30_dialog_content = "But you're making Tiny One do all the work...",
  ui_story_5080_50800402_31_dialog_content = "W-We meet again, the Last Caelestite! I see destiny has favored you with yet another powerful ally!",
  ui_story_5080_50800402_32_dialog_content = "You could talk normally to me, you know?",
  ui_story_5080_50800402_33_dialog_content = "But I, the legendary warrior Zeta, haven't given up hope yet!",
  ui_story_5080_50800402_34_dialog_content = "As a Hero of Neutrality, if you can ally yourself with the Last Caelestite, then that means you can join me on my quest as well!",
  ui_story_5080_50800402_35_dialog_content = "If it means having a powerful warrior like you on my team, I'll even overlook your evil past!",
  ui_story_5080_50800402_36_dialog_content = "I...",
  ui_story_5080_50800402_37_dialog_content = "No need to say another word! I already know exactly what's on your mind!",
  ui_story_5080_50800402_38_dialog_content = "A proud warrior like you isn't easily convinced, I'm sure.",
  ui_story_5080_50800402_39_dialog_content = "But that's okay! You and I can fight on equal footing once my Weapon Master repairs your drone.",
  ui_story_5080_50800402_40_dialog_content = "And after I beat you fair and square... You'll become an invaluable addition to my party, and that witch will never stand a chance against me!",
  ui_story_5080_50800402_41_dialog_content = "Your oath sounds more like a declaration of war to me.",
  ui_story_5080_50800402_42_dialog_content = "Don't worry about her too much, Captain. Zeta just has a... different way of talking.",
  ui_story_5080_50800402_43_dialog_content = "Th-That's right, Captain. Once Eagle Hunter Three is fixed, we'll take our leave.",
  ui_story_5080_50800402_44_dialog_content = "It's fine.",
  ui_story_5080_50800402_45_dialog_content = "Hear that, Zeta? Now, why don't you apologize... Huh?",
  ui_story_5080_50800402_46_dialog_content = "Despite your affiliation with those Rediesel bandits...",
  ui_story_5080_50800402_47_dialog_content = "You don't seem aware of the past, so I'm willing to overlook it this time.",
  ui_story_5080_50800402_48_dialog_content = "You're still young, so don't let them corrupt you with their desert outlaw ways.",
  ui_story_5080_50800402_49_dialog_content = "Heheh, you seem to have the wrong idea! My dream is to become a legendary hero, and also the savior of the desert!",
  ui_story_5080_50800402_50_dialog_content = "I'm glad to hear you have such a noble goal. I didn't hurt you earlier, did I?",
  ui_story_5080_50800402_51_dialog_content = "Huh? N-Not at all! An attack like that couldn't even put a scratch on me! And I definitely wasn't crying out of fear or anything either!",
  ui_story_5080_50800402_52_dialog_content = "Good. You really are a brave warrior.",
  ui_story_5080_50800402_53_dialog_content = "Am I seeing things...?",
  ui_story_5080_50800402_54_dialog_content = "She just handled Zeta perfectly.",
  ui_story_5080_50800402_55_dialog_content = "... I didn't know she could be like this.",
  ui_story_5080_50800402_56_dialog_content = "Maybe she's exactly as you described her earlier, Carleen. It makes sense for an experienced and mature captain to take care of her subordinates.",
  ui_story_5080_50800402_57_dialog_content = "But...",
  ui_story_5080_50800402_58_dialog_content = "(Is this the real her? If so, then why is she so cold towards us?)",
  ui_story_5080_50800402_59_dialog_content = "(Is she suppressing her emotions for the sake of the mission? Or... could she be hiding a deeper kind of pain?)",
  ui_story_5080_50800402_60_dialog_content = "Interesting. I've seen birds of all shapes and sizes pass through the desert on their migratory routes, but this is the first time I've ever seen a falcon that could put away its talons.",
  ui_story_5080_50800402_61_dialog_content = "Uh, Zeta? This drone's crevices are full of sand, which explains why some of the circuit were fried.",
  ui_story_5080_50800402_62_dialog_content = "I'm not used to working on finely-tuned stuff like this. Fixing it won't be easy.",
  ui_story_5080_50800402_63_dialog_content = "Wh-What?",
  ui_story_5080_50800402_64_dialog_content = "If you can't do it, then hand me the tools so I can take care of it.",
  ui_story_5080_50800402_65_dialog_content = "N-Now just hold on a second!",
  ui_story_5080_50800402_66_dialog_content = "I gave my word as a proud warrior that I'd take full responsibility for this! How else are we supposed to have our epic battle?!",
  ui_story_5080_50800402_67_dialog_content = "You can't burn out before taking the first step. You're not giving up, are you?",
  ui_story_5080_50800402_68_dialog_content = "You know who's great at this kind of work? Odi the Machine Maniac! You don't wanna lose to her, do you?!",
  ui_story_5080_50800402_69_dialog_content = "Wha... What did you say?!",
  ui_story_5080_50800402_70_dialog_content = "Stand back and watch, all of you! This job's nothing for the likes of me!",
  ui_story_5080_50800402_71_dialog_content = "I'll have this thing fixed in a jiffy! Odi's skills don't even compare to mine!",
  ui_story_5080_50800402_72_dialog_content = "I think I know how Zeta keeps roping Tiny One into her schemes now.",
  ui_story_5080_50800402_73_dialog_content = "It's getting late, and it doesn't look like the repairs will be done anytime soon. You should all just stay here for tonight.",
  ui_story_5080_50800402_74_dialog_content = "We wouldn't be intruding, would we?",
  ui_story_5080_50800402_75_dialog_content = "Don't worry, I'm used to \"intrusions\" like this now.",
  ui_story_5080_50800402_76_dialog_content = "Besides... I think I have much to discuss with a certain bird of prey.",
  ui_story_5080_50800500_1_dialog_content = "<color=#e8d9bb>As night descends on the desert, the temperature starts to plummet. Suddenly, a sand dune stirs in the seemingly-empty expanse.</color>",
  ui_story_5080_50800500_2_dialog_content = "<color=#e8d9bb>With a sputtering sound, a figure bursts out from under the sands!</color>",
  ui_story_5080_50800500_3_dialog_content = "Ach—Pfft!",
  ui_story_5080_50800500_4_dialog_content = "Pfft, pfft, pfft!",
  ui_story_5080_50800500_5_dialog_content = "*cough* R-Roy...! Are... Are you alright?",
  ui_story_5080_50800500_6_dialog_content = "Urgh... I'm too old for this sort of thing, young Sinsa. The next time you decide to bring a mountain crashing down on our heads, at least give me a heads-up!",
  ui_story_5080_50800500_7_dialog_content = "Heheh—It's been a while since we've cut loose like that, huh?",
  ui_story_5080_50800500_8_dialog_content = "Yes, but fun and games aside, we still don't know the exact location of their nest... And their numbers are no laughing matter either.",
  ui_story_5080_50800500_9_dialog_content = "It's fine, now let's head back to camp. If anyone asks, just tell them we took out the Eclipsites' nest and left it at that.",
  ui_story_5080_50800500_10_dialog_content = "But is that really okay? We killed plenty of Eclipsites, but it clearly wasn't all of them.",
  ui_story_5080_50800500_11_dialog_content = "With all the underground passages running through this place, it's possible that those molten monsters are nesting within the volcano.",
  ui_story_5080_50800500_12_dialog_content = "Then let's charge into that volcano!",
  ui_story_5080_50800500_13_dialog_content = "Is that really the best idea we've got?",
  ui_story_5080_50800500_14_dialog_content = "I'm worried the same kind of Eclipsite that killed our leader is still lurking in the volcano somewhere, one that's stronger than anything we've ever faced.",
  ui_story_5080_50800500_15_dialog_content = "We need to tell everyone immediately and ensure they're ready to fight when the time comes.",
  ui_story_5080_50800500_16_dialog_content = "If things get dangerous, of course, I'll let them know. But if we do come up against <color=#FFB400>that thing</color>, I can't let those little scamps get in harm's way.",
  ui_story_5080_50800500_17_dialog_content = "What's so different about it now? You were also just a snot-nosed punk back then, but now you're our leader.",
  ui_story_5080_50800500_18_dialog_content = "I get that feeling, but there's no way I'm tellin' everyone! Our beef with <color=#FFB400>that monster</color>? Nah, it's got nothin' to do with the rugrats back home!",
  ui_story_5080_50800500_19_dialog_content = "This wrench was passed on to me, along with that grudge. As leader, it falls to me to get revenge for our old boss and our fallen brothers. That's why...",
  ui_story_5080_50800500_20_dialog_content = "Promise me you won't say a thing, Roy.",
  ui_story_5080_50800500_21_dialog_content = "So you're doing it for the kids, huh? The boss said something like that in the past too.",
  ui_story_5080_50800500_22_dialog_content = "Even though we were lucky enough to escape, my heart's been filled with regret ever since.",
  ui_story_5080_50800500_23_dialog_content = "If we let the kids fight <color=#FFB400>that thing</color>, and they end up feeling the same helplessness and despair we did back then, they'll end up just like...",
  ui_story_5080_50800500_24_dialog_content = "No they won't, young Sinsa. After all we've been through, don't tell me you haven't seen how much they've grown?",
  ui_story_5080_50800500_25_dialog_content = "Yes, some of them are inexperienced or don't remember what happened back then, but those kids are already proud and full-fledged members of the Rediesel Wrench.",
  ui_story_5080_50800500_26_dialog_content = "Zeta was only two when she lost her parents. She was no taller than a tire back then, but now she's strong enough to rove the desert alone.",
  ui_story_5080_50800500_27_dialog_content = "Are you really going to deprive her of the opportunity to face her past?",
  ui_story_5080_50800500_28_dialog_content = "That's not what I meant. You know me better than that.",
  ui_story_5080_50800500_29_dialog_content = "I do, and I also know that you're too overbearing to let go of their hands.",
  ui_story_5080_50800500_30_dialog_content = "Do you remember what our old boss used to say? She believed that we should respect every decision a child makes, since every person is entitled to freedom.",
  ui_story_5080_50800500_31_dialog_content = "Now that the kids are all grown up, old folks like us need to learn how to let go.",
  ui_story_5080_50800500_32_dialog_content = "When the storm comes, we'll have to face it together instead of trying to shield them from it.",
  ui_story_5080_50800500_33_dialog_content = "The storm, huh...",
  ui_story_5080_50800500_34_dialog_content = "Sinsa! Roy!",
  ui_story_5080_50800500_35_dialog_content = "Eve? We were just talking about you. What are you doing here, huh?",
  ui_story_5080_50800500_36_dialog_content = "I was so worried about the two of you, so we came out here to find you.",
  ui_story_5080_50800500_37_dialog_content = "Come on, Sinsa! Let's go home!",
  ui_story_5080_50800500_38_dialog_content = "Roy... When the storm came back then, I didn't want to let go of Eve... Because I was afraid I would lose her...",
  ui_story_5080_50800500_39_dialog_content = "But in the end, she was the one who saved us both...",
  ui_story_5080_50800500_40_dialog_content = "No matter what happens, I'll never let go of my family. But... I think you might be right about these kids. They're a lot stronger than we could ever imagine.",
  ui_story_5080_50800500_41_dialog_content = "Yes, but that doesn't mean I have to bring them with me. They can help out by defending our home.",
  ui_story_5080_50800500_42_dialog_content = "Anyway, we can discuss the work arrangements after we get back... Hey, what's with the handkerchief?",
  ui_story_5080_50800500_43_dialog_content = "I'm so moved, young Sinsa... You've grown so much in the last fifteen years.",
  ui_story_5080_50800500_44_dialog_content = "Knock that off, you moron! I've been the leader of the Wrench for years now, so stop lumping me in with the other kids!",
  ui_story_5080_50800500_45_dialog_content = "What took you guys so long? Ah, never mind. It's chow time, so don't get in my way! Wait for me, Rabbie!",
  ui_story_5080_50800500_46_dialog_content = "What happened out there? You two look like you were rolling around in a furnace.",
  ui_story_5080_50800500_47_dialog_content = "Nothing happened, we just went to check out the volcano.",
  ui_story_5080_50800500_48_dialog_content = "Tch—I hear Azure's coming back soon. Next time you guys run off on your own, remember to bring us back some booze.",
  ui_story_5080_50800500_49_dialog_content = "Let's just eat already! I'm about to starve over here!",
  ui_story_5080_50800500_50_dialog_content = "Huh? Where are Zeta and Tiny One?",
  ui_story_5080_50800500_51_dialog_content = "No clue, but this lizard jerky is tops! Maybe they ran into some trouble and had to escape through a secret tunnel?",
  ui_story_5080_50800500_52_dialog_content = "I'm a little worried, considering how late it is.",
  ui_story_5080_50800500_53_dialog_content = "Hey Barbara, you were causing a ruckus with them earlier. Any idea where they went?",
  ui_story_5080_50800500_54_dialog_content = "Hmm... It was too hectic to remember anything clearly, but I think they left with Jeriah.",
  ui_story_5080_50800500_55_dialog_content = "She said something about recruiting a new member to her party. Could she mean that woman from before?",
  ui_story_5080_50800500_56_dialog_content = "She went with Jeriah, eh... If they want to look for that Illumina soldier, then I say let them be.",
  ui_story_5080_50800500_57_dialog_content = "But we hardly know anything about that woman. And with all this volcanic activity, it's too dangerous to just leave them alone out there...",
  ui_story_5080_50800500_58_dialog_content = "We'll go look for them. We're almost done eating.",
  ui_story_5080_50800500_59_dialog_content = "You'll need a good driver. I'm coming too!",
  ui_story_5080_50800500_60_dialog_content = "I suggest we...",
  ui_story_5080_50800500_61_dialog_content = "You sure you can drive at night without flipping the car over?",
  ui_story_5080_50800500_62_dialog_content = "Count me in! Besides, I don't need to eat much nowadays.",
  ui_story_5080_50800500_63_dialog_content = "I still think we should...",
  ui_story_5080_50800500_64_dialog_content = "I'll go too! My passionate singing will guide our little ones through the night!",
  ui_story_5080_50800500_65_dialog_content = "That's just because it'll be too loud and annoying to ignore.",
  ui_story_5080_50800500_66_dialog_content = "You wanna say that to my face?!",
  ui_story_5080_50800500_67_dialog_content = "Enough!",
  ui_story_5080_50800500_68_dialog_content = "I'll go find them, so all of you just shut up and eat!",
  ui_story_5080_50800500_69_dialog_content = "Dig in, everyone! Huh? Is something wrong with the food?",
  ui_story_5080_50800500_70_dialog_content = "Forgive me if I'm being rude, but does this really count as food... Huh?!",
  ui_story_5080_50800500_71_dialog_content = "Wow! This fried sandworm is a lot crispier than before!",
  ui_story_5080_50800500_72_dialog_content = "And this grilled snake tail is so tender and fresh!",
  ui_story_5080_50800500_73_dialog_content = "Why aren't you eating, Carleen? Don't worry, Vice and I felt the same way before, but this stuff's totally delicious!",
  ui_story_5080_50800500_74_dialog_content = "I-I appreciate your concern... But could you please hold that skewer a little further away from me?",
  ui_story_5080_50800500_75_dialog_content = "This flavor...!!!",
  ui_story_5080_50800500_76_dialog_content = "It's even better than our military's best canned rations!",
  ui_story_5080_50800500_77_dialog_content = "The Illumina Federation could treat its soldiers a little better, it seems...",
  ui_story_5080_50800500_78_dialog_content = "I didn't think you'd enjoy the Rediesel Desert's food so much, Captain.",
  ui_story_5080_50800500_79_dialog_content = "I'm not particularly interested in culinary pleasures, to be honest.",
  ui_story_5080_50800500_80_dialog_content = "Ahh, that hit the spot! Time to get back to work, so don't bother me!",
  ui_story_5080_50800500_81_dialog_content = "So you like honey-roasted sand rats just like me, huh?",
  ui_story_5080_50800500_82_dialog_content = "Heheh, even a sinister soldier from Illumina isn't beyond the saving grace of delicious food!",
  ui_story_5080_50800500_83_dialog_content = "If anyone is sinister, it's the Rediesel Wrench. I refuse to accept... that we have anything in common.",
  ui_story_5080_50800500_84_dialog_content = "(Huh? Why is she being so mean all of a sudden?)",
  ui_story_5080_50800500_85_dialog_content = "Really? Because I think it's great that we have something in common! Fear not, the legendary savior of the world will rescue you from your evil organization too!",
  ui_story_5080_50800500_86_dialog_content = "There will always be a seat for you in my vehicle!",
  ui_story_5080_50800500_87_dialog_content = "Sounds pretty cool, right? I've always wanted to say that!",
  ui_story_5080_50800500_88_dialog_content = "The Rediesel Wrench... is nothing but a disgraceful gang of deserters from Illumina.",
  ui_story_5080_50800500_89_dialog_content = "Not only did they forget their identity and honor, but they also fell into banditry and turned their guns on civilians.",
  ui_story_5080_50800500_90_dialog_content = "No one could ever approve of their actions. Not even... a child like you.",
  ui_story_5080_50800500_91_dialog_content = "I'm not a child, and we're nothing like that! You must be mistaking us for some other group!",
  ui_story_5080_50800500_92_dialog_content = "And letting innocent children like you fall into their hands is Illumina's fault, which is why we'll do everything we can to make things right.",
  ui_story_5080_50800500_93_dialog_content = "And by that, do you mean turning them over to Illumina's <color=#FFB400>Executioners</color>?",
  ui_story_5080_50800500_94_dialog_content = "What?! I've never heard of anything like that before...!",
  ui_story_5080_50800500_95_dialog_content = "Before this desert had a name, when the <color=#FFB400>Rediesel Wrench</color> still didn't exist, Illumina had its fair share of deserters who came to this place.",
  ui_story_5080_50800500_96_dialog_content = "Their desire for freedom led them to abandon Illumina and take refuge in this harsh and desolate land.",
  ui_story_5080_50800500_97_dialog_content = "But in the end, Illumina's <color=#FFB400>Executioners</color> pursued them into the desert and cut them down.",
  ui_story_5080_50800500_98_dialog_content = "No way...",
  ui_story_5080_50800500_99_dialog_content = "Illumina is the reason why the original settlers of this desert took up arms, and why they were so suspicious of one another.",
  ui_story_5080_50800500_100_dialog_content = "... But that was all in the past. The Grand Marshal of today doesn't condone these methods but advocates for a new system.",
  ui_story_5080_50800500_101_dialog_content = "Illumina no longer hunts down its deserters! So long as the Rediesel bandits lay down their arms and return peaceably, no one will be—",
  ui_story_5080_50800500_102_dialog_content = "During the Darkover Crisis, Sinsa and the others even went to Gannon City to provide reinforcements... A pity they were never properly repaid for their kindness.",
  ui_story_5080_50800500_103_dialog_content = "There must have been some kind of misunderstanding. I'm sure both sides could come to an agreement if they just discuss things reasonably.",
  ui_story_5080_50800500_104_dialog_content = "If possible... I would prefer not to hurt any of you. But as outsiders, it's impossible for you to understand the significance of desertion.",
  ui_story_5080_50800500_105_dialog_content = "One person's selfish decision could harm countless other people... It could ruin everything, as well as their families.",
  ui_story_5080_50800500_106_dialog_content = "(She seems strangely agitated right now... What could she be remembering?)",
  ui_story_5080_50800500_107_dialog_content = "Is that so? Why should a bird's wings be bound just because it is born in Illumina?",
  ui_story_5080_50800500_108_dialog_content = "I was born into the Rediesel Wrench, though I never truly fit in with them. Even so, I could tell that they were just a bunch of freedom-loving fools.",
  ui_story_5080_50800500_109_dialog_content = "I was allowed to leave and build a life for myself whenever I wanted. All of them have their choices to make as well.",
  ui_story_5080_50800500_110_dialog_content = "Asking them to return to Illumina and controlled by the system, stripped of their individuality. I can't imagine they would ever agree to that.",
  ui_story_5080_50800500_111_dialog_content = "That's not fair to say, I don't feel that way about Illumina at all!",
  ui_story_5080_50800500_112_dialog_content = "So we can't do whatever we want in Illumina? What about drag racing? Is drag racing still allowed?",
  ui_story_5080_50800500_113_dialog_content = "Well, the Undercities have lots of priceless and delicate machinery, so... no.",
  ui_story_5080_50800500_114_dialog_content = "That sounds awful! I'd never want to go there!",
  ui_story_5080_50800500_115_dialog_content = "I-It's really not that bad! We have all sorts of other competitions too! And you could always apply for transportation duty!",
  ui_story_5080_50800500_116_dialog_content = "Illumina's mission is to protect all Aurorians. Individual sacrifices are necessary for the sake of the whole.",
  ui_story_5080_50800500_117_dialog_content = "Oh, my little bird of prey. Illumina must have spared no effort to train such a steadfast soldier.",
  ui_story_5080_50800500_118_dialog_content = "There's no need to obfuscate things. I come from a long line of proud heroes, and my family's faith in Illumina is stronger than you could ever imagine.",
  ui_story_5080_50800500_119_dialog_content = "No sacrifice is too great for Illumina's splendor! Our lives are fleeting, but glory is eternal!",
  ui_story_5080_50800500_120_dialog_content = "And when all have been sacrificed, who will be left to remember the heroes?",
  ui_story_5080_50800500_121_dialog_content = "You say you come from a long line of heroes, but do you remember what your grandfather's grandfather accomplished? Or what he enjoyed in life?",
  ui_story_5080_50800500_122_dialog_content = "I'm sure you were told all about the greatness of your ancestors from a young age... But what do you really know about their existence?",
  ui_story_5080_50800500_123_dialog_content = "I...",
  ui_story_5080_50800500_124_dialog_content = "... While their acts of valor may be forgotten in time, the fruits of a hero's achievements will always remain.",
  ui_story_5080_50800500_125_dialog_content = "In a world overrun by the Eclipsites, we must continue to live, grow, and pass on our will... Just as countless fallen heroes have done before us. ",
  ui_story_5080_50800500_126_dialog_content = "Though I may not know all of them by name, their sacrifices and achievements live on through us, the inheritors of Astra.",
  ui_story_5080_50800500_127_dialog_content = "Those heroes have influenced me, giving me the determination to cross thousands of paths to get here... I have no regrets!",
  ui_story_5080_50800500_128_dialog_content = "Their tales and their existences will never truly disappear! They will continue to reach the hearts and lives of other people in more ways than we can imagine!",
  ui_story_5080_50800500_129_dialog_content = "Carleen...",
  ui_story_5080_50800500_130_dialog_content = "The princess of Lumopolis really knows how to give an excellent speech.",
  ui_story_5080_50800500_131_dialog_content = "White Lancer... You're absolutely right.",
  ui_story_5080_50800500_132_dialog_content = "Hey boss, aren't you gonna go in? You've been eavesdropping this whole time!",
  ui_story_5080_50800500_133_dialog_content = "Shhh! Quiet, Tiny one. I'm still trying to hear...",
  ui_story_5080_50800500_134_dialog_content = "White Lancer makes an excellent point! I... once belonged to a squad of loyal soldiers who gave their lives in the name of justice. They graced me with their kindness, and I will always be proud of it.",
  ui_story_5080_50800500_135_dialog_content = "Their example is one which deserves to be followed.",
  ui_story_5080_50800500_136_dialog_content = "That's right... Because if I don't, I...",
  ui_story_5080_50800500_137_dialog_content = "Huh? Where are you going, Captain—",
  ui_story_5080_50800500_138_dialog_content = "Just give her some space.",
  ui_story_5080_50800500_139_dialog_content = "Hmph... Zeta, Tiny One, let's go home.",
  ui_story_5080_50800500_140_dialog_content = "Th-The leader of the Rediesel bandits?! When did you...",
  ui_story_5080_50800500_141_dialog_content = "It's done! I fixed it! Ohhh, wait till Odi finds out I fixed something she's never worked on before!!!",
  ui_story_5080_50800500_142_dialog_content = "But <color=#FFB400>Cursed Warrior</color>... I'd really like to stay...",
  ui_story_5080_50800500_143_dialog_content = "... Then go ahead. You're all grown up after all. Keep an eye on these brats, would you, Jeriah?",
  ui_story_5080_50800500_144_dialog_content = "Wait! You... You know about that Eclipsite, don't you?",
  ui_story_5080_50800500_145_dialog_content = "After all these years of roaming through the desert, the Rediesel Wrench must know more about its existence. Could you tell me where to find its nest?",
  ui_story_5080_50800500_146_dialog_content = "You're not the first Illumina soldier to come looking for it, not by a long shot... But unfortunately, none of those guys ever came back.",
  ui_story_5080_50800500_147_dialog_content = "You're nothing special compared to them, so just give up already. There's no reason to get yourself killed over your mission.",
  ui_story_5080_50800500_148_dialog_content = "It pisses me off to know that after all these years, they're still sending people to their deaths.",
  ui_story_5080_50800500_149_dialog_content = "You don't understand! These are our orders as soldiers, and the unimaginable treasures hidden within the Secret Territories are worth every noble sacrifice!",
  ui_story_5080_50800500_150_dialog_content = "You keep saying that word over and over again, but do you actually know what \"sacrifice\" means?",
  ui_story_5080_50800500_151_dialog_content = "Go ahead, tell me what you think it means!",
  ui_story_5080_50800500_152_dialog_content = "It's the willingness to lay down one's own life for the sake of Illumina's splendor and the greater good!",
  ui_story_5080_50800500_153_dialog_content = "As well as... the resolve to accomplish one's mission at all costs!",
  ui_story_5080_50800500_154_dialog_content = "Hahahaha—",
  ui_story_5080_50800500_155_dialog_content = "Why are you laughing? You think this is a joke?!",
  ui_story_5080_50800500_156_dialog_content = "Yeah, I do. You really are no different than the people who came before you, so just go home. This desert has already claimed too many lives.",
  ui_story_5080_50800500_157_dialog_content = "Let's go, Tiny One.",
  ui_story_5080_50800500_158_dialog_content = "You know nothing... We're not the same... You have no idea what kind of resolve brought me here...",
  ui_story_5080_50800500_159_dialog_content = "I won't disgrace my family any longer... I have to... wash away our shame...",
  ui_story_5080_50800601_1_dialog_content = "Aren't you gonna get some sleep, Vice?",
  ui_story_5080_50800601_2_dialog_content = "Yawn—I still need to finish today's mission report... But don't worry about me! You go ahead and get some rest.",
  ui_story_5080_50800601_3_dialog_content = "You seem pretty tired to me.",
  ui_story_5080_50800601_4_dialog_content = "It's such a great opportunity to work with Captain... This is such a rare experience...",
  ui_story_5080_50800601_5_dialog_content = "I have to... write down everything...",
  ui_story_5080_50800601_6_dialog_content = "Here, let me help you with that.",
  ui_story_5080_50800601_7_dialog_content = "Nng... That's not... gonna work...",
  ui_story_5080_50800601_8_dialog_content = "It's fine. There's only a little bit left to write. I'll finish it for you.",
  ui_story_5080_50800601_9_dialog_content = "After spending so much time with Vice, even PlayerName has gotten used to doing this for her.",
  ui_story_5080_50800601_10_dialog_content = "I'm not sure when it happened, but it's probably from all the lectures she gives me... Don't worry, this won't take long. Go get some sleep, Carleen.",
  ui_story_5080_50800601_11_dialog_content = "It seems like you still have something on your mind... But if you insist. Good night.",
  ui_story_5080_50800601_12_dialog_content = "(I just need to add one last part, and her report will be done.)",
  ui_story_5080_50800601_13_dialog_content = "But wait, there's more... And this is the best part too!",
  ui_story_5080_50800601_14_dialog_content = "(Is that Zeta's voice? I can hear it all the way over here... How does she still have this much energy?)",
  ui_story_5080_50800601_15_dialog_content = "And so the witch girl and I hopped into our race car!",
  ui_story_5080_50800601_16_dialog_content = "(Who is she talking to? I'm done writing now... Guess it wouldn't hurt to take a look.)",
  ui_story_5080_50800601_17_dialog_content = "Whoosh! My car zoomed forward and we narrowly avoided the dragon's claws! Bang! Crash!",
  ui_story_5080_50800601_18_dialog_content = "I rammed my car into the dragon and sent it flying! Even the witch had no choice but to acknowledge my might!",
  ui_story_5080_50800601_19_dialog_content = "(Sounds like she might be exaggerating a little bit... Huh? Is that... Rachel? Is Zeta bothering her while she's on guard duty?)",
  ui_story_5080_50800601_20_dialog_content = "Oh, and I bet you didn't know this! When I rev up my engine, tons of lizards start crawling out of the sand!",
  ui_story_5080_50800601_21_dialog_content = "Those lizards taste the best! They're even more tender than the ones we had today!",
  ui_story_5080_50800601_22_dialog_content = "We're all pretty good at cooking around here, so I bet you'd like them too!",
  ui_story_5080_50800601_23_dialog_content = "... Would you like to try one of my compressed military biscuits?",
  ui_story_5080_50800601_24_dialog_content = "No thanks, those look awful.",
  ui_story_5080_50800601_25_dialog_content = "Which reminds me! Did I ever tell you that I run rallies all by myself?",
  ui_story_5080_50800601_26_dialog_content = "Unlike that evil witch girl, I don't rely on the Last Caelestite to reach the finish line!",
  ui_story_5080_50800601_27_dialog_content = "The glory of blazing through the unforgiving desert belongs to me alone!",
  ui_story_5080_50800601_28_dialog_content = "That's impressive. I never would have known that from just looking at you.",
  ui_story_5080_50800601_29_dialog_content = "Heheh, pretty cool right? The legendary warrior Zeta and her glorious achievements are enough to convince any evildoer to abandon their wicked ways! That's why you should stick with me!",
  ui_story_5080_50800601_30_dialog_content = "Your ability to survive all alone in the desert for so long would make you an excellent navigator on my rallies!",
  ui_story_5080_50800601_31_dialog_content = "Hop in my car, and we can share the glory of winning our next race!",
  ui_story_5080_50800601_32_dialog_content = "Glory, huh... I'm really only good with machines. Am I really a good choice for your team?",
  ui_story_5080_50800601_33_dialog_content = "Of course! Just leave the training to me, and I'll mold you into a legendary member of my crew!",
  ui_story_5080_50800601_34_dialog_content = "You can be in charge of... What was that thing called again? It's like a map, but with lots of other information... The road book! I'll teach you how to make a proper road book for our rallies!",
  ui_story_5080_50800601_35_dialog_content = "Sure. That sounds pretty interesting to me.",
  ui_story_5080_50800601_36_dialog_content = "(Is this real? Those two are actually having a conversation...)",
  ui_story_5080_50800601_37_dialog_content = "There's lots of other interesting stuff out here in the desert too! Starting tomorrow, I'll teach you all about them!",
  ui_story_5080_50800601_38_dialog_content = "And after we train you up... I'll finally be able to defeat that witch...",
  ui_story_5080_50800601_39_dialog_content = "But right now, it's time for me to go to bed... Good night...",
  ui_story_5080_50800601_40_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5080_50800601_41_dialog_content = "Honestly... Doesn't that hurt?",
  ui_story_5080_50800601_42_dialog_content = "Get lots of rest then... Good night.",
  ui_story_5080_50800601_43_dialog_content = "(One minute she's cold and distant, and the next she's warm and kind... Which one is the real you, Rachel?)",
  ui_story_5080_50800601_44_dialog_content = "(Maybe now is a good time to talk to her... Huh? Those powerful emotions... They're back again...)",
  ui_story_5080_50800601_45_option_content = "Sense Rachel",
  ui_story_5080_50800601_46_dialog_content = "The target has been acquired, and our mission is now complete. We did it, Captain!",
  ui_story_5080_50800601_47_dialog_content = "Well done... But don't drop your guard just yet, not while the ruins are still crawling with Eclipsites. We need to get out of here.",
  ui_story_5080_50800601_48_dialog_content = "Green Owl, Red Kestrel, take the data core and retreat through our infiltration route.",
  ui_story_5080_50800601_49_dialog_content = "This thing's pretty heavy, Captain. Let me carry it instead.",
  ui_story_5080_50800601_50_dialog_content = "It's fine, just keep a lookout. We need to regroup with the others at the exfil point.",
  ui_story_5080_50800601_51_dialog_content = "Captain, there appears to be a disturbance within the Eclipsite ranks.",
  ui_story_5080_50800601_52_dialog_content = "They're moving in a different direction... Why are they gathering together like that?",
  ui_story_5080_50800601_53_dialog_content = "No... They're starting to charge towards us!",
  ui_story_5080_50800601_54_dialog_content = "Run!",
  ui_story_5080_50800601_55_dialog_content = "Green Owl, Red Kestrel, come in! What's the situation at the exfil point?",
  ui_story_5080_50800601_56_dialog_content = "The Eclipsites appear to be converging on a single point... This is bad, Captain! They're closing in on your position!",
  ui_story_5080_50800601_57_dialog_content = "Just stay calm and stick to the plan. We'll be there soon, so make sure our escape route stays open!",
  ui_story_5080_50800601_58_dialog_content = "Don't bother with those Eclipsites, White Goose! Let's go!",
  ui_story_5080_50800601_59_dialog_content = "Escort the Captain out of here, Gray Wing! I'll draw their attention away from you!",
  ui_story_5080_50800601_60_dialog_content = "What are you talking about? We're getting out of here together! Captain, you have to get rid of the data core, or else we won't be able to outrun those Eclipsites!",
  ui_story_5080_50800601_61_dialog_content = "How are those things aware of our position? It's like they're trying to protect the core...",
  ui_story_5080_50800601_62_dialog_content = "Keep up, White Goose! No more running off on your own!",
  ui_story_5080_50800601_63_dialog_content = "But Captain... At this rate, we'll never make it...",
  ui_story_5080_50800601_64_dialog_content = "<color=#e8d9bb>Bang, bang, bang—</color>",
  ui_story_5080_50800601_65_dialog_content = "This way, Captain!",
  ui_story_5080_50800601_66_dialog_content = "It's Green Owl and Red Kestrel!",
  ui_story_5080_50800601_67_dialog_content = "Fools! I gave you clear orders to guard the exit, so what are you doing here?!",
  ui_story_5080_50800601_68_dialog_content = "You wouldn't have made it if we didn't disobey your orders, Captain.",
  ui_story_5080_50800601_69_dialog_content = "If you're going to discipline us, at least save it until we make it to safety!",
  ui_story_5080_50800601_70_dialog_content = "Idiots...",
  ui_story_5080_50800601_71_dialog_content = "I was wondering what was taking so long! Have you been carrying this heavy thing all this time, Captain?",
  ui_story_5080_50800601_72_dialog_content = "So this is the core, huh? This thing isn't exactly portable, Captain. We should...",
  ui_story_5080_50800601_73_dialog_content = "No! The mission comes first! The data in this core has the power to change all of Illumina... The Eagleeye Squad can't afford to fail, even if it puts our lives at risk!",
  ui_story_5080_50800601_74_dialog_content = "If we fail, it'll make us all deserters... I won't... Let you put your families through that kind of shame.",
  ui_story_5080_50800601_75_dialog_content = "The exit's just up ahead, and I'll bring up the rear. Now go! Make sure that the data core makes it back to Illumina!",
  ui_story_5080_50800601_76_dialog_content = "No can do, Captain!",
  ui_story_5080_50800601_77_dialog_content = "Are you disobeying orders again, Gray Wing?!",
  ui_story_5080_50800601_78_dialog_content = "According to Chapter 6, Subsection 31 of the Illumina Mission Completion Decree, a squad's vice-captain can supersede the captain's orders so long as the rest of the squad is in agreement!",
  ui_story_5080_50800601_79_dialog_content = "There's never been a better scout than you, Captain. Even if we make it through the exit, there's no guarantee that we'll safely return to the surface.",
  ui_story_5080_50800601_80_dialog_content = "As vice-captain, I hereby initiate a vote! All in favor of supporting the Captain and covering her escape, say \"aye\"!",
  ui_story_5080_50800601_81_dialog_content = "Aye!",
  ui_story_5080_50800601_82_dialog_content = "Aye.",
  ui_story_5080_50800601_83_dialog_content = "You...",
  ui_story_5080_50800601_84_dialog_content = "\"The mission comes before all,\" remember? Sorry, Captain... But your mission is different now.",
  ui_story_5080_50800601_85_dialog_content = "Take the core and return to Illumina. Your family's still waiting for you, aren't they?",
  ui_story_5080_50800601_86_dialog_content = "Don't worry, we'll be right behind you.",
  ui_story_5080_50800601_87_dialog_content = "Now get going, Captain!",
  ui_story_5080_50800601_88_dialog_content = "I-I...",
  ui_story_5080_50800601_89_dialog_content = "Just hang on, Eagle Hunters! I'll call for reinforcements as soon as I reach the surface!",
  ui_story_5080_50800601_90_dialog_content = "The Eclipsites are coming. Anyone feeling scared yet?",
  ui_story_5080_50800601_91_dialog_content = "The Captain made it out safely. What's there to be scared about now?",
  ui_story_5080_50800601_92_dialog_content = "Blow up the exit. We can't let any of these monsters get past us.",
  ui_story_5080_50800601_93_dialog_content = "What?! No, Gray Wing! Don't do it—!",
  ui_story_5080_50800601_94_dialog_content = "You're always carrying so much weight on your shoulders, Captain... I'm really sorry... For making you carry a little more.",
  ui_story_5080_50800601_95_dialog_content = "Light it up!!!",
  ui_story_5080_50800602_1_dialog_content = "(That was Rachel... Is this why she always insists on working alone? So when we were assigned to help her...)",
  ui_story_5080_50800602_2_dialog_content = "(The reason she keeps hiding her emotions and treating us so coldly... Is it because she's afraid to lose us?)",
  ui_story_5080_50800602_3_dialog_content = "(After seeing her painful past, should I really keep trying to talk to her about?)",
  ui_story_5080_50800602_4_dialog_content = "Gray Wing, White Goose, Green Owl, Red Kestrel... Are you... Still watching over me?",
  ui_story_5080_50800602_5_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5080_50800602_6_dialog_content = "Who's there? How dare you eavesdrop on—",
  ui_story_5080_50800602_7_dialog_content = "Meow!",
  ui_story_5080_50800602_8_dialog_content = "Cat?",
  ui_story_5080_50800602_9_dialog_content = "... Come here, little kitty.",
  ui_story_5080_50800602_10_dialog_content = "Would you like some dried fish?",
  ui_story_5080_50800602_11_dialog_content = "Good kitty... Are you the Courier's pet?",
  ui_story_5080_50800602_12_dialog_content = "Your fur is so soft and smooth. What a beautiful little cat.",
  ui_story_5080_50800602_13_dialog_content = "Did the jingling of these dog tags get your attention? You want to talk to them too, don't you?",
  ui_story_5080_50800602_14_dialog_content = "That cat was taken in by Roy a while ago and raised in the Rediesel Wrench's base. It can be pretty spoiled sometimes.",
  ui_story_5080_50800602_15_dialog_content = "Gah!",
  ui_story_5080_50800602_16_dialog_content = "Meow—!",
  ui_story_5080_50800602_17_dialog_content = "Wh-When did you... You didn't see anything, did you?!",
  ui_story_5080_50800602_18_dialog_content = "Don't worry, I've met all kinds of people during my travels. I don't feel one way or the other about your preferences.",
  ui_story_5080_50800602_19_dialog_content = "Besides, I've known for a long time that you're not as stone-hearted as you appear.",
  ui_story_5080_50800602_20_dialog_content = "But if you don't mind me saying, I think your cold appearance is only hurting your allies even more.",
  ui_story_5080_50800602_21_dialog_content = "... What makes you so different? You pushed the Rediesel Wrench away, didn't you?",
  ui_story_5080_50800602_22_dialog_content = "Pushed them away? Not at all. I simply moved a little further away from all the noise and commotion.",
  ui_story_5080_50800602_23_dialog_content = "As I suspected, you're just like <color=#FFB400>that person</color>. No wonder you gave me such a familiar feeling.",
  ui_story_5080_50800602_24_dialog_content = "\"That person\"?",
  ui_story_5080_50800602_25_dialog_content = "There are plenty of ex-soldiers from Illumina in the Rediesel Wrench, but one of them is especially different.",
  ui_story_5080_50800602_26_dialog_content = "Just like you, she was a dedicated and elite soldier on a special mission, one who led her team into the desert at a very young age.",
  ui_story_5080_50800602_27_dialog_content = "Did she... Survive her exploration of the Secret Territories out here?",
  ui_story_5080_50800602_28_dialog_content = "Do you remember her name, or the name of her squad? It's possible that I might know her.",
  ui_story_5080_50800602_29_dialog_content = "Her name...? When I first met her, she had already abandoned her past. I'm not sure if the name she's using is even her real name.",
  ui_story_5080_50800602_30_dialog_content = "But I do remember the name of her squad: the Freebird Squad. It's the same name that made me so envious of birds and their ability to fly freely through the sky.",
  ui_story_5080_50800602_31_dialog_content = "\"Freebird Squad\"?!",
  ui_story_5080_50800602_32_dialog_content = "(Isn't that the name of the squad Rachel's looking for right now?)",
  ui_story_5080_50800602_33_dialog_content = "That person... Escaped to the desert as well? Then, not only did she become a traitor, she also fell in with the Rediesel Wrench—",
  ui_story_5080_50800602_34_dialog_content = "You're wrong, Jeriah: I'm nothing like that person. She may be a shameless deserter, but I'm not!",
  ui_story_5080_50800602_35_dialog_content = "I'm sorry, my little bird of prey, but I'm afraid you're the one who's mistaken.",
  ui_story_5080_50800602_36_dialog_content = "That woman was neither shameless nor a deserter. Up until the very end, she was one of the proudest people I've ever known.",
  ui_story_5080_50800602_37_dialog_content = "Her burning passion was as red as the wrench she wielded in her hands. Even after passing it on to Sinsa, it hasn't lost any of its color.",
  ui_story_5080_50800602_38_dialog_content = "If that's what you believe... Then I have a story to share with you.",
  ui_story_5080_50800602_39_dialog_content = "It was first told to me by <color=#FFB400>my aunt</color>, who was once a member of the Freebird Squad—",
  ui_story_5080_50800602_40_dialog_content = "Thirty years ago, Illumina put together a special forces team known as the Freebird Squad.",
  ui_story_5080_50800602_41_dialog_content = "The elite, hand-selected members of this team were charged with carrying out missions that were impossible for any other squad.",
  ui_story_5080_50800602_42_dialog_content = "Despite the incomparable challenges they faced with every operation, the Freebird Squad maintained a perfect mission success rate. Joining their squad was every soldier's greatest aspiration.",
  ui_story_5080_50800602_43_dialog_content = "If that squad still existed, I'm sure you would have been the perfect candidate for it.",
  ui_story_5080_50800602_44_dialog_content = "But then they were assigned to a highly classified mission, which ended up being their last. My aunt and her comrades risked their lives for it...",
  ui_story_5080_50800602_45_dialog_content = "The price they paid was unimaginable but in the end... Their captain betrayed them. She abandoned the mission without authorization and led the rest of the survivors back to Illumina as a <color=#FFB400>deserter</color>.",
  ui_story_5080_50800602_46_dialog_content = "Not long afterward, she defected from Illumina entirely, which cast my aunt into the depths of despair!",
  ui_story_5080_50800602_47_dialog_content = "They branded her a traitor, and accused her of being a separatist. Stripped of her honor and demoted countless times, she was scorned by everyone around her!",
  ui_story_5080_50800602_48_dialog_content = "She refused to come home for fear of burdening our family, and her relationship with my father fell to pieces—",
  ui_story_5080_50800602_49_dialog_content = "But despite all of my aunt's sacrifices, our family's honor was still...",
  ui_story_5080_50800602_50_dialog_content = "(Rachel...)",
  ui_story_5080_50800602_51_option_content = "Sense Rachel's Memories",
  ui_story_5080_50800602_52_dialog_content = "Hey look! That traitor's daughter is here again!",
  ui_story_5080_50800602_53_dialog_content = "Don't tell me she's trying to get into the Museum. That place is where we honor our real heroes! Traitors aren't allowed in there!",
  ui_story_5080_50800602_54_dialog_content = "Given her family's history of betrayal, it's hard to imagine that she was raised any differently.",
  ui_story_5080_50800602_55_dialog_content = "Can we really trust someone like her to watch our backs, captain?",
  ui_story_5080_50800602_56_dialog_content = "Rachel? That thin-looking little girl? I don't think she has the determination for this...",
  ui_story_5080_50800602_57_dialog_content = "No way! She's no good! Get rid of her—",
  ui_story_5080_50800602_58_dialog_content = "I'm not that kind of person! I'll prove it... I'll prove it to everyone!",
  ui_story_5080_50800602_59_dialog_content = "I know you're not, Rachel. You're already a wonderful young lady and an exceptional soldier. You have nothing to prove to anyone.",
  ui_story_5080_50800602_60_dialog_content = "No, Auntie... I... I didn't mean it like that...",
  ui_story_5080_50800602_61_dialog_content = "It's okay, Rachel. I don't care what other people say, and neither should you.",
  ui_story_5080_50800602_62_dialog_content = "Just keep that passion in your heart, and show them that you're better than your worthless aunt.",
  ui_story_5080_50800602_63_dialog_content = "Auntie... I'm so sorry...",
  ui_story_5080_50800602_64_dialog_content = "Stand up and look at me, Rachel. None of this is your fault.",
  ui_story_5080_50800602_65_dialog_content = "It's my fault for bringing so much trouble into your life. You're going to endure a lot more criticism in the future.",
  ui_story_5080_50800602_66_dialog_content = "But you can't let it knock you down. Never give in to what they say about you. Fight it loudly and with all your heart, just like right now.",
  ui_story_5080_50800602_67_dialog_content = "I know you'll be even greater than I could ever hope to be.",
  ui_story_5080_50800602_68_dialog_content = "Believe in yourself, Rachel. No matter what decisions you make, stick with them until the bitter end—And don't listen to what anyone says about you!",
  ui_story_5080_50800602_69_dialog_content = "My aunt was forced to live outside on her own, but she always treated me like her own daughter... And that's why... I can never forgive that person for what she did to her.",
  ui_story_5080_50800602_70_dialog_content = "So I decided to become stronger, to surpass my limits and overcome the shackles of my family's past... I didn't want that tragedy to repeat itself ever again.",
  ui_story_5080_50800602_71_dialog_content = "She comes from a family of deserters, so she's bound to give up sometimes, right?",
  ui_story_5080_50800602_72_dialog_content = "No way! I think she's super cool for being so persistent, so stop talking about her behind her back.",
  ui_story_5080_50800602_73_dialog_content = "So did any of the new recruits catch your eye, Hiiro?",
  ui_story_5080_50800602_74_dialog_content = "Not at all. None of them even came close to keeping up with my training regimen.",
  ui_story_5080_50800602_75_dialog_content = "I think you're being too harsh on them... Wait, what about <color=#FFB400>her</color>? Don't tell me <color=#FFB400>she</color> wasn't up to snuff either?",
  ui_story_5080_50800602_76_dialog_content = "<color=#FFB400>That girl</color>... She expects way too much from herself, considering she isn't as physically fit as her peers. Pushing herself like this will never work for her.",
  ui_story_5080_50800602_77_dialog_content = "I've been trying to disqualify her before she does any lasting damage to herself. However, no matter how difficult I make things for her, she stubbornly refuses to give up.",
  ui_story_5080_50800602_78_dialog_content = "In terms of fitness, she's completely unremarkable, but in the end... She was the only one who kept up with me.",
  ui_story_5080_50800602_79_dialog_content = "The Academy is buzzing with rumors about her and her family, but little by little, her peers are starting to respect her.",
  ui_story_5080_50800602_80_dialog_content = "I'm not sure if I should praise her or not.",
  ui_story_5080_50800602_81_dialog_content = "A soldier who never fails to stand up after getting knocked down countless times... It sounds to me like she has the makings of a hero, Hiiro.",
  ui_story_5080_50800602_82_dialog_content = "You can't keep denying her anymore, so just acknowledge her resolve and take good care of her.",
  ui_story_5080_50800602_83_dialog_content = "There's no way she'll let herself be disqualified.",
  ui_story_5080_50800602_84_dialog_content = "Cadet Rachel! In recognition of your exemplary performance and your indomitable spirit, you have been specially chosen by Commander Hiiro to join the ranks of the 3rd Legion!",
  ui_story_5080_50800602_85_dialog_content = "(So this is Rachel... This is how she fought her way up the ranks... And became an elite captain worthy of everyone's respect.)",
  ui_story_5080_50800602_86_dialog_content = "I see... You suffered so much to become the bird of prey that you are today.",
  ui_story_5080_50800602_87_dialog_content = "Heh, then you're free to see her as a traitor if you wish. After all, we only exchanged a few words before she disappeared from our lives forever.",
  ui_story_5080_50800602_88_dialog_content = "With how cunning she was, I truly wish she had managed to escape back then... Maybe then she could give me the answers I'm looking for.",
  ui_story_5080_50800602_89_dialog_content = "What answers?",
  ui_story_5080_50800602_90_dialog_content = "This desert is vast, don't you think? You could stand guard through the boundless night and still only see a tiny fraction of this place.",
  ui_story_5080_50800602_91_dialog_content = "Its vastness is also what makes it so empty.",
  ui_story_5080_50800602_92_dialog_content = "This emptiness... Is that why you could never fit in with those people?",
  ui_story_5080_50800602_93_dialog_content = "You said you traveled to countless places, and yet you never found a place where you truly belonged, did you? So you came back to this place instead...",
  ui_story_5080_50800602_94_dialog_content = "It's true that the desert has always felt strangely unfamiliar to me, and that I've never seen eye-to-eye with the hot-blooded fools of the Rediesel Wrench.",
  ui_story_5080_50800602_95_dialog_content = "They're so noisy and wild every single day, but are they really searching for the meaning of life?",
  ui_story_5080_50800602_96_dialog_content = "I worry that they're going to come to their senses someday, and realize just how much of their lives they wasted. Just thinking about it is terrifying.",
  ui_story_5080_50800602_97_dialog_content = "People are destined to go their separate ways, and the party has to come to an end someday. No matter how brightly we shine in life, all of us will return to nothingness. It's frightening, isn't it?",
  ui_story_5080_50800602_98_dialog_content = "So you linger in this desert, a place that's neither your home nor an unfamiliar land.",
  ui_story_5080_50800602_99_dialog_content = "You're just another lonely bird in the Rediesel Desert, the same as me.",
  ui_story_5080_50800602_100_dialog_content = "You're actually very good at understanding other people's viewpoints, you know? And that's the mark of a truly great captain.",
  ui_story_5080_50800602_101_dialog_content = "(If only Vice was awake to see this! I'll have to find a chance to tell her about it tomorrow.)",
  ui_story_5080_50800602_102_dialog_content = "I was just a child when that person was still alive. She taught me many things, and opened my eyes to the vastness of the world.",
  ui_story_5080_50800602_103_dialog_content = "She also motivated me to search for a life of freedom with all my heart. I wanted to find the meaning of my life and charge headfirst into a future of endless possibilities.",
  ui_story_5080_50800602_104_dialog_content = "But then she died without another word. Her proud and powerful figure became just another blurry image in our memories.",
  ui_story_5080_50800602_105_dialog_content = "So what could I ever amount to? After breaking away from my parents and the Rediesel Wrench, there's no place left for me in this world.",
  ui_story_5080_50800602_106_dialog_content = "And while I'm stuck in this profound emptiness, those fools keep carrying on without a single worry in the world. Sigh... I really wish I knew what to do.",
  ui_story_5080_50800602_107_dialog_content = "Why are you telling me all of this?",
  ui_story_5080_50800602_108_dialog_content = "Because I'm not sure I could talk to anyone else about this.",
  ui_story_5080_50800602_109_dialog_content = "I suppose there must be a better reason for sharing my thoughts with you. Maybe it's because you remind me so much of her... Or perhaps you remind me of myself?",
  ui_story_5080_50800602_110_dialog_content = "Are you sure you're not just... A lost little bird who strayed into the desert?",
  ui_story_5080_50800602_111_dialog_content = "Part of me wishes that you were here to look for deserters. That way, you could find that person and teach her a lesson for disappearing from our lives like that.",
  ui_story_5080_50800602_112_dialog_content = "If it wasn't for her, maybe I wouldn't be so frustrated in life. After all, she changed the Rediesel Wrench from a group of dishonorable idiots into a group of carefree ones...",
  ui_story_5080_50800602_113_dialog_content = "So why can't I be like them?",
  ui_story_5080_50800602_114_dialog_content = "Jeriah, you...",
  ui_story_5080_50800602_115_dialog_content = "I'll carry Zeta to bed. You should go downstairs and get some sleep too.",
  ui_story_5080_50800602_116_dialog_content = "You say that everything must return to nothingness... And yet you're still willing to hold her and carry her.",
  ui_story_5080_50800602_117_dialog_content = "It can't be helped. After covering my house with their \"artwork,\" it's impossible to ignore them.",
  ui_story_5080_50800602_118_dialog_content = "The desert gets cold at night. I'll have Speaker take over for you, so get some rest.",
  ui_story_5080_50800602_119_dialog_content = "Also... Our poor Caelestite friend will freeze to death if we stay out here any longer.",
  ui_story_5080_50800602_120_dialog_content = "(She knew I was here all along!)",
  ui_story_5080_50800602_121_dialog_content = "(I gotta get out of here... Ow!)",
  ui_story_5080_50800602_122_dialog_content = "Wh-Who left this bucket full of water over here?!",
  ui_story_5080_50800701_1_dialog_content = "Wake up. The mission isn't over yet.",
  ui_story_5080_50800701_2_dialog_content = "Yawn... Good morning, Captain.",
  ui_story_5080_50800701_3_dialog_content = "... Good morning, now go splash some water on your face and wake up!",
  ui_story_5080_50800701_4_dialog_content = "Y-Yes, ma'am!",
  ui_story_5080_50800701_5_dialog_content = "We're continuing our reconnaissance work today! Wake up and meet in ten minutes!",
  ui_story_5080_50800701_6_dialog_content = "Let me join you.",
  ui_story_5080_50800701_7_dialog_content = "If you're looking for a certain Eclipsite, I may have some information that could prove useful.",
  ui_story_5080_50800701_8_dialog_content = "Why are you suddenly interested in coming with us? It can't just be out of curiosity, right?",
  ui_story_5080_50800701_9_dialog_content = "Even though everything must return to nothingness, I still want to see how this ends.",
  ui_story_5080_50800701_10_dialog_content = "You wouldn't turn me away, would you?",
  ui_story_5080_50800701_11_dialog_content = "Besides, if we manage to find that person's resting place, I'd like to pay my respects.",
  ui_story_5080_50800701_12_dialog_content = "... Is everyone awake yet? Let's get ready to move out!",
  ui_story_5080_50800701_13_dialog_content = "Zeta's still out like a light.",
  ui_story_5080_50800701_14_dialog_content = "Let the child sleep. We're leaving.",
  ui_story_5080_50800701_15_dialog_content = "Here is the map we're using for our investigation, Jeriah.",
  ui_story_5080_50800701_16_dialog_content = "From what I discovered yesterday, the Eclipsite nest is most likely somewhere around the volcanic belt.",
  ui_story_5080_50800701_17_dialog_content = "I've marked a number of locations on the map. Could you help us rule out any of these places?",
  ui_story_5080_50800701_18_dialog_content = "Unfortunately, my little bird of prey, you won't find your answer in any of these locations.",
  ui_story_5080_50800701_19_dialog_content = "What you and most other outsiders don't know is that a massive, dormant volcano is hidden under the sands of the Rediesel Desert.",
  ui_story_5080_50800701_20_dialog_content = "A dormant volcano?",
  ui_story_5080_50800701_21_dialog_content = "Yes, though I suppose that isn't exactly the case anymore. Just yesterday, I confirmed that the volcano is active once again.",
  ui_story_5080_50800701_22_dialog_content = "While that type of Eclipsite has been seen roaming all over the desert, I'm afraid its nest can only be in that place.",
  ui_story_5080_50800701_23_dialog_content = "After all, it's the only place that the Rediesel Wrench generally avoids.",
  ui_story_5080_50800701_24_dialog_content = "Why is that?",
  ui_story_5080_50800701_25_dialog_content = "The last time the underground volcano erupted was during the Darkover Crisis. Back then, countless Eclipsites came surging out of the fissures in the ground and attacked the Rediesel Wrench.",
  ui_story_5080_50800701_26_dialog_content = "Their leader at the time died during that battle, along with Zeta's parents and many others.",
  ui_story_5080_50800701_27_dialog_content = "Ever since then, the Rediesel Wrench has made its home all over the desert, but they always steer clear of that place.",
  ui_story_5080_50800701_28_dialog_content = "But if they know those Eclipsites came out of the volcano, why haven't they tried investigating it after all these years?",
  ui_story_5080_50800701_29_dialog_content = "They did, but they never found anything.",
  ui_story_5080_50800701_30_dialog_content = "The volcano has been completely dormant ever since that day, and only regular Eclipsites inhabit that place now.",
  ui_story_5080_50800701_31_dialog_content = "The Rediesel Wrench has gone to clear them out a few times, but no sign of those Eclipsites has ever been discovered.",
  ui_story_5080_50800701_32_dialog_content = "At first, everyone thought they were the only ones of their kind and had perished in that battle along with the Rediesel Wrench leader and the others.",
  ui_story_5080_50800701_33_dialog_content = "After so many extermination campaigns, even the regular Eclipsites in the volcano have dwindled in numbers.",
  ui_story_5080_50800701_34_dialog_content = "People tend to avoid their most painful memories. In time, they stopped going to that place altogether.",
  ui_story_5080_50800701_35_dialog_content = "But that used to be their home... How could they just abandon it like that?",
  ui_story_5080_50800701_36_dialog_content = "Don't look so sad, PlayerName! We've done a great job of rebuilding Eraveil, remember? All we have to do now is find more of your people!",
  ui_story_5080_50800701_37_dialog_content = "Heheh, Vice may be right. Perhaps some of your Caelestite compatriots chose to travel the world as freely as the birds themselves.",
  ui_story_5080_50800701_38_dialog_content = "And perhaps someday... Those birds will come home to roost once again.",
  ui_story_5080_50800701_39_dialog_content = "...",
  ui_story_5080_50800701_40_dialog_content = "In any case, I'm the only person who still visits their former home every so often.",
  ui_story_5080_50800701_41_dialog_content = "And while my investigations haven't been fruitful, I still know the way there.",
  ui_story_5080_50800701_42_dialog_content = "Then we'll leave the navigating to you, Jeriah. Here's the map.",
  ui_story_5080_50800701_43_dialog_content = "Understood, now let's get going.",
  ui_story_5080_50800701_44_dialog_content = "Th-The ground's shaking!",
  ui_story_5080_50800701_45_dialog_content = "Look! The volcano is erupting!",
  ui_story_5080_50800701_46_dialog_content = "Don't be so alarmed. We should keep going on our way.",
  ui_story_5080_50800701_47_dialog_content = "Volcanic activity is nothing new in the Rediesel Desert, but that isn't the place we're looking for.",
  ui_story_5080_50800701_48_dialog_content = "The volcano in question has been dormant for years. Even at the rim of its crater, I found no signs of activity until recently.",
  ui_story_5080_50800701_49_dialog_content = "But now... Roars have started to come from deep within the volcano. The roars of Eclipsites.",
  ui_story_5080_50800701_50_dialog_content = "And if that kind of Eclipsite has returned to the volcano, then something strange must be happening as we speak.",
  ui_story_5080_50800701_51_dialog_content = "We need to hurry!",
  ui_story_5080_50800701_52_dialog_content = "Over here. We can reach the volcano's crater by descending from here.",
  ui_story_5080_50800701_53_dialog_content = "Wow... This place is covered with scorch marks from lava!",
  ui_story_5080_50800701_54_dialog_content = "Could these have been left by the Eclipsites? Or perhaps it's just from the volcano?",
  ui_story_5080_50800701_55_dialog_content = "I'm not sure... I was so busy with my investigation yesterday that I didn't venture very far down.",
  ui_story_5080_50800701_56_dialog_content = "But one thing's for certain: this volcano is active now.",
  ui_story_5080_50800701_57_dialog_content = "Wait, doesn't that mean it's dangerous to go down there?",
  ui_story_5080_50800701_58_dialog_content = "Carleen, can you stay here and guard the entrance and our car?",
  ui_story_5080_50800701_59_dialog_content = "Understood. Leave it to me.",
  ui_story_5080_50800701_60_dialog_content = "An unimaginable power is causing the ground to tremble slightly.",
  ui_story_5080_50800701_61_dialog_content = "This volcano is anything but extinct.",
  ui_story_5080_50800701_62_dialog_content = "These tracks on the ground... Were they left by Eclipsites?",
  ui_story_5080_50800701_63_dialog_content = "They seem to be going deeper into the volcano. Let's go.",
  ui_story_5080_50800701_64_dialog_content = "Wait, Rachel!",
  ui_story_5080_50800701_65_dialog_content = "Take a look at this!",
  ui_story_5080_50800701_66_dialog_content = "This passage looks like it was just excavated recently.",
  ui_story_5080_50800701_67_dialog_content = "Look! The crater is just up ahead!",
  ui_story_5080_50800701_68_dialog_content = "Why is there such a large and recently-dug tunnel so close to the crater...?",
  ui_story_5080_50800701_69_dialog_content = "Take a look at that wall, young Caelestite.",
  ui_story_5080_50800701_70_dialog_content = "Claw marks? They're really deep, as if they were left by something gigantic...",
  ui_story_5080_50800701_71_dialog_content = "There's no mistaking it. These claw marks belong to that dragon from back then.",
  ui_story_5080_50800701_72_dialog_content = "It looks like this place is its lair, or perhaps its hunting grounds.",
  ui_story_5080_50800701_73_dialog_content = "No wonder Azure hasn't been able to find it all this time.",
  ui_story_5080_50800701_74_dialog_content = "It's because the dragon has multiple lairs, and one of them is in a place that most people avoid in the Rediesel Desert...",
  ui_story_5080_50800701_75_dialog_content = "But Jeriah... How did you know Azure was looking for it?",
  ui_story_5080_50800701_76_dialog_content = "Heh, like I said, I've been assigned to this entire desert after all.",
  ui_story_5080_50800701_77_dialog_content = "(Please... It's as clear as day, Jeriah...You actually care about everyone in the Rediesel Wrench.)",
  ui_story_5080_50800701_78_dialog_content = "Now that I think about it, the dragon's sightings seem to correspond with the volcano's eruptions.",
  ui_story_5080_50800701_79_dialog_content = "Maybe it has to evacuate the volcano and search for another lair whenever it erupts?",
  ui_story_5080_50800701_80_dialog_content = "But if it's afraid of lava, why did it choose to live in a volcano?",
  ui_story_5080_50800701_81_dialog_content = "It makes no sense.",
  ui_story_5080_50800701_82_dialog_content = "Because it was hiding from a certain person.",
  ui_story_5080_50800701_83_dialog_content = "Back then, that person was scouring the desert for her dangerous prey. To avoid her, the dragon had no choice but to hide itself deep underground...",
  ui_story_5080_50800701_84_dialog_content = "The ground's shaking again!",
  ui_story_5080_50800701_85_dialog_content = "Something's not right... The source of the quake seems to be right below us! Could it be that the volcano is about to erupt?!",
  ui_story_5080_50800701_86_dialog_content = "The mission has run into an impossible obstacle, Captain! We need to retreat for now!",
  ui_story_5080_50800701_87_dialog_content = "... The rest of you can go on without me. I'm going to continue with the mission.",
  ui_story_5080_50800701_88_dialog_content = "But Captain... It's too dangerous to stay down here!",
  ui_story_5080_50800701_89_dialog_content = "The mission comes before all.",
  ui_story_5080_50800701_90_dialog_content = "It's only natural for a predator to pursue its prey this relentlessly.",
  ui_story_5080_50800701_91_dialog_content = "However, your willingness to sacrifice your life over something so illusive confuses me. Tell me, are you being too adamant about this, or are you actually hesitating?",
  ui_story_5080_50800701_92_dialog_content = "There's no need to risk our lives in this kind of situation, Captain! We can always come back later!",
  ui_story_5080_50800701_93_dialog_content = "That won't do. If the volcano erupts, this whole place will be flooded with magma, and when it cools...",
  ui_story_5080_50800701_94_dialog_content = "Just go!",
  ui_story_5080_50800701_95_dialog_content = "We're getting out of here together, Captain!",
  ui_story_5080_50800701_96_dialog_content = "Hatchling Two... Why did you have to say it like that...?",
  ui_story_5080_50800701_97_dialog_content = "Huh?",
  ui_story_5080_50800701_98_dialog_content = "(She's talking about before... Rachel's old squadmate said the exact same thing...)",
  ui_story_5080_50800701_99_dialog_content = "I can't run away... I won't...",
  ui_story_5080_50800701_100_dialog_content = "Careful! I sense Eclipsites coming towards us!",
  ui_story_5080_50800701_101_dialog_content = "We can talk about escaping later! Get ready to fight, everyone!",
  ui_story_5080_50800702_1_dialog_content = "I-It's finally over.",
  ui_story_5080_50800702_2_dialog_content = "The tremors stopped too... Does that mean the volcano is stable now?",
  ui_story_5080_50800702_3_dialog_content = "Why were those Eclipsites so powerful? In all of my investigations, I've never seen anything like them down here.",
  ui_story_5080_50800702_4_dialog_content = "Their bodies... Are these mutations?",
  ui_story_5080_50800702_5_dialog_content = "It's happening again!",
  ui_story_5080_50800702_6_dialog_content = "It's way too dangerous here, Captain! We should at least retreat to the tunnel from earlier!",
  ui_story_5080_50800702_7_dialog_content = "We're too close to the volcano's crater here.",
  ui_story_5080_50800702_8_dialog_content = "Fine... We'll do as Hatchling Two suggests and look for another route—",
  ui_story_5080_50800702_9_dialog_content = "Wait, this trembling... This isn't the volcano at all!",
  ui_story_5080_50800702_10_dialog_content = "Look out, everyone! The tunnel is about to collapse—!!!",
  ui_story_5080_50800702_11_dialog_content = "The Rediesel Wrench has always been such an unruly group of people.",
  ui_story_5080_50800702_12_dialog_content = "Hey Jeriah, come build this car with us! I bet we can finish it by today if we work hard!",
  ui_story_5080_50800702_13_dialog_content = "Yeah, and then we can use it to catch tons of sand lizards!",
  ui_story_5080_50800702_14_dialog_content = "No thanks.",
  ui_story_5080_50800702_15_dialog_content = "Aww, but why? You never want to hang out, Jeriah!",
  ui_story_5080_50800702_16_dialog_content = "No worries, we'll just try again tomorrow!",
  ui_story_5080_50800702_17_dialog_content = "Even when I told them no, it didn't make a difference. Still, I was never able to fit in with the others.",
  ui_story_5080_50800702_18_dialog_content = "Aha! Looks like I found you again!",
  ui_story_5080_50800702_19_dialog_content = "I wasn't playing hide-and-seek with you.",
  ui_story_5080_50800702_20_dialog_content = "Then that means you were waiting for me, right?",
  ui_story_5080_50800702_21_dialog_content = "See? You're only blushing because I'm right!",
  ui_story_5080_50800702_22_dialog_content = "N-No way.",
  ui_story_5080_50800702_23_dialog_content = "Here you go. It wasn't easy, but I managed to find a few more teaching materials from Illumina.",
  ui_story_5080_50800702_24_dialog_content = "You went out there again?",
  ui_story_5080_50800702_25_dialog_content = "Yep! I had business to do with some black market merchants in Umbraton.",
  ui_story_5080_50800702_26_dialog_content = "Wanna know something else? There's this incredible set of ancient ruins just outside of Umbraton, and it's built out of materials that we don't even know about.",
  ui_story_5080_50800702_27_dialog_content = "It's full of gangsters and people hawking stuff on the black market. They've turned the whole place into a crazy maze of some sort.",
  ui_story_5080_50800702_28_dialog_content = "They're all searching for anything that can turn a profit. They don't even realize that the ruins themselves are the most valuable thing out there!",
  ui_story_5080_50800702_29_dialog_content = "What do you mean? What other value can some old ruins have, aside from being a tourist spot?",
  ui_story_5080_50800702_30_dialog_content = "Are you seriously asking that?!",
  ui_story_5080_50800702_31_dialog_content = "What do you think those ruins are made out of? Why were they built? And who exactly built them?",
  ui_story_5080_50800702_32_dialog_content = "What kind of technology can we find in there? And what can that technology do for us?",
  ui_story_5080_50800702_33_dialog_content = "What was the ancient civilization like? What kind of world did they create for themselves, and why did it disappear?",
  ui_story_5080_50800702_34_dialog_content = "Those ruins can answer all of those questions and more.",
  ui_story_5080_50800702_35_dialog_content = "Can some old hallways really tell you that much?",
  ui_story_5080_50800702_36_dialog_content = "With a little time and persuasion, sure!",
  ui_story_5080_50800702_37_dialog_content = "You mean like... That time you told me about before?",
  ui_story_5080_50800702_38_dialog_content = "What time?",
  ui_story_5080_50800702_39_dialog_content = "When you were exploring the Secret Territory in Northland.",
  ui_story_5080_50800702_40_dialog_content = "Oh, you mean that one time I taught you how to fly a kite!",
  ui_story_5080_50800702_41_dialog_content = "That's right, those ruins described a kind of flying machine. When Illumina discovered that, they started pouring tons of resources into researching it.",
  ui_story_5080_50800702_42_dialog_content = "But for a single person like me, all I could do was make you a kite.",
  ui_story_5080_50800702_43_dialog_content = "So what did you see in those other ruins?",
  ui_story_5080_50800702_44_dialog_content = "There were too many people loitering around, so I didn't get the chance to do any research.",
  ui_story_5080_50800702_45_dialog_content = "But I'll make sure to take a good look around the next time I go.",
  ui_story_5080_50800702_46_dialog_content = "I might even find something nice to bring back to you, Jeriah!",
  ui_story_5080_50800702_47_dialog_content = "... Can I ask you something?",
  ui_story_5080_50800702_48_dialog_content = "Huh? Sure, go ahead.",
  ui_story_5080_50800702_49_dialog_content = "You've basically seen all of Astra, so why do you still get so excited about everything?",
  ui_story_5080_50800702_50_dialog_content = "Nothing in this world should surprise you anymore. If anything, you should be totally bored by now...",
  ui_story_5080_50800702_51_dialog_content = "Hey Jeriah, have you read all of the books I've brought back for you?",
  ui_story_5080_50800702_52_dialog_content = "Yep. All five thousand, six hundred and eighty-three of them.",
  ui_story_5080_50800702_53_dialog_content = "But even that many books couldn't begin to tell the entire story of Astra.",
  ui_story_5080_50800702_54_dialog_content = "Did you also know that there are other continents in the world besides our own? What kind of people and places are out there, I wonder?",
  ui_story_5080_50800702_55_dialog_content = "I have no idea, but I've always been curious to know.",
  ui_story_5080_50800702_56_dialog_content = "I've been to most places in Astra, but I still can't remember all the roads I've traveled.",
  ui_story_5080_50800702_57_dialog_content = "You may not realize it right now, Jeriah, but you also have a burning desire to explore the world.",
  ui_story_5080_50800702_58_dialog_content = "You're not like me, zooming past all of the world's sights without stopping to appreciate them. That's why I think you'll learn more about this world than I ever will.",
  ui_story_5080_50800702_59_dialog_content = "Quit stroking my head...",
  ui_story_5080_50800702_60_dialog_content = "Alright! You wanted an answer, so here it is! Even though I've been to lots of different places, I rarely make memories when I'm out there.",
  ui_story_5080_50800702_61_dialog_content = "And when night falls over the desert, I realize that I hardly remember any of the beautiful things I've seen in my life.",
  ui_story_5080_50800702_62_dialog_content = "That's because... As a soldier of Illumina, you're always getting sent out on missions.",
  ui_story_5080_50800702_63_dialog_content = "Though I could be wrong too! Hahaha!",
  ui_story_5080_50800702_64_dialog_content = "You're a smart kid, Jeriah. I know you have lots of questions, and I know it feels awful when you don't find the answers you're looking for.",
  ui_story_5080_50800702_65_dialog_content = "But there's no helping it. You're still a kid after all!",
  ui_story_5080_50800702_66_dialog_content = "So grow up and learn everything you can, Jeriah! I'm sure you'll be able to solve any question that comes your way in the future!",
  ui_story_5080_50800702_67_dialog_content = "And don't waste your life running around like I did. Always remember to stop and smell the roses.",
  ui_story_5080_50800702_68_dialog_content = "I'm positive you'll find your life's meaning, and make tons of wonderful memories along the way.",
  ui_story_5080_50800702_69_dialog_content = "Spread your wings and live freely, Jeriah. Only then will you find... The answers you're so desperate to know.",
  ui_story_5080_50800702_70_dialog_content = "I don't understand.",
  ui_story_5080_50800702_71_dialog_content = "<color=#FFB400>She</color> and I should be the same. We were both born into places where we didn't belong.",
  ui_story_5080_50800702_72_dialog_content = "I wanted to leave the desert and leave my mark on the world wherever I went. But after freeing herself from Illumina, she chose to come here of all places.",
  ui_story_5080_50800702_73_dialog_content = "Why... Why did you choose to stay?",
  ui_story_5080_50800702_74_dialog_content = "Do you still remember <color=#FFB400>that story</color> I told you, Jeriah?",
  ui_story_5080_50800702_75_dialog_content = "Uh-huh.",
  ui_story_5080_50800702_76_dialog_content = "And at the end of that story, you found <color=#FFB400>this wrench</color> and a group of people who depended on you. You weren't alone anymore.",
  ui_story_5080_50800702_77_dialog_content = "So for everyone's sake, you united all of the desert nomads and formed the Rediesel Wrench.",
  ui_story_5080_50800702_78_dialog_content = "You were never responsible for any of them... So why did you choose to stay for them? Don't you want to keep...",
  ui_story_5080_50800702_79_dialog_content = "What's wrong with wanting to come home? I was born and raised in this desert after all. Besides, I want them to have their freedom too.",
  ui_story_5080_50800702_80_dialog_content = "Living without self-awareness makes us no different from the Eclipsites, don't you think? I want to free their souls and give them the power to make their own decisions.",
  ui_story_5080_50800702_81_dialog_content = "I already wasted most of my own life.",
  ui_story_5080_50800702_82_dialog_content = "So, I wish for them to understand their journey and live a life of freedom.",
  ui_story_5080_50800702_83_dialog_content = "To become free spirits who live in the moment, merrily making mischief—is that what freedom is?",
  ui_story_5080_50800702_84_dialog_content = "I don't understand...",
  ui_story_5080_50800702_85_dialog_content = "It's because of your stories that I found out there was so much more waiting for me to discover.",
  ui_story_5080_50800702_86_dialog_content = "At that time, I was utterly engrossed in exploring this world.",
  ui_story_5080_50800702_87_dialog_content = "Oh? That's quite impressive, Jeriah.",
  ui_story_5080_50800702_88_dialog_content = "But this world isn't as amazing as you described. You lied to me.",
  ui_story_5080_50800702_89_dialog_content = "The nobles of Lumopolis are arrogant, the Illumina Federation is ever so dull, and the people of Northland remain trapped in their own fairy tales.",
  ui_story_5080_50800702_90_dialog_content = "The Whispering Corridor of Umbraton has become Istvan's treasure trove. Those so-called ruins of legend are just the indifferent inner walls of his coffers.",
  ui_story_5080_50800702_91_dialog_content = "Everything just seems so empty...",
  ui_story_5080_50800702_92_dialog_content = "Even the Caelestites, who created so many scientific miracles, have ultimately become memories people rarely speak of.",
  ui_story_5080_50800702_93_dialog_content = "The Eclipsites attack, we strike back... All life in this world is trapped in a desperate vicious cycle for survival.",
  ui_story_5080_50800702_94_dialog_content = "Everything will return to nothingness.",
  ui_story_5080_50800702_95_dialog_content = "Little Jeriah has finally grown up, but you worry too much.",
  ui_story_5080_50800702_96_dialog_content = "I don't understand... Should I stop asking questions?",
  ui_story_5080_50800702_97_dialog_content = "If intelligence only invites the emptiness of solitude, should I choose to join those carefree fools?",
  ui_story_5080_50800702_98_dialog_content = "But Jeriah, the last Caelestite is here.",
  ui_story_5080_50800702_99_dialog_content = "You should know that from the moment he's back, Eraveil will never be a forgotten memory anymore. Their story shall begin anew with an heir to carry forth those memories.",
  ui_story_5080_50800702_100_dialog_content = "Does the scenery of the world always remain the same?",
  ui_story_5080_50800702_101_dialog_content = "The capriciousness of fate doesn't only bring boredom or pain.",
  ui_story_5080_50800702_102_dialog_content = "Those connections, like firm strings, hold onto you, the unrestrainable kite...",
  ui_story_5080_50800702_103_dialog_content = "Wait! Where are you going? Don't leave!",
  ui_story_5080_50800702_104_dialog_content = "You must have felt it—they are calling out to you.",
  ui_story_5080_50800702_105_dialog_content = "In your eyes, I'm certainly not a very good teacher. But in my eyes, Jeriah... I'm very glad to have met you.",
  ui_story_5080_50800702_106_dialog_content = "Wait! Come back! Don't go! Don't go—<color=#FFB400>Attar</color>—!",
  ui_story_5080_50800702_107_dialog_content = "Jeriah!",
  ui_story_5080_50800702_108_dialog_content = "...?",
  ui_story_5080_50800702_109_dialog_content = "Great, you're awake.",
  ui_story_5080_50800702_110_dialog_content = "This little punk was freaking out... He's been sitting here trying to work his \"special moves\" on you this whole time.",
  ui_story_5080_50800702_111_dialog_content = "Sinsa...?",
  ui_story_5080_50800702_112_dialog_content = "And us too.",
  ui_story_5080_50800702_113_dialog_content = "... Why does it feel as though half of the Rediesel Wrench is here?",
  ui_story_5080_50800702_114_dialog_content = "Enchantress! Yay, you've finally woken up! Where does it hurt?",
  ui_story_5080_50800702_115_dialog_content = "Why did you leave your favorite legendary hero behind?! I woke up as soon as I heard you pull up!",
  ui_story_5080_50800702_116_dialog_content = "I was fighting off the Eclipsites when she drove after me in a frenzy, just in time to break the siege.",
  ui_story_5080_50800702_117_dialog_content = "But she was too over-excited, she didn't listen to me for a second. My only choice was to bring her here to find you...",
  ui_story_5080_50800702_118_dialog_content = "And then the cave suddenly collapsed! Doesn't it feel like something straight out of an adventure story?",
  ui_story_5080_50800702_119_dialog_content = "Regarding the cave's collapse, I felt at the time it was somewhat different from the tremors of a volcano...",
  ui_story_5080_50800702_120_dialog_content = "It's all Sinsa's fault, swinging that wrench around like a brute... I told you the cave was unstable.",
  ui_story_5080_50800702_121_dialog_content = "I didn't ask you to follow me.",
  ui_story_5080_50800702_122_dialog_content = "That's another thing—why did you call over so many people but not me? You must really have it in for me, huh...",
  ui_story_5080_50800702_123_dialog_content = "Hey, don't blame Sinsa. We were looking for just the right kind of help, that's all.",
  ui_story_5080_50800702_124_dialog_content = "Huh? You mean Jona's more useful than I am?",
  ui_story_5080_50800702_125_dialog_content = "It's dangerous out in the wilderness too. Jona needed to stay home and hold down the fort.",
  ui_story_5080_50800702_126_dialog_content = "Don't worry, once Azure gets back, Jona will come catch up.",
  ui_story_5080_50800702_127_dialog_content = "Right you are, Dawn. Jona can track Eclipsites. And you... don't sell yourself short, big guy. You know I have faith in you.",
  ui_story_5080_50800702_128_dialog_content = "No, this is all wrong! Everyone's roles are pretty clear—which one of you wrenches can't keep your mouth shut?! Why did both you and Eve show up?!",
  ui_story_5080_50800702_129_dialog_content = "Sorry... It's because I noticed you and Dawn were missing, so I asked around...",
  ui_story_5080_50800702_130_dialog_content = "Aaaaah!!! Those guys can't even keep a secret from little old Eve?!",
  ui_story_5080_50800702_131_dialog_content = "You were planning on leaving me and Eve behind, huh? Unacceptable! You hear me?! I gave my all just to catch up with you guys!",
  ui_story_5080_50800702_132_dialog_content = "Brock, you should take Eve back, it's too dangerous here.",
  ui_story_5080_50800702_133_dialog_content = "The road's collapsed—it'd be too dangerous trying to find another way back now. I suggest we let them stay.",
  ui_story_5080_50800702_134_dialog_content = "Enough arguing! Yeesh... How did things turn out like this...?",
  ui_story_5080_50800702_135_dialog_content = "Well, since we don't really have a choice anymore... Eve, Brock—you two can stay. But Eve, just make sure you stick close!",
  ui_story_5080_50800702_136_dialog_content = "Okay!",
  ui_story_5080_50800702_137_dialog_content = "Let us unite and bravely face the unknown!",
  ui_story_5080_50800702_138_dialog_content = "I've arranged a little victory celebration of my own. No one's allowed to miss it—got that, people?",
  ui_story_5080_50800702_139_dialog_content = "Remember this—don't try to be a hero! If trouble finds ya, hide behind me—that goes for you guys too, PlayerName.",
  ui_story_5080_50800702_140_dialog_content = "The Rediesel Wrench... So it's finally come to this. Oh well...",
  ui_story_5080_50800702_141_dialog_content = "You, Lollipop Girl—you can follow behind me, I...",
  ui_story_5080_50800702_142_dialog_content = "I'll protect you.",
  ui_story_5080_50800802_1_dialog_content = "Since we've come this far together, I guess there are a few things I don't need to keep hidden from you anymore.",
  ui_story_5080_50800802_2_dialog_content = "Roy, I'm just gonna tell them. The terrain here is getting lower and lower... We might just encounter the jackpot any moment now.",
  ui_story_5080_50800802_3_dialog_content = "No objections here. If there is anything you miss, I'll explain it.",
  ui_story_5080_50800802_4_dialog_content = "Why does this all feel so formal all of a sudden...?",
  ui_story_5080_50800802_5_dialog_content = "Let me take you back fifteen years. The Darkover Crisis had already erupted all over Astra—we'd been desperately resisting the outbreak for a while.",
  ui_story_5080_50800802_6_dialog_content = "No one would've guessed there was a volcano hidden beneath the camp. It erupted without warning, and a flood of Eclipsites came pouring out from the huge fissure it created.",
  ui_story_5080_50800802_7_dialog_content = "We were caught off guard and had to fight while retreating from the camp.",
  ui_story_5080_50800802_8_dialog_content = "I was only sixteen, ordered to evacuate by the head honchos. I wasn't strong enough... I could only protect Eve and the others as we fled.",
  ui_story_5080_50800802_9_dialog_content = "I was following the leaders at that time too. We were covering the rear together... but in the end, they told me to run ahead.",
  ui_story_5080_50800802_10_dialog_content = "Our leaders... They sacrificed themselves in that last battle.",
  ui_story_5080_50800802_11_dialog_content = "That wicked dragon was there too. At first, the chief seemed to be able to handle it, but—",
  ui_story_5080_50800802_12_dialog_content = "The eruptions grew more intense, and an Eclipsite dripping in magma crawled out from beneath the earth.",
  ui_story_5080_50800802_13_dialog_content = "That Eclipsite dripping in magma, there's no doubt about it—that's our target.",
  ui_story_5080_50800802_14_dialog_content = "The boss seemed to have some kind of connection with it. She was surprised and... afraid when she saw it.",
  ui_story_5080_50800802_15_dialog_content = "She said she knew how strong that thing was. That's why she told us all to get out of there.",
  ui_story_5080_50800802_16_dialog_content = "The way she gave that final command... all I could do was run. In the end, she charged forward with a few other senior members of the gang.",
  ui_story_5080_50800802_17_dialog_content = "Hmm...",
  ui_story_5080_50800802_18_dialog_content = "(I'm picking up a strong wave of emotion... Is that... Rachel?)",
  ui_story_5080_50800802_19_option_content = "(Is she losing her cool?)",
  ui_story_5080_50800802_20_dialog_content = "(Right. That leader is the same deserter who ruined her aunt's reputation.)",
  ui_story_5080_50800802_21_option_content = "(Is she refusing to believe all this?)",
  ui_story_5080_50800802_22_dialog_content = "(It must be hard for her to believe that the leader back then was the kind to sacrifice herself so nobly...)",
  ui_story_5080_50800802_23_dialog_content = "(In her heart, that leader has always been a deserter, afraid of death, but for the Rediesel Wrench, she's clearly a hero!)",
  ui_story_5080_50800802_24_dialog_content = "There's not much to say about what happened after that.",
  ui_story_5080_50800802_25_dialog_content = "Thanks to little Sinsa, although he was young, his command was clear as day. More importantly, he had the courage of a real boss.",
  ui_story_5080_50800802_26_dialog_content = "Under his leadership, we began to launch guerrilla operations, and eventually found Lepidoz.",
  ui_story_5080_50800802_27_dialog_content = "Not only did we manage to dust ourselves off, we even saved a whole bunch of stray desert nomads in the process, and our numbers started to grow.",
  ui_story_5080_50800802_28_dialog_content = "Our old leader was dead, but the crisis wasn't over. Everyone else was busy crying over our losses, so what else could I do but think of ways to cheer them up?",
  ui_story_5080_50800802_29_dialog_content = "Eve and I were outsiders. The boss had tried her best to take care of us, and everyone helped us out a lot.",
  ui_story_5080_50800802_30_dialog_content = "No one wanted to be the bad guy! No one wanted to have to spout the harsh truths people needed to hear, so I did it all! The boss was gone—we couldn't afford to lose anyone else.",
  ui_story_5080_50800802_31_dialog_content = "I didn't care who called me uncouth or unreasonable, as long as everyone survived, I felt I was doing right by the chief.",
  ui_story_5080_50800802_32_dialog_content = "I didn't really think about much else at the time.",
  ui_story_5080_50800802_33_dialog_content = "Don't be modest—it doesn't suit you, big guy.",
  ui_story_5080_50800802_34_dialog_content = "Enough of the sappy stuff! This is all beside the point!",
  ui_story_5080_50800802_35_dialog_content = "After the volcano settled down, we gradually cleared out all the Eclipsites.",
  ui_story_5080_50800802_36_dialog_content = "And after the magma cooled down, all we found back at what was left of the camp was that wrench.",
  ui_story_5080_50800802_37_dialog_content = "The wicked dragon, the boss, that Eclipsite... we couldn't find a single trace of any of them.",
  ui_story_5080_50800802_38_dialog_content = "Although no one said it out loud, we all assumed that the boss must've gone down with those monsters, and that they all died in the lava.",
  ui_story_5080_50800802_39_dialog_content = "Until the wicked dragon reared its ugly head once more...",
  ui_story_5080_50800802_40_dialog_content = "Now that Eclipsite's back too... Maybe the old boss just got eaten by those things back then.",
  ui_story_5080_50800802_41_dialog_content = "No way! She was too good for that!",
  ui_story_5080_50800802_42_dialog_content = "Well, at least we can finally get our revenge. This place we never managed to find before—it turns out a hidden route was lying here all along...",
  ui_story_5080_50800802_43_dialog_content = "In the past, the volcano would rumble and roar from time to time.",
  ui_story_5080_50800802_44_dialog_content = "Although everyone knew it was the Eclipsites making all that noise, no matter how many of them we killed, we just couldn't wipe them all out. It always felt like there must've been some undiscovered passage they were streaming in from.",
  ui_story_5080_50800802_45_dialog_content = "Hah, well, we finally found it. But we still had to come back to this damn place to do it.",
  ui_story_5080_50800802_46_dialog_content = "I... liked following her around quite a lot when I was little.",
  ui_story_5080_50800802_47_dialog_content = "I saw her power. It was no less than Sinsa's exaggerated account. She shouldn't have lost to that dragon.",
  ui_story_5080_50800802_48_dialog_content = "And... I could feel that she was enduring something I couldn't yet understand.",
  ui_story_5080_50800802_49_dialog_content = "She was desperately hiding some secret, suppressing some part of herself.",
  ui_story_5080_50800802_50_dialog_content = "Now that you mention it, yeah... the boss and I were from Illumina. I'd heard her name more times than I can remember.",
  ui_story_5080_50800802_51_dialog_content = "But when I actually met her, she was different from how I'd imagined.",
  ui_story_5080_50800802_52_dialog_content = "But I always felt like she was hiding her true self. No matter what enemy we were up against, I got the feeling she was always holding back.",
  ui_story_5080_50800802_53_dialog_content = "She only seemed to let out whatever was lying within her in the end. That's when I saw our leader's wild side unleashed for the first time.",
  ui_story_5080_50800802_54_dialog_content = "She was wilder than Sinsa on a bad day.",
  ui_story_5080_50800802_55_dialog_content = "That's quite an odd comparison to make.",
  ui_story_5080_50800802_56_dialog_content = "If even a woman like her could lose to <color=#FFB400>that Eclipsite</color>, what chance do we have?",
  ui_story_5080_50800802_57_dialog_content = "The Roaring Volcano looks like it's about to erupt, and the Darkover may strike again. Can the Rediesel Wrench really stand up to such odds?",
  ui_story_5080_50800802_58_dialog_content = "Do you really have to ask?",
  ui_story_5080_50800802_59_dialog_content = "Just bring it on!",
  ui_story_5080_50800802_60_dialog_content = "It doesn't matter what kind of Eclipsite we're up against. I'll knock 'em sky-high with this trusty wrench of mine!",
  ui_story_5080_50800802_61_dialog_content = "If that Eclipsite has the guts to face me again, oh boy, I won't let it get away this time! No way!",
  ui_story_5080_50800802_62_dialog_content = "Caelestite One, Hatchling Two—listen up.",
  ui_story_5080_50800802_63_dialog_content = "What's up? Why the sudden cloak-and-dagger routine?",
  ui_story_5080_50800802_64_dialog_content = "Our mission is... to capture that Eclipsite alive, if possible.",
  ui_story_5080_50800802_65_dialog_content = "When the time comes, prevent Sinsa from killing it.",
  ui_story_5080_50800901_1_dialog_content = "Another new path, huh? What's really going on down here?",
  ui_story_5080_50800901_2_dialog_content = "It's opening up. It looks like we've reached the true path.",
  ui_story_5080_50800901_3_dialog_content = "The world beneath the desert is a complex place to navigate, but looking at this structure... could this have been part of the Leyline Corridor's wall?",
  ui_story_5080_50800901_4_dialog_content = "When the volcano erupted, the lava burned through, and the Eclipsites dug through these holes to make a path.",
  ui_story_5080_50800901_5_dialog_content = "From the looks of these walls, they were definitely dug out, but with tools, not claws.",
  ui_story_5080_50800901_6_dialog_content = "So, this ain't Eclipsite handiwork?",
  ui_story_5080_50800901_7_dialog_content = "People have lived in the desert for a very long time. Perhaps this was the work of the ancient civilization who developed the Leyline Corridor.",
  ui_story_5080_50800901_8_dialog_content = "Look here... Intense vibrations have cracked the strata.",
  ui_story_5080_50800901_9_dialog_content = "There are cut stones down here. This was a floor, meaning this place was built by someone.",
  ui_story_5080_50800901_10_dialog_content = "What? Right next to an underground volcanic vent?!",
  ui_story_5080_50800901_11_dialog_content = "That explains the tool marks on the walls—they weren't just developing the leyline for no reason, they were building something.",
  ui_story_5080_50800901_12_dialog_content = "Hey, what's the Illumina soldier doing digging in the dirt at a time like this?",
  ui_story_5080_50800901_13_dialog_content = "Hang on—she's digging out the deepest remnants in the crevices of these building materials, searching for any stories they might be able to tell.",
  ui_story_5080_50800901_14_dialog_content = "This stone has obvious three-point indentations, and there's charred ash in the cracks.",
  ui_story_5080_50800901_15_dialog_content = "There's no mistaking it. Someone set up a pot and cooked something here a long time ago.",
  ui_story_5080_50800901_16_dialog_content = "From here to where we came in, it's about the size of a room—this was an underground shelter.",
  ui_story_5080_50800901_17_dialog_content = "A long time ago, there probably weren't any Eclipsites here, but it was most likely a refuge for a group of people.",
  ui_story_5080_50800901_18_dialog_content = "They hid here until the volcanic eruption buried everything.",
  ui_story_5080_50800901_19_dialog_content = "Very impressive. With just a few words, you've unearthed the ancient stories buried here.",
  ui_story_5080_50800901_20_dialog_content = "I've never seen anything like this before... No wonder you made scout captain at such a young age.",
  ui_story_5080_50800901_21_dialog_content = "Sinsa, have you ever heard anything about people living underground here?",
  ui_story_5080_50800901_22_dialog_content = "Eve and I are basically outsiders too. We don't know all those old tales.",
  ui_story_5080_50800901_23_dialog_content = "Roy and I are from Illumina, and though he's certainly been around, he probably doesn't know about this kind of stuff either.",
  ui_story_5080_50800901_24_dialog_content = "Why are you looking at me? I'm too young to know about this stuff. Plus, if Sinsa doesn't know about it, why would I?",
  ui_story_5080_50800901_25_dialog_content = "If there used to be people here, how come you've never heard anything about it?",
  ui_story_5080_50800901_26_dialog_content = "Even I hadn't heard about it! Could this be some super ancient relic? Maybe there's some epic power buried here, like a mega-powerful Lumina giant!?",
  ui_story_5080_50800901_27_dialog_content = "My bad... I should've made sure the kids studied their history, but nobody seemed to care about the past.",
  ui_story_5080_50800901_28_dialog_content = "You had me organize and send over books every month, and they've just been gathering dust.",
  ui_story_5080_50800901_29_dialog_content = "Sorry, Jeriah.",
  ui_story_5080_50800901_30_dialog_content = "We've got bigger fish to fry right now!",
  ui_story_5080_50800901_31_dialog_content = "Right! A legendary warrior like me has no time for old stories!",
  ui_story_5080_50800901_32_dialog_content = "Ah... I expected as much, but hearing you all actually say it... There really is no hope for this world.",
  ui_story_5080_50800901_33_dialog_content = "Everyone really only cares about the present instead of exploring what the land beneath their feet and the legacy of their predecessors truly means.",
  ui_story_5080_50800901_34_dialog_content = "Miss Jeriah, you must know something, right? Please tell us!",
  ui_story_5080_50800901_35_dialog_content = "My research on the desert isn't exactly extensive, but when it comes to shelters, a certain legend springs to mind.",
  ui_story_5080_50800901_36_dialog_content = "It's also the Rediesel Wrench's origin story.",
  ui_story_5080_50800901_37_dialog_content = "Wasn't it because our old boss conquered the bandits that the Rediesel Wrench was formed?",
  ui_story_5080_50800901_38_dialog_content = "Long ago, the desert was home to nomads and outlaws, living without any real semblance of order.",
  ui_story_5080_50800901_39_dialog_content = "Perhaps they were afraid of the outside world, or tired of it, preferring to live in the harsh environment of the desert.",
  ui_story_5080_50800901_40_dialog_content = "They believed this place to be their freedom.",
  ui_story_5080_50800901_41_dialog_content = "Freedom...",
  ui_story_5080_50800901_42_dialog_content = "One day, a young noblewoman from Lumopolis, persecuted by her family, was brought into the desert by her maid.",
  ui_story_5080_50800901_43_dialog_content = "The maid wanted to take her to her hometown, far from all strife.",
  ui_story_5080_50800901_44_dialog_content = "The strife of Lumopolis... I see.",
  ui_story_5080_50800901_45_dialog_content = "A guard from the city was sent after them. He believed in a knight's honor above all else.",
  ui_story_5080_50800901_46_dialog_content = "Interestingly, an Illumina soldier had also ventured into the desert at that time, searching the villages for Illumina deserters.",
  ui_story_5080_50800901_47_dialog_content = "He was after a disillusioned Illumina engineer who had lost his will to serve.",
  ui_story_5080_50800901_48_dialog_content = "A disillusioned Illumina soldier...",
  ui_story_5080_50800901_49_dialog_content = "During the chase, the Illumina agent, due to a mix-up, mistakenly thought the Lumo Guard was after the same person as him.",
  ui_story_5080_50800901_50_dialog_content = "The young lady and her maid, encountering the engineer, mistook him for a bounty hunter.",
  ui_story_5080_50800901_51_dialog_content = "They feared each other, and began chasing each other, yet were closely connected by the fickleness of fate.",
  ui_story_5080_50800901_52_dialog_content = "With the engineer's intervention, the young lady and her maid successfully escaped the knight.",
  ui_story_5080_50800901_53_dialog_content = "And thanks to the knight's blunder, the agent lost his deserter, ending up tracking him only to Saltstone Village.",
  ui_story_5080_50800901_54_dialog_content = "It sounds like this legend is all about fools.",
  ui_story_5080_50800901_55_dialog_content = "Indeed, but because they were fools, they never truly harmed each other.",
  ui_story_5080_50800901_56_dialog_content = "They all held onto their beliefs, clearly having the opportunity to strike, yet not wanting to hurt one another.",
  ui_story_5080_50800901_57_dialog_content = "I think I like stories like this.",
  ui_story_5080_50800901_58_dialog_content = "On the last leg of their journey, they encountered a rare sandstorm. Everything on their path was devoured by the raging sands.",
  ui_story_5080_50800901_59_dialog_content = "Just in the nick of time, the hunted helped the hunters, and the hunters gave up their chase.",
  ui_story_5080_50800901_60_dialog_content = "After all that had taken place, the hunters' missions were long overdue, and they themselves would be deemed deserters.",
  ui_story_5080_50800901_61_dialog_content = "Stuck in the same boat, mutual support finally led them to understand and trust each other.",
  ui_story_5080_50800901_62_dialog_content = "They made a pact to reach Saltstone Village together, to settle down and live in peace there.",
  ui_story_5080_50800901_63_dialog_content = "Did they get their fairy tale ending?",
  ui_story_5080_50800901_64_dialog_content = "No. When they arrived at the maid's hometown, the supposed oasis of Saltstone Village, they found it had been destroyed by a volcanic eruption.",
  ui_story_5080_50800901_65_dialog_content = "The survivors were also being targeted by bandits and were trapped in a living hell.",
  ui_story_5080_50800901_66_dialog_content = "The oasis didn't exist. They were doomed to never find peace.",
  ui_story_5080_50800901_67_dialog_content = "The outsiders lost hope, realizing that this place was no different from the world they had left behind...",
  ui_story_5080_50800901_68_dialog_content = "...",
  ui_story_5080_50800901_69_dialog_content = "The survivors, led by the village oracle, fled toward the village gates, just in time to meet these outsiders.",
  ui_story_5080_50800901_70_dialog_content = "Those seeking a haven suddenly became a haven for others.",
  ui_story_5080_50800901_71_dialog_content = "Flustered, neither the resolute knight nor the uncompromising soldier could fathom what was being asked of them at that moment.",
  ui_story_5080_50800901_72_dialog_content = "Faced with a matter of life and death, no one expected the engineer to raise the wrench in his hand and charge at the bandits.",
  ui_story_5080_50800901_73_dialog_content = "His brave act inspired the others, and the bandits were finally driven away.",
  ui_story_5080_50800901_74_dialog_content = "What a heroic tale! Let me guess—that wrench is the legendary Rediesel Wrench, am I right?",
  ui_story_5080_50800901_75_dialog_content = "Don't get ahead of yourself, the story's not over yet.",
  ui_story_5080_50800901_76_dialog_content = "Because of that engineer, the people found hope once again. And so, they set off once more, searching for a new oasis in the desert.",
  ui_story_5080_50800901_77_dialog_content = "Along the way, they gradually absorbed more nomads into the fold, becoming a formidable force without even realizing it.",
  ui_story_5080_50800901_78_dialog_content = "Eventually, they found a small oasis rich in rediesel and settled down there.",
  ui_story_5080_50800901_79_dialog_content = "That's the legend Attar... no, the previous leader told me.",
  ui_story_5080_50800901_80_dialog_content = "It proves that long ago, this desert was inhabited by Aurorians.",
  ui_story_5080_50800901_81_dialog_content = "Those people, just like us, were all striving to find their own way of life.",
  ui_story_5080_50800901_82_dialog_content = "These underground shelters were probably places to escape pursuers or bandits, correct?",
  ui_story_5080_50800901_83_dialog_content = "But whether these people were engulfed by the erupting volcano or abandoned upon discovering the volcano deep in the tunnels... I don't know.",
  ui_story_5080_50800901_84_dialog_content = "Tsk, I'm getting kinda jealous over here... It's not fair! Why'd the old boss tell all that to you and not us?",
  ui_story_5080_50800901_85_dialog_content = "Well, that's just because you didn't show the slightest bit of interest.",
  ui_story_5080_50800901_86_dialog_content = "I was full of curiosity and very interested in her stories, always pestering her to tell me more.",
  ui_story_5080_50800901_87_dialog_content = "But on reflection, it feels as though the more you know, the more you become wrapped in a sense of nothingness—a sense that the past will eventually fade away...",
  ui_story_5080_50800901_88_dialog_content = "You know, Sinsa, you were just a newbie back then, always busy babysitting your sister.",
  ui_story_5080_50800901_89_dialog_content = "Life wasn't all sunshine and rainbows back then—we were scrounging for food day in and day out.",
  ui_story_5080_50800901_90_dialog_content = "You had your hands full too, teaching Azure to drive, remember?",
  ui_story_5080_50800901_91_dialog_content = "Just being alive was incredible enough... I always thought living in the now was all that mattered.",
  ui_story_5080_50800901_92_dialog_content = "Back then, we didn't have the means to go digging up the past.",
  ui_story_5080_50800901_93_dialog_content = "But hey, times have changed!",
  ui_story_5080_50800901_94_dialog_content = "Now, life at Rediesel Wrench is all sunshine and rainbows... and I'm set to become the sharpest wrench in the toolbox!",
  ui_story_5080_50800901_95_dialog_content = "Just you wait, Sinsa. I'll hit the books hard when we're back and become a better leader than you one day!",
  ui_story_5080_50800901_96_dialog_content = "You little punk... Isn't our cushy life all thanks to my blood, sweat, and tears?",
  ui_story_5080_50800901_97_dialog_content = "You mean to say that in the story, that person who raised his wrench became some kind of spiritual symbol.",
  ui_story_5080_50800901_98_dialog_content = "But an Illumina engineer's wrench is not a weapon, and has never possessed such exaggerated dimensions.",
  ui_story_5080_50800901_99_dialog_content = "The wrench in Sinsa's hands probably weighs a ton now, right?",
  ui_story_5080_50800901_100_dialog_content = "That's right. Aside from me, you won't find many who can just twirl it around like it's nothing.",
  ui_story_5080_50800901_101_dialog_content = "What kind of engineer would carry such a wrench?",
  ui_story_5080_50800901_102_dialog_content = "Little bird of prey, are you saying this story is not true?",
  ui_story_5080_50800901_103_dialog_content = "This legend may have been concocted by your leader to beautify the past of the Rediesel Wrench.",
  ui_story_5080_50800901_104_dialog_content = "According to Illumina's records, this desert has always been overrun by bandits, stirring up trouble and inciting many to become deserters.",
  ui_story_5080_50800901_105_dialog_content = "These people called themselves the Rediesel Gang, and constantly threatened other Aurorians.",
  ui_story_5080_50800901_106_dialog_content = "That person... first turned my aunt into a deserter, then joined the Rediesel Gang after fleeing here. She later became their leader.",
  ui_story_5080_50800901_107_dialog_content = "She forced nomads to join her to grow her power, slowly expanding her rule over the desert and turning it into the Rediesel Wrench.",
  ui_story_5080_50800901_108_dialog_content = "These stories are just fabrications she created to cast the history of the Rediesel Wrench in a positive light.",
  ui_story_5080_50800901_109_dialog_content = "Hey, you little Illumina brat! Didn't anyone ever teach you not to spout nonsense about someone people look up to?",
  ui_story_5080_50800901_110_dialog_content = "Just 'cause we're buddies for now, that doesn't mean you get to run your mouth!",
  ui_story_5080_50800901_111_dialog_content = "Wait, why would you even say that, Captain? If, as you say, she ruled the desert, why would she need to bother prettying up the past?",
  ui_story_5080_50800901_112_dialog_content = "I can't picture the leader Sinsa and the others believe in being that kind of person.",
  ui_story_5080_50800901_113_dialog_content = "Did she... really want to protect everyone?",
  ui_story_5080_50800901_114_dialog_content = "And so she wanted to protect you from the truth.",
  ui_story_5080_50800901_115_dialog_content = "...",
  ui_story_5080_50800901_116_dialog_content = "Tsk, so you can understand people, huh?",
  ui_story_5080_50800901_117_dialog_content = "Wait... Is that another earthquake?",
  ui_story_5080_50800901_118_dialog_content = "No, that's the sound of the Eclipsite horde.",
  ui_story_5080_50800901_119_dialog_content = "Look here, Miss Soldier Ant of Illumina. This is how we roll at the Rediesel Wrench, this is the pledge we all made to keep our family safe!",
  ui_story_5080_50800901_120_dialog_content = "Now, pay attention—we're about to show you exactly what our brand of bravery looks like!",
  ui_story_5080_50801000_1_dialog_content = "Look at all these burns... You got too fired up.",
  ui_story_5080_50801000_2_dialog_content = "Heh, a scratch here and there... I've seen worse!",
  ui_story_5080_50801000_3_dialog_content = "Hey, Roy, is it chow time yet? The gang's gotta be starving!",
  ui_story_5080_50801000_4_dialog_content = "What's on the menu?",
  ui_story_5080_50801000_5_dialog_content = "That's right—dinner time, dinner time! Kids, set up the pot!",
  ui_story_5080_50801000_6_dialog_content = "Let's roll, Dawn! Time to snag us some volcanic delicacies!",
  ui_story_5080_50801000_7_dialog_content = "What are you doing?",
  ui_story_5080_50801000_8_dialog_content = "Work hard, play hard, little Illumina lady.",
  ui_story_5080_50801000_9_dialog_content = "Don't look so shocked. They're always like this. They never slack off when it comes to food.",
  ui_story_5080_50801000_10_dialog_content = "If you're not keen on their exotic cuisine, we brought some food too.",
  ui_story_5080_50801000_11_dialog_content = "But, we're on a mission right now!",
  ui_story_5080_50801000_12_dialog_content = "How can you just eat like this...? What if we're ambushed?",
  ui_story_5080_50801000_13_dialog_content = "Hatchling Two, Caelestite One, White Lancer—continue your mission.",
  ui_story_5080_50801000_14_dialog_content = "Yes, Captain!",
  ui_story_5080_50801000_15_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5080_50801000_16_dialog_content = "Oops... My bad... I skipped breakfast this morning...",
  ui_story_5080_50801000_17_dialog_content = "...",
  ui_story_5080_50801000_18_dialog_content = "Captain, a seasoned Illumina soldier used to tell us, \"Eat up! A full belly gives you the strength to fight until the next meal!\"",
  ui_story_5080_50801000_19_dialog_content = "He swore by this rule, and everyone agreed.",
  ui_story_5080_50801000_20_dialog_content = "Zeta and Vice have been busy fighting and traveling since they got up...",
  ui_story_5080_50801000_21_dialog_content = "Those old Illumina soldiers know all about battling on an empty stomach.",
  ui_story_5080_50801000_22_dialog_content = "Yet they still persevered.",
  ui_story_5080_50801000_23_dialog_content = "That's why they hope the younger generation can eat better than they did.",
  ui_story_5080_50801000_24_dialog_content = "I suppose we cannot move on without replenishing our energy. To ensure the mission is completed, I will grant you time to eat.",
  ui_story_5080_50801000_25_dialog_content = "I'll stand guard. Not everyone can afford to relax...",
  ui_story_5080_50801000_26_dialog_content = "Captain, at least eat some of these compressed rations! Captain...!",
  ui_story_5080_50801000_27_dialog_content = "Let her be, she just wants to make sure this mission is executed flawlessly.",
  ui_story_5080_50801000_28_dialog_content = "We're back—Hey, you started without us!",
  ui_story_5080_50801000_29_dialog_content = "Heroes are all about efficiency! I'm off to go stand guard!",
  ui_story_5080_50801000_30_dialog_content = "... The speed at which you eat is commendable. With training, you could become a fine soldier.",
  ui_story_5080_50801000_31_dialog_content = "I don't wanna be an Illumina soldier. I'm destined to save the world!",
  ui_story_5080_50801000_32_dialog_content = "Have a taste! This roasted bug jerky's yummy! I brought it over just for you.",
  ui_story_5080_50801000_33_dialog_content = "Thank you... Lollipop Girl.",
  ui_story_5080_50801000_34_dialog_content = "I'm the Savior of the World, not some side character!",
  ui_story_5080_50801000_35_dialog_content = "You're cool and all, but your taste needs work! Must be 'cause you were raised by the Demon King, huh?",
  ui_story_5080_50801000_36_dialog_content = "Tough break, Savior of the World's Long-Lost Arch-Enemy Sister!",
  ui_story_5080_50801000_37_dialog_content = "Sister?",
  ui_story_5080_50801000_38_dialog_content = "Yeah! We're Warrior Sisters now! Don't worry, I'll find a way to free you from those mental chains of yours!",
  ui_story_5080_50801000_39_dialog_content = "Huh? You're smiling? That's the first time I've seen you smile... Must be the power of family, right?!",
  ui_story_5080_50801000_40_dialog_content = "Don't mind her; she just likes to play make-believe, make-up stories, and so on.",
  ui_story_5080_50801000_41_dialog_content = "Sisters... Hmm...",
  ui_story_5080_50801000_42_dialog_content = "You seem to have been reminded of something. Do you have a sister, by any chance?",
  ui_story_5080_50801000_43_dialog_content = "Yes... she's very smart, stronger than I am, and... just adorable.",
  ui_story_5080_50801000_44_dialog_content = "Once she finishes her studies, she'll become an exemplary soldier.",
  ui_story_5080_50801000_45_dialog_content = "I'm proud of her.",
  ui_story_5080_50801000_46_dialog_content = "What...? Ugh...",
  ui_story_5080_50801000_47_dialog_content = "Zeta, you look unconvinced.",
  ui_story_5080_50801000_48_dialog_content = "She's making me jealous... I mean! Not jealous! Just...",
  ui_story_5080_50801000_49_dialog_content = "Having a sister like you, your little sister must be so happy.",
  ui_story_5080_50801000_50_dialog_content = "'Cause Eagleshot's way nicer than that witch.",
  ui_story_5080_50801000_51_dialog_content = "No, I'm still a long way from being good enough.",
  ui_story_5080_50801000_52_dialog_content = "I'll keep trying... trying... not to cause any more trouble for my family.",
  ui_story_5080_50801000_53_dialog_content = "Oh, la, la, la!",
  ui_story_5080_50801000_54_dialog_content = "What's with the sudden serenade? I can't even hear myself think!",
  ui_story_5080_50801000_55_dialog_content = "You haven't heard? Barbara told him he's got more potential than you, so he's been training like crazy lately.",
  ui_story_5080_50801000_56_dialog_content = "What?!",
  ui_story_5080_50801000_57_dialog_content = "\"The Rediesel's First Tenor, more rousing than Sinsa\"—Barbara's words.",
  ui_story_5080_50801000_58_dialog_content = "So he's training like crazy, gearing up to charm everyone's socks off with his vocal stylings.",
  ui_story_5080_50801000_59_dialog_content = "Wow, then I guess I have to practice too. I promised them I'd join the band.",
  ui_story_5080_50801000_60_dialog_content = "Where are those drumsticks... Not this... not that, either... Bingo!",
  ui_story_5080_50801000_61_dialog_content = "Alright, I'm here to keep the beat. Let's get to it!",
  ui_story_5080_50801000_62_dialog_content = "These people...",
  ui_story_5080_50801000_63_dialog_content = "Crank it up, Fleur! Pour your heart and soul into those drumsticks!",
  ui_story_5080_50801000_64_dialog_content = "Are you in harmony with me? Caught up with my voice yet?",
  ui_story_5080_50801000_65_dialog_content = "Unless you keep it down, even the Eclipsites are gonna catch up with your voice.",
  ui_story_5080_50801000_66_dialog_content = "Don't bang on the walls, Fleur! Careful not to alert the Eclipsites!",
  ui_story_5080_50801000_67_dialog_content = "It's a good thing Sinsa has some common sense, Rediesel Wrench...",
  ui_story_5080_50801000_68_dialog_content = "Take the wrench. If you wanna practice, get banging with this! Go ahead, knock yourself out!",
  ui_story_5080_50801000_69_dialog_content = "Aren't you afraid of attracting the Eclipsites?",
  ui_story_5080_50801000_70_dialog_content = "That's not really a big deal, is it? We're itching to find 'em anyway. Raise the pitch, higher! Higher!",
  ui_story_5080_50801000_71_dialog_content = "Ah... Truly incorrigible.",
  ui_story_5080_50801000_72_dialog_content = "Living in this vast desert, they've never developed a spirit of inquiry. All they do is fool around every day...",
  ui_story_5080_50801000_73_dialog_content = "But Jeriah, what is the spirit of inquiry, exactly?",
  ui_story_5080_50801000_74_dialog_content = "Little Caelestite, are you starting to have your doubts too?",
  ui_story_5080_50801000_75_dialog_content = "No, I just think that... even though they live in such a harsh environment, you never hear Sinsa and the others complaining.",
  ui_story_5080_50801000_76_dialog_content = "They're always trying to find the joy in life, and they seem pretty good at it.",
  ui_story_5080_50801000_77_dialog_content = "I always get the feeling that they're already full of the spirit of inquiry, when it comes to exploring their own lives.",
  ui_story_5080_50801000_78_dialog_content = "Yeah, Miss Jeriah. You know so much, but it seems like you're a little too negative about life in general...",
  ui_story_5080_50801000_79_dialog_content = "No offense, of course, but... is that really the way you want to be?",
  ui_story_5080_50801000_80_dialog_content = "Coming from an Illumina soldier such as Vice, I'm not entirely sure how to respond.",
  ui_story_5080_50801000_81_dialog_content = "Perhaps you believe people from Illumina don't have the right to lecture others on life and liberty.",
  ui_story_5080_50801000_82_dialog_content = "But I grew up there, and I know all too well—the purpose of Illumina is to serve as a shield, to protect all those behind us.",
  ui_story_5080_50801000_83_dialog_content = "We may have to make sacrifices, but I know that the people behind that shield can live happily.",
  ui_story_5080_50801000_84_dialog_content = "The smiles on their faces are what I strive to protect.",
  ui_story_5080_50801000_85_dialog_content = "I'm happy to see them doing all they can to live their lives. Seeing them so free is good enough for me.",
  ui_story_5080_50801000_86_dialog_content = "The meaning of... protection...?!",
  ui_story_5080_50801000_87_dialog_content = "So, you all have different views on life.",
  ui_story_5080_50801000_88_dialog_content = "Living for others? In my view, it's not exactly what I would call being entirely free, but it's still admirable.",
  ui_story_5080_50801000_89_dialog_content = "Hmm, how should I understand this? You're supposed to explore life on your own terms, yet you're so closely connected to others...",
  ui_story_5080_50801000_90_dialog_content = "I still believe the bonds that exist between people can't be severed.",
  ui_story_5080_50801000_91_dialog_content = "Even you, Jeriah, can't erase the ties you've formed with us... even if you don't want to become a happy-go-lucky fool.",
  ui_story_5080_50801000_92_dialog_content = "... Right, the house is now a canvas of doodles, a mountain of gifts and books for the children.",
  ui_story_5080_50801000_93_dialog_content = "No matter how sneaky I try to be, those kids still manage to catch me, and they've even taken my car out for a joyride.",
  ui_story_5080_50801000_94_dialog_content = "They dinged it up pretty good, but I patched it up real nice!",
  ui_story_5080_50801000_95_dialog_content = "Some pretty unique patches too.",
  ui_story_5080_50801000_96_dialog_content = "After all this, Jeriah, do you still think you're all alone?",
  ui_story_5080_50801000_97_dialog_content = "What's this, little Caelestite? Are you really so concerned about my social connections? Are you that worried about me?",
  ui_story_5080_50801000_98_dialog_content = "Even if I try to blend in with these people, it won't lessen my wanderlust.",
  ui_story_5080_50801000_99_dialog_content = "Alright, that's the beat!",
  ui_story_5080_50801000_100_dialog_content = "I can feel your fire, I feel your vibe—now let's really belt it out!",
  ui_story_5080_50801000_101_dialog_content = "<color=#e8d9bb>Under Sinsa's command, the Rediesel Wrench belt out their song like crazy.</color>",
  ui_story_5080_50801000_102_dialog_content = "<color=#e8d9bb>It's a totally discordant chorus, but everyone gives it their all, never once thinking of stopping—it's their own special kind of harmony.</color>",
  ui_story_5080_50801000_103_dialog_content = "Their personalities are just too distinct and prominent, not the kinds that blend together.",
  ui_story_5080_50801000_104_dialog_content = "Yet this motley crew of unique characters has become family.",
  ui_story_5080_50801000_105_dialog_content = "Keep singing, just watch the soup pot.",
  ui_story_5080_50801000_106_dialog_content = "Oh, Jeriah, I saw an amazing thing they had there called hot pot when I was in Longzhou.",
  ui_story_5080_50801000_107_dialog_content = "You cook up a spicy broth, toss in whatever food you want, and just fish it out when you want to eat it.",
  ui_story_5080_50801000_108_dialog_content = "No matter what you throw in that spicy hot pot, the flavors don't get mixed up.",
  ui_story_5080_50801000_109_dialog_content = "Everyone living in the desert right now is kind of like a hot pot.",
  ui_story_5080_50801000_110_dialog_content = "Rediesel is unbelievable. The desert's so vast, with enough room for everyone to stretch out and explore their life's journey...",
  ui_story_5080_50801000_111_dialog_content = "Hot pot... you say?",
  ui_story_5080_50801000_112_dialog_content = "Jeriah, listen—do you hear that? That falcon's singing.",
  ui_story_5080_50801000_113_dialog_content = "It's just a bird's cry, nothing more.",
  ui_story_5080_50801000_114_dialog_content = "Hahaha... Jeriah, how do you know it's not singing a song for its own journey?",
  ui_story_5080_50801000_115_dialog_content = "... Why did you tell me that legend?",
  ui_story_5080_50801000_116_dialog_content = "Isn't it amazing? Strangers born in Rediesel, Lumopolis, and Illumina eventually become a big family despite everyone's differences.",
  ui_story_5080_50801000_117_dialog_content = "Though living in this world of endless calamity, lonely souls are still willing to share their emotions.",
  ui_story_5080_50801000_118_dialog_content = "Some are willing to raise a wrench to protect others and become leaders. Others are willing to follow such people and work together.",
  ui_story_5080_50801000_119_dialog_content = "The desert has become our home.",
  ui_story_5080_50801000_120_dialog_content = "Merely passing through the sky on their journey, they gather into flocks, finding their own oasis.",
  ui_story_5080_50801000_121_dialog_content = "Jeriah, strive to explore the breadth of your own life, fly high, and sing your heart out!",
  ui_story_5080_50801000_122_dialog_content = "How can you continue wandering forever? There's already a place for you here—",
  ui_story_5080_50801101_1_dialog_content = "<color=#e8d9bb>The sound of the guitar, burning like the sun, pierces through the desert heat, calming the trembling ground.</color>",
  ui_story_5080_50801101_2_dialog_content = "Onward, onward! My spirit will never die!",
  ui_story_5080_50801101_3_dialog_content = "It's baking out here, and she's still practicing new tunes. Good for her.",
  ui_story_5080_50801101_4_dialog_content = "I won't be outdone! Tiny One, it's our turn!",
  ui_story_5080_50801101_5_dialog_content = "The stage is set. I've got stuff to do, you go on.",
  ui_story_5080_50801101_6_dialog_content = "Hello? This is the Rediesel Wrench...",
  ui_story_5080_50801101_7_dialog_content = "Bopper, Jona's rushing me to come back. What's going on?",
  ui_story_5080_50801101_8_dialog_content = "Look out! The ever-shining idol is here! The Diesel Sweety, Barbara!",
  ui_story_5080_50801101_9_dialog_content = "Hello? This is the Rediesel Wrench... Azure, is that you?",
  ui_story_5080_50801101_10_dialog_content = "Wow, it's buzzing over there.",
  ui_story_5080_50801101_11_dialog_content = "The fierce sun is blazing! The fierce sun rages on!!!",
  ui_story_5080_50801101_12_dialog_content = "Hello? This is the Rediesel Wrench...",
  ui_story_5080_50801101_13_dialog_content = "Hello? I can't hear a thing. Forget it, I'll just wait for sis to come back.",
  ui_story_5080_50801101_14_dialog_content = "Hey, Maggie, did you set up those landmines properly?",
  ui_story_5080_50801101_15_dialog_content = "It's so hot though... I got it, I got it, I'll do it now!",
  ui_story_5080_50801101_16_dialog_content = "Let's cover the entire camp perimeter before sunset!",
  ui_story_5080_50801101_17_dialog_content = "Do we really need all these traps?",
  ui_story_5080_50801101_18_dialog_content = "<color=#e8d9bb>The desert's tremors continue. The distant volcano roars, venting its rage.</color>",
  ui_story_5080_50801101_19_dialog_content = "The leaders have been gone a long time...",
  ui_story_5080_50801101_20_dialog_content = "No response to communications.",
  ui_story_5080_50801101_21_dialog_content = "Tiny One, Fleur's out right now, come help me fix the truck.",
  ui_story_5080_50801101_22_dialog_content = "Hmph, is that a challenge? You still won't admit that I'm better?",
  ui_story_5080_50801101_23_dialog_content = "What are you talking about!?",
  ui_story_5080_50801101_24_dialog_content = "Should we set out aboard Lepidoz?",
  ui_story_5080_50801101_25_dialog_content = "Hey, Bopper, was that Azure on the line?",
  ui_story_5080_50801101_26_dialog_content = "I don't know...",
  ui_story_5080_50801101_27_dialog_content = "How can you not know if you took the call?",
  ui_story_5080_50801101_28_dialog_content = "Go back out on patrol, and later...",
  ui_story_5080_50801101_29_dialog_content = "Forget it, it's gotta be Azure. Who else could it be?",
  ui_story_5080_50801101_30_dialog_content = "I can't miss this rare chance. I've gotta take her out for a drink after all this.",
  ui_story_5080_50801101_31_dialog_content = "... Hear me out.",
  ui_story_5080_50801101_32_dialog_content = "We're here, right by the volcano's mouth.",
  ui_story_5080_50801101_33_dialog_content = "All we've gotta do is jump down here, and we're inside the volcano—",
  ui_story_5080_50801101_34_dialog_content = "The activity level of this volcano... Eagle Hunter One, activate detection mode!",
  ui_story_5080_50801101_35_dialog_content = "... As expected, this volcano is extremely active.",
  ui_story_5080_50801101_36_dialog_content = "Why hasn't it reached eruption yet?",
  ui_story_5080_50801101_37_dialog_content = "This isn't a dormant volcano waking up. It's always been this active.",
  ui_story_5080_50801101_38_dialog_content = "It hasn't erupted in all these years.",
  ui_story_5080_50801101_39_dialog_content = "Strange...",
  ui_story_5080_50801101_40_dialog_content = "Whoa, is this for real? Eclipsites are crawling out of the volcano's mouth!",
  ui_story_5080_50801101_41_dialog_content = "Those Eclipsites... their lava energy must be coming from here.",
  ui_story_5080_50801101_42_dialog_content = "Time to go! Jump!",
  ui_story_5080_50801101_43_dialog_content = "Vice... Carleen... Wait for me! It's so high!",
  ui_story_5080_50801102_1_dialog_content = "Eclipsites count as living creatures, right?",
  ui_story_5080_50801102_2_dialog_content = "How come they're capable of living in the mouth of this volcano, not only utilizing the lava's energy but also completely unafraid of it?",
  ui_story_5080_50801102_3_dialog_content = "Fleur, do the math for us, won't you? How do we blow this volcano's mouth sky-high?",
  ui_story_5080_50801102_4_dialog_content = "If the Eclipsites aren't scared of the lava, this might be the only way to keep them from coming back.",
  ui_story_5080_50801102_5_dialog_content = "That won't do. That lady's right, this is an active volcano. Any rash blasting might trigger an eruption.",
  ui_story_5080_50801102_6_dialog_content = "The tremors won't stop. The Eclipsites are gonna keep coming out from the volcano's depths...",
  ui_story_5080_50801102_7_dialog_content = "We don't know what's happening outside, so we need to make this quick.",
  ui_story_5080_50801102_8_dialog_content = "Why has this volcano been so active yet seemingly dormant for so long?",
  ui_story_5080_50801102_9_dialog_content = "What could be the reason?",
  ui_story_5080_50801102_10_dialog_content = "The volcano's fury is likely due to unstable leyline energy.",
  ui_story_5080_50801102_11_dialog_content = "If we can find the cause, maybe we can solve this crisis.",
  ui_story_5080_50801102_12_dialog_content = "No matter what, we gotta move fast.",
  ui_story_5080_50801102_13_dialog_content = "If this shaking keeps up, even the Eclipsites will be spooked to the surface.",
  ui_story_5080_50801102_14_dialog_content = "The Rediesels might be tough cookies, but what about the villagers?",
  ui_story_5080_50801102_15_dialog_content = "Very true. Any thoughts, Sinsa?",
  ui_story_5080_50801102_16_dialog_content = "There's nothing else for it. If these guys are coming from inside, I'll have to go in.",
  ui_story_5080_50801102_17_dialog_content = "<size=45>What?!</size>",
  ui_story_5080_50801102_18_dialog_content = "Are you feeling alright? This is a volcano we're talking about, Sinsa.",
  ui_story_5080_50801102_19_dialog_content = "I'm feeling right as rain, thank you very much. That's why I can't just ignore this thing.",
  ui_story_5080_50801102_20_dialog_content = "I'm sick of its rumbling. Whether it's for grudges old or grudges new, I'm settling the score once and for all.",
  ui_story_5080_50801102_21_dialog_content = "Why... are you pushing yourself so hard?",
  ui_story_5080_50801102_22_dialog_content = "Hah! Funny hearing that from you.",
  ui_story_5080_50801102_23_dialog_content = "After all, the Rediesel Wrench are known as deserters, and you're from a similar background.",
  ui_story_5080_50801102_24_dialog_content = "You've all survived this long by plundering others, haven't you? Just going with the flow, living day by day.",
  ui_story_5080_50801102_25_dialog_content = "Why would you risk your life now?",
  ui_story_5080_50801102_26_dialog_content = "Alright, now it's my turn to grill you. What were you doing in Illumina? Why trek all the way to this volcano?",
  ui_story_5080_50801102_27_dialog_content = "I'm the captain of the Eagleeye Squad! I've led my team through over forty high-stakes special operations.",
  ui_story_5080_50801102_28_dialog_content = "Without me, the others would've faced even greater danger.",
  ui_story_5080_50801102_29_dialog_content = "I came for glory. I'm nothing like you people.",
  ui_story_5080_50801102_30_dialog_content = "You know, Fleur and that other geezer were both born in Gannon City.",
  ui_story_5080_50801102_31_dialog_content = "They didn't get any glory there—instead, they had to escape to the desert because they felt they were suffocating.",
  ui_story_5080_50801102_32_dialog_content = "What even is glory, anyway?",
  ui_story_5080_50801102_33_dialog_content = "Glory is—",
  ui_story_5080_50801102_34_dialog_content = "Miss Illumina, enlighten me—do you truly grasp the meaning of \"sacrifice\"?",
  ui_story_5080_50801102_35_dialog_content = "For Illumina, for the liberation of all Aurorians, no matter the cost!",
  ui_story_5080_50801102_36_dialog_content = "I'm ready to sacrifice everything for that grand cause!",
  ui_story_5080_50801102_37_dialog_content = "...",
  ui_story_5080_50801102_38_dialog_content = "Why are you looking at me like that?",
  ui_story_5080_50801102_39_dialog_content = "Is that how you convince yourself?",
  ui_story_5080_50801102_40_dialog_content = "Never mind. It's pointless to talk to you about this right now.",
  ui_story_5080_50801102_41_dialog_content = "Roy, she's still living in a dream world.",
  ui_story_5080_50801102_42_dialog_content = "You...!",
  ui_story_5080_50801102_43_dialog_content = "Excuse me, I gotta clean up a bunch of bugs infesting my home. Stay out of my way.",
  ui_story_5080_50801102_44_dialog_content = "Hey, Sinsa, who said you could clean up alone? Don't forget about us!",
  ui_story_5080_50801102_45_dialog_content = "You guys, don't all crowd in. It's dangerous.",
  ui_story_5080_50801102_46_dialog_content = "You're one to talk, dummy!",
  ui_story_5080_50801102_47_dialog_content = "Jumping into a volcano together? This seems like an unwise choice.",
  ui_story_5080_50801102_48_dialog_content = "Ready, everyone... Whoa!",
  ui_story_5080_50801102_49_dialog_content = "It's an earthquake! Be careful!",
  ui_story_5080_50801102_50_dialog_content = "<color=#e8d9bb>Out of nowhere, an earthquake strikes, and those of us standing near the volcano's edge tumble into it.</color>",
  ui_story_5080_50801102_51_dialog_content = "Sinsa!",
  ui_story_5080_50801102_52_dialog_content = "Eve! Everyone! I'm coming!",
  ui_story_5080_50801102_53_dialog_content = "Don't even think about taking anyone else away from me!",
  ui_story_5080_50801102_54_dialog_content = "<color=#e8d9bb>Sinsa flies down like a cannonball, using his monstrous strength to hurl everyone to safety.</color>",
  ui_story_5080_50801102_55_dialog_content = "<color=#e8d9bb>As I watch him approach, getting closer and closer—I don't know why, but I suddenly feel at ease.</color>",
  ui_story_5080_50801102_56_dialog_content = "Grab my hand, PlayerName!",
  ui_story_5080_50801102_57_dialog_content = "Wait, Sinsa, that's molten lava below us! What are you doing!?",
  ui_story_5080_50801102_58_dialog_content = "Who cares! Just get me up there!",
  ui_story_5080_50801102_59_dialog_content = "Don't you dare think about dying on me, kid!",
  ui_story_5080_50801102_60_dialog_content = "<size=50>Sinsa!!!</size>",
  ui_story_5080_50801201_1_dialog_content = "Mission accomplished! Eagleeye's contributions were significant!",
  ui_story_5080_50801201_2_dialog_content = "Thank you for your hard work, Rachel. Illumina will remember your sacrifice.",
  ui_story_5080_50801201_3_dialog_content = "Step forward, soldier. The Grand Marshal will now personally award you the Medal of Honor!",
  ui_story_5080_50801201_4_dialog_content = "Regarding the rescue operation, we did all we could... Sorry, Rachel, this is all I have for you. Thank you for your efforts.",
  ui_story_5080_50801201_5_dialog_content = "Aghhh...!",
  ui_story_5080_50801201_6_dialog_content = "So heavy...",
  ui_story_5080_50801201_7_dialog_content = "Huh?",
  ui_story_5080_50801201_8_dialog_content = "They're right here... in my hands... so heavy...",
  ui_story_5080_50801201_9_dialog_content = "For my sake... all my teammates... all sacrificed...",
  ui_story_5080_50801201_10_dialog_content = "Someone get over here! She's about to faint!",
  ui_story_5080_50801201_11_dialog_content = "My chest hurts... I'm not injured, but the pain won't stop... Auntie...",
  ui_story_5080_50801201_12_dialog_content = "Thank you, Captain... Thank you for giving your all to complete the mission.",
  ui_story_5080_50801201_13_dialog_content = "Now, our children will no longer be remembered as \"failures.\"",
  ui_story_5080_50801201_14_dialog_content = "They can finally rest as heroes.",
  ui_story_5080_50801201_15_dialog_content = "No...",
  ui_story_5080_50801201_16_dialog_content = "I'm so sad, Auntie... I completed the mission, but... it hurts so much...",
  ui_story_5080_50801201_17_dialog_content = "Rachel, my child, don't cry... don't cry...",
  ui_story_5080_50801201_18_dialog_content = "It's all my fault. Why are the grown-ups all thanking me when it was all because of my mistake...?",
  ui_story_5080_50801201_19_dialog_content = "You salvaged their last shred of dignity.",
  ui_story_5080_50801201_20_dialog_content = "But they should've returned safely and been with their parents.",
  ui_story_5080_50801201_21_dialog_content = "Rachel, look at me. Would you really be able to bear that responsibility? Turning everyone into deserters just to get them home safe?",
  ui_story_5080_50801201_22_dialog_content = "I... I don't know... I don't know...",
  ui_story_5080_50801201_23_dialog_content = "What's going on, Rachel? This is your sixth failed mission.",
  ui_story_5080_50801201_24_dialog_content = "You've rested long enough, so why is this happening again?",
  ui_story_5080_50801201_25_dialog_content = "I'm sorry, it's all my fault. Please don't blame the others.",
  ui_story_5080_50801201_26_dialog_content = "The others have all complained about you. You can't even remember their names or faces... What happened?",
  ui_story_5080_50801201_27_dialog_content = "I... I'm sorry... I'm sorry...",
  ui_story_5080_50801201_28_dialog_content = "You should take a break from missions for now. I'll arrange some time off for you.",
  ui_story_5080_50801201_29_dialog_content = "I'm truly sorry... Commander...",
  ui_story_5080_50801201_30_dialog_content = "Gray Wing... His name was Louis. He was born in the North and always dreamed of exploring the desert.",
  ui_story_5080_50801201_31_dialog_content = "He once said he wanted to carve a flute from a branch of the white trees of Northland to give as a gift to White Goose.",
  ui_story_5080_50801201_32_dialog_content = "White Goose... Her name was Merry. She always talked about learning an instrument but never actually got around to it.",
  ui_story_5080_50801201_33_dialog_content = "She promised to play for me on my birthday, but kept putting it off, year after year.",
  ui_story_5080_50801201_34_dialog_content = "And then there's Red Kestrel and Green Owl...",
  ui_story_5080_50801201_35_dialog_content = "They've now become this necklace, hanging around my neck forever.",
  ui_story_5080_50801201_36_dialog_content = "\"Would you really be able to bear that responsibility? Turning everyone into deserters just to get them home safe?\"",
  ui_story_5080_50801201_37_dialog_content = "PlayerName!",
  ui_story_5080_50801201_38_dialog_content = "...!",
  ui_story_5080_50801201_39_dialog_content = "Vice, I'm here! Captain, Fleur, Zeta, are you all okay?",
  ui_story_5080_50801201_40_dialog_content = "I'm okay.",
  ui_story_5080_50801201_41_dialog_content = "Great, PlayerName's safe too.",
  ui_story_5080_50801201_42_dialog_content = "Looks like the volcano's mouth collapsed. Where are the others?",
  ui_story_5080_50801201_43_dialog_content = "It seems we're not on the same level... Heh, this is like a classic setup before the final boss in the Demon King's castle!",
  ui_story_5080_50801201_44_dialog_content = "The Rediesel leader... To think he actually jumped into the lava for us...",
  ui_story_5080_50801201_45_dialog_content = "Let's move down. We need to find Sinsa.",
  ui_story_5080_50801201_46_dialog_content = "It's all lava here... Our only choice is to navigate around these areas.",
  ui_story_5080_50801201_47_dialog_content = "The mission comes first. We should avoid unnecessary danger zones.",
  ui_story_5080_50801201_48_dialog_content = "Sinsa saved us... so I have to find them. Follow me, I should be able to sense them.",
  ui_story_5080_50801201_49_dialog_content = "Last Caelestite, your lines are always so cool! Stop stealing my thunder! I'm going too!",
  ui_story_5080_50801201_50_dialog_content = "Captain, I want to help with the rescue too.",
  ui_story_5080_50801201_51_dialog_content = "... Your arm's injured. Did it happen when we fell?",
  ui_story_5080_50801201_52_dialog_content = "Huh? Oh... it's bleeding.",
  ui_story_5080_50801201_53_dialog_content = "Take this and bandage yourself up. You're not fit for frontline duty anymore. Stay behind me when we go.",
  ui_story_5080_50801201_54_dialog_content = "Go?",
  ui_story_5080_50801201_55_dialog_content = "Down there. The target might be below us.",
  ui_story_5080_50801201_56_dialog_content = "Yes, ma'am!",
  ui_story_5080_50801201_57_dialog_content = "This place is crawling with Eclipsites... How can they live in an active volcano?",
  ui_story_5080_50801201_58_dialog_content = "Eclipsites are living creatures too. Surely they should avoid such dangerous areas.",
  ui_story_5080_50801201_59_dialog_content = "This is nothing like what I learned at the academy.",
  ui_story_5080_50801201_60_dialog_content = "... These Eclipsites were discovered by Illumina long ago.",
  ui_story_5080_50801201_61_dialog_content = "What? Why hadn't I heard about this?",
  ui_story_5080_50801201_62_dialog_content = "Back then, the Committee assigned my aunt's team to a mission just like ours.",
  ui_story_5080_50801201_63_dialog_content = "Her captain was the one who officially founded the Rediesel Wrench.",
  ui_story_5080_50801201_64_dialog_content = "You know, your aunt served in the Freebird Squad.",
  ui_story_5080_50801201_65_dialog_content = "Her last mission was an important one directly assigned by the Committee, but not only did she fail, her captain also defected from Illumina afterward.",
  ui_story_5080_50801201_66_dialog_content = "Many people have said that the Freebird Squad abandoned their mission without permission to save themselves. What do you think about this?",
  ui_story_5080_50801201_67_dialog_content = "I'm ashamed! Grand Marshal. I feel very... guilty about my aunt's failure.",
  ui_story_5080_50801201_68_dialog_content = "But she herself was always loyal. She was just dragged down by that captain!",
  ui_story_5080_50801201_69_dialog_content = "Please give me a chance to restore my family's honor.",
  ui_story_5080_50801201_70_dialog_content = "But if that disgrace hadn't transpired, your aunt might have died a hero.",
  ui_story_5080_50801201_71_dialog_content = "Would that have been any easier for you to accept?",
  ui_story_5080_50801201_72_dialog_content = "Um... I... I...",
  ui_story_5080_50801201_73_dialog_content = "Hahaha... I was just asking.",
  ui_story_5080_50801201_74_dialog_content = "Now, let me tell you why I called you here—I have a mission for you.",
  ui_story_5080_50801201_75_dialog_content = "Your aunt's last mission is the one I wish to assign to you.",
  ui_story_5080_50801201_76_dialog_content = "Grand Marshal?",
  ui_story_5080_50801201_77_dialog_content = "Back then, the Committee ordered the Freebird Squad to bring back that observed Eclipsite alive.",
  ui_story_5080_50801201_78_dialog_content = "They wanted a live specimen for the purpose of experimentation.",
  ui_story_5080_50801201_79_dialog_content = "I'm still skeptical of whether such research holds positive implications for Illumina, so I won't force you into anything.",
  ui_story_5080_50801201_80_dialog_content = "I...",
  ui_story_5080_50801201_81_dialog_content = "Of course, capturing that Eclipsite alive might make up for your regret over your aunt.",
  ui_story_5080_50801201_82_dialog_content = "However, Rachel, you can decide what to do for yourself.",
  ui_story_5080_50801201_83_dialog_content = "I've picked a special teammate for your mission. You've heard the name \"Vice\" before, I assume?",
  ui_story_5080_50801201_84_dialog_content = "The young captain rumored to work closely with a Caelestite? But she's been working with Caelestite for such a long time...",
  ui_story_5080_50801201_85_dialog_content = "Right. If she were to go with you, how could her partner not follow?",
  ui_story_5080_50801201_86_dialog_content = "They're incredible individuals. I'm sure you'll find some answers on this mission.",
  ui_story_5080_50801201_87_dialog_content = "This is also a request carefully issued by Hiiro. You have a fine superior, Rachel.",
  ui_story_5080_50801201_88_dialog_content = "Thank you very much, and thank you, Commander Hiiro. Thank you for still believing in me and giving me this opportunity!",
  ui_story_5080_50801201_89_dialog_content = "I'll prepare to depart right away!",
  ui_story_5080_50801201_90_dialog_content = "Wait a moment, Rachel.",
  ui_story_5080_50801201_91_dialog_content = "Rest assured, I will complete the mission!",
  ui_story_5080_50801201_92_dialog_content = "I just want to ask you one thing—",
  ui_story_5080_50801201_93_dialog_content = "Can you still find the Illumina in your heart?",
  ui_story_5080_50801201_94_dialog_content = "I... I know what you're worried about, Grand Marshal.",
  ui_story_5080_50801201_95_dialog_content = "I indeed made errors in command, errors which led to my team's downfall. And I can't seem to get along with my fellow team members in my current state...",
  ui_story_5080_50801201_96_dialog_content = "But rest assured, I won't make the same mistakes again.",
  ui_story_5080_50801201_97_dialog_content = "That's not what I meant, but never mind. Go ahead.",
  ui_story_5080_50801201_98_dialog_content = "Having them around may alter your thinking.",
  ui_story_5080_50801201_99_dialog_content = "They're legendary partners, incredible people. Their words hold great power.",
  ui_story_5080_50801201_100_dialog_content = "I'll pay more attention and continue to keep my... I won't get involved with any teammates, and I won't get anyone else in trouble...",
  ui_story_5080_50801201_101_dialog_content = "Auntie, I have good news.",
  ui_story_5080_50801201_102_dialog_content = "I have a new mission.",
  ui_story_5080_50801201_103_dialog_content = "Really? That's wonderful. But are you okay? Don't push yourself.",
  ui_story_5080_50801201_104_dialog_content = "I'm fine, Auntie. And this time, I might have a chance to investigate what happened back then.",
  ui_story_5080_50801201_105_dialog_content = "I will clear your name.",
  ui_story_5080_50801201_106_dialog_content = "Don't think like that, Rachel.",
  ui_story_5080_50801201_107_dialog_content = "I've never regretted what happened back then. I'm deeply grateful to the captain for allowing me to survive.",
  ui_story_5080_50801201_108_dialog_content = "If it weren't for her, I'd be missing out on the pleasure of your company.",
  ui_story_5080_50801201_109_dialog_content = "Why are you still defending her... She deserted Illumina.",
  ui_story_5080_50801201_110_dialog_content = "The captain is no deserter, nor is she a traitor!",
  ui_story_5080_50801201_111_dialog_content = "There must be some reason for her actions we don't know of, but I absolutely believe in her with all my heart!",
  ui_story_5080_50801201_112_dialog_content = "She turned you all into traitors and not once thought about returning in all these years! Why do you still believe in her?!",
  ui_story_5080_50801201_113_dialog_content = "She's the one who carried all of us back from that molten inferno single-handedly!",
  ui_story_5080_50801201_114_dialog_content = "She's a true hero!",
  ui_story_5080_50801201_115_dialog_content = "I just want to clear your name...",
  ui_story_5080_50801201_116_dialog_content = "Our family did nothing wrong...",
  ui_story_5080_50801201_117_dialog_content = "Where are you going, Rachel?",
  ui_story_5080_50801201_118_dialog_content = "Come back, Rachel! I forbid you from going there!",
  ui_story_5080_50801201_119_dialog_content = "Rachel...",
  ui_story_5080_50801201_120_dialog_content = "Although Freebird's mission failed, they still gathered a great deal of intelligence.",
  ui_story_5080_50801201_121_dialog_content = "The information they left behind mentioned how the Eclipsite they observed back then was a mutated species that could absorb geothermal energy to survive.",
  ui_story_5080_50801201_122_dialog_content = "And this volcano, always active but never reaching the critical point of eruption, is teeming with such Eclipsites.",
  ui_story_5080_50801201_123_dialog_content = "It's likely because these Eclipsites are absorbing the volcano's energy.",
  ui_story_5080_50801201_124_dialog_content = "The instability of the Rediesel Desert's volcano is due to unstable geothermal energy.",
  ui_story_5080_50801201_125_dialog_content = "The activity of these Eclipsites causes an imbalance in geothermal energy, yet their feeding on the volcano suppresses its eruptions.",
  ui_story_5080_50801201_126_dialog_content = "From this perspective, it is likely that those Eclipsites have been thriving underground all this time.",
  ui_story_5080_50801201_127_dialog_content = "Though only one was observed back then, they've become a whole colony now.",
  ui_story_5080_50801201_128_dialog_content = "And they've even passed down this terrifying trait genetically.",
  ui_story_5080_50801201_129_dialog_content = "Wait, does that mean we should be thankful to these creatures?",
  ui_story_5080_50801201_130_dialog_content = "It's thanks to them that the volcano hasn't erupted? Well, that's just plain annoying.",
  ui_story_5080_50801201_131_dialog_content = "But if it weren't for these Eclipsites, the geothermal energy wouldn't be so unstable, and the environment wouldn't be this harsh.",
  ui_story_5080_50801201_132_dialog_content = "We wouldn't have to deal with all those annoying earthquakes when we're driving!",
  ui_story_5080_50801201_133_dialog_content = "Even more than that—does the desolation of the desert have anything to do with these creatures?",
  ui_story_5080_50801201_134_dialog_content = "Anyway, the fact that these Eclipsites can <color=#FFB400>absorb</color> the volcano's power is already one step too far for me.",
  ui_story_5080_50801201_135_dialog_content = "If <color=#FFB400>that Eclipsite</color> from back then has managed to survive all this time, just how powerful is that thing?",
  ui_story_5080_50801201_136_dialog_content = "We can't suffer it to exist any longer...",
  ui_story_5080_50801201_137_dialog_content = "We absolutely cannot allow it to go on...",
  ui_story_5080_50801201_138_dialog_content = "So let's keep pushing forward, deeper into the volcano! Toward Sinsa!",
  ui_story_5080_50801202_1_dialog_content = "Yikes... Talk about a tight squeeze.",
  ui_story_5080_50801202_2_dialog_content = "And there's lava everywhere... Be careful!",
  ui_story_5080_50801202_3_dialog_content = "Hatchling Two, Lollipop Girl, stick to my six!",
  ui_story_5080_50801202_4_dialog_content = "Eagle Hunter One, Two, Three—open fire!",
  ui_story_5080_50801202_5_dialog_content = "Captain, don't push yourself! These Eclipsites have really tough defenses!",
  ui_story_5080_50801202_6_dialog_content = "Enough talk! Focused Strike!",
  ui_story_5080_50801202_7_dialog_content = "Never fear! My sweet bomb's gonna wrap this up pronto!",
  ui_story_5080_50801202_8_dialog_content = "Roar—!",
  ui_story_5080_50801202_9_dialog_content = "Captain!",
  ui_story_5080_50801202_10_dialog_content = "It's just a scratch—stay put.",
  ui_story_5080_50801202_11_dialog_content = "Here comes round two!",
  ui_story_5080_50801202_12_dialog_content = "Eagle Hunter One, fall back and defend!",
  ui_story_5080_50801202_13_dialog_content = "No! Too late...",
  ui_story_5080_50801202_14_dialog_content = "Hero Strike!",
  ui_story_5080_50801202_15_dialog_content = "Roar—!",
  ui_story_5080_50801202_16_dialog_content = "Zeta?!",
  ui_story_5080_50801202_17_dialog_content = "Lollipop Girl!!!",
  ui_story_5080_50801202_18_dialog_content = "Fleur, I've got it on a leash with my Force Boost! Strike now!",
  ui_story_5080_50801202_19_dialog_content = "See you in hell!",
  ui_story_5080_50801202_20_dialog_content = "Did it fall into the lava?",
  ui_story_5080_50801202_21_dialog_content = "Groooar!!!",
  ui_story_5080_50801202_22_dialog_content = "It got swallowed up by the lava... Aren't these Eclipsites supposed to be able to withstand lava?",
  ui_story_5080_50801202_23_dialog_content = "Lollipop Girl, are you okay?!",
  ui_story_5080_50801202_24_dialog_content = "Heh, how's that, Eagleshot? The Rediesel Wrench ain't half bad.",
  ui_story_5080_50801202_25_dialog_content = "Why would you do that... for me...?",
  ui_story_5080_50801202_26_dialog_content = "'Cause you're the hero's long-lost sister who went astray...",
  ui_story_5080_50801202_27_dialog_content = "Lollipop Girl? Lollipop Girl!",
  ui_story_5080_50801202_28_dialog_content = "(Damn, no med kits and Zeta's in bad shape... Wait... Huh?)",
  ui_story_5080_50801202_29_dialog_content = "Did I fail in my command again? Did I, once again, let someone else...",
  ui_story_5080_50801202_30_dialog_content = "I was supposed to be the protector...",
  ui_story_5080_50801202_31_dialog_content = "Why do I keep messing up? Am I too full of myself?",
  ui_story_5080_50801202_32_dialog_content = "Don't be too hard on yourself, Zeta's still got a fighting chance! Quick, get her on my back, we need to move.",
  ui_story_5080_50801202_33_dialog_content = "Hang in there, Zeta! I'll get you out of here, I promise!",
  ui_story_5080_50801202_34_dialog_content = "The reformed demon mechanic, it looks like my journey might be at its end. Just forget about me...",
  ui_story_5080_50801202_35_dialog_content = "Quit messing around!",
  ui_story_5080_50801202_36_dialog_content = "Snap out of it! Remember the new valve you ordered from me?",
  ui_story_5080_50801202_37_dialog_content = "Just give me a bit more time, and I'll figure out an even more advanced twin-V8 engine! Don't you want to give it a whirl?",
  ui_story_5080_50801202_38_dialog_content = "Huh?!",
  ui_story_5080_50801202_39_dialog_content = "If you hang on till we're out of here, I'll pimp your ride exclusively—no more helping for Azure! Deal?",
  ui_story_5080_50801202_40_dialog_content = "Plus, haven't you always wanted to know what's under the hood of Azure's ride? I'll find out for you!",
  ui_story_5080_50801202_41_dialog_content = "Let's go find Roy and get him to come with us... Zeta, wake up!",
  ui_story_5080_50801202_42_dialog_content = "I'm planning a prank on Azure with that guy! You just wait and see!",
  ui_story_5080_50801202_43_dialog_content = "Right, right. Lollipop Girl, I can lend a hand too. I majored in mechanical engineering at the academy!",
  ui_story_5080_50801202_44_dialog_content = "But you don't even call me by my name...",
  ui_story_5080_50801202_45_dialog_content = "I can modify your ride too. Illumina tech is top-notch, you know.",
  ui_story_5080_50801202_46_dialog_content = "Ever dreamt of driving an Illumina-style princess carriage?",
  ui_story_5080_50801202_47_dialog_content = "What?! No way! I wanna see it now! Got any blueprints?",
  ui_story_5080_50801202_48_dialog_content = "Zeta? You... you're okay?",
  ui_story_5080_50801202_49_dialog_content = "Uh... Heh, looks like the Sweet Hunter on my back took the hit for me... I guess I am the chosen heroine after all.",
  ui_story_5080_50801202_50_dialog_content = "Lady Zeta's back in action!",
  ui_story_5080_50801202_51_dialog_content = "You...",
  ui_story_5080_50801202_52_dialog_content = "This is the tale of the Wild Child, Warrior Zeta! She won't go down without a fight... Erm...",
  ui_story_5080_50801202_53_dialog_content = "I wasn't trying to fool you guys, I just wanted Fleur to carry me for a while.",
  ui_story_5080_50801202_54_dialog_content = "You scared me there... Why are you clowning around at a time like this... Seriously... I'm glad you're okay, though.",
  ui_story_5080_50801202_55_dialog_content = "(When I first noticed, I didn't know how to break it to them... I'm glad that joke didn't last long.)",
  ui_story_5080_50801202_56_dialog_content = "My back's killing me!",
  ui_story_5080_50801202_57_dialog_content = "Eagleshot, you look bummed. You're not angry with me, are you...?",
  ui_story_5080_50801202_58_dialog_content = "Huh? Your face is so mean right now... You look like you're about to turn into a villain on us! Are you planning on making this a horror story?!",
  ui_story_5080_50801202_59_dialog_content = "Don't—",
  ui_story_5080_50801202_60_dialog_content = "Huh?!",
  ui_story_5080_50801202_61_dialog_content = "Zeta... I'm so pleased you're okay.",
  ui_story_5080_50801202_62_dialog_content = "You can't just pat a hero's head all willy-nilly like! But since you're acting all cute, I can't really turn you down... Huh?",
  ui_story_5080_50801202_63_dialog_content = "Y-You said my name!",
  ui_story_5080_50801202_64_dialog_content = "You shouldn't scare people with jokes like that...",
  ui_story_5080_50801202_65_dialog_content = "Captain...",
  ui_story_5080_50801202_66_dialog_content = "Don't worry, a hero never plays the same trick twice, hehe.",
  ui_story_5080_50801202_67_dialog_content = "Well, since everything's fine, after all that... let's get out of this lava trap! Keep moving!",
  ui_story_5080_50801202_68_dialog_content = "Caelestite One, Hatchling Two—don't fall behind!",
  ui_story_5080_50801202_69_dialog_content = "What's with her still calling me by my code name...",
  ui_story_5080_50801202_70_dialog_content = "Let's not sweat the small stuff for now. Time to roll out.",
  ui_story_5080_50801202_71_dialog_content = "The mission must continue. Hurry up!",
  ui_story_5080_50801202_72_dialog_content = "(She slips on that cold mask of indifference so quickly, but it just looks so out of place now, Rachel...)",
  ui_story_5080_50801202_73_dialog_content = "Let's go, Vice. I have a feeling this is almost over.",
  ui_story_5080_50801202_74_dialog_content = "Move quickly! Stay away from the danger zones. Uh...",
  ui_story_5080_50801202_75_dialog_content = "What's wrong?",
  ui_story_5080_50801202_76_dialog_content = "Nothing, let's go!",
  ui_story_5080_50801202_77_dialog_content = "Eagle Hunter One, scout ahead. Everyone else, follow Eagle Hunter One!",
  ui_story_5080_50801202_78_dialog_content = "Their lives are still in my hands... I can't... fall now...",
  ui_story_5080_50801301_1_dialog_content = "Graaaaah—!",
  ui_story_5080_50801301_2_dialog_content = "They're swarming.",
  ui_story_5080_50801301_3_dialog_content = "Filled with malice, brimming with hatred.",
  ui_story_5080_50801301_4_dialog_content = "Jeriah, get moving, I can handle this.",
  ui_story_5080_50801301_5_dialog_content = "What are you talking about? Your eyesight is impaired. I can't leave you behind.",
  ui_story_5080_50801301_6_dialog_content = "Your abilities... aren't suited for this battle.",
  ui_story_5080_50801301_7_dialog_content = "After all, I'm still a senior member.",
  ui_story_5080_50801301_8_dialog_content = "The ground... it's sinking... I'm gonna fall into the lava!",
  ui_story_5080_50801301_9_dialog_content = "Dawn! A little to the left—grab my hand!",
  ui_story_5080_50801301_10_dialog_content = "You go ahead, Jeriah.",
  ui_story_5080_50801301_11_dialog_content = "I've got your hand. Don't let go, Dawn.",
  ui_story_5080_50801301_12_dialog_content = "The Eclipsites, they're coming.",
  ui_story_5080_50801301_13_dialog_content = "I don't have time to think about that right now.",
  ui_story_5080_50801301_14_dialog_content = "Why? Jeriah, you need to live!",
  ui_story_5080_50801301_15_dialog_content = "If you die, everyone will be so sad.",
  ui_story_5080_50801301_16_dialog_content = "Can you imagine Eve's face soaked in tears?",
  ui_story_5080_50801301_17_dialog_content = "She'd be hugging you and crying!",
  ui_story_5080_50801301_18_dialog_content = "...",
  ui_story_5080_50801301_19_dialog_content = "That kite string really has a strong hold on you.",
  ui_story_5080_50801301_20_dialog_content = "Now that this connection between us has been made, I won't let it be easily severed!",
  ui_story_5080_50801301_21_dialog_content = "Jeriah... Watch out!",
  ui_story_5080_50801301_22_dialog_content = "Attar, I tried my best...",
  ui_story_5080_50801301_23_dialog_content = "<color=#FFB400>Rapid Torrent!</color>",
  ui_story_5080_50801301_24_dialog_content = "Just in time! Zeta, block them with your bombs!",
  ui_story_5080_50801301_25_dialog_content = "Hey-hey, the ultimate sugar bomb is coming your way!",
  ui_story_5080_50801301_26_dialog_content = "Jeriah, I'm here to help! Fleur, please help pull up Dawn...",
  ui_story_5080_50801301_27_dialog_content = "<color=#FFB400>Ice Blossom!</color>",
  ui_story_5080_50801301_28_dialog_content = "The bridge is ready, come on up!",
  ui_story_5080_50801301_29_dialog_content = "Carleen? And Eve?",
  ui_story_5080_50801301_30_dialog_content = "Dawn, I'm here to help you!",
  ui_story_5080_50801301_31_dialog_content = "You've been a great help, Little Princess of Lumopolis.",
  ui_story_5080_50801301_32_dialog_content = "There's no need to thank me. You're also fighting hard to protect those you care about, aren't you?",
  ui_story_5080_50801301_33_dialog_content = "Come with me, Dawn. Don't let go of my hand!",
  ui_story_5080_50801301_34_dialog_content = "Jeriah... my hand...",
  ui_story_5080_50801301_35_dialog_content = "We've finally regrouped. Carleen, are you all okay?",
  ui_story_5080_50801301_36_dialog_content = "We're fine, but the lava here is too dangerous. We won't be able to fight here for long.",
  ui_story_5080_50801301_37_dialog_content = "Little bird of prey, Princess, hurry and take Zeta away from here.",
  ui_story_5080_50801301_38_dialog_content = "Caelestite, I'm afraid I must trouble you to use your psychic abilities to lead us to Sinsa.",
  ui_story_5080_50801301_39_dialog_content = "You're not leaving?",
  ui_story_5080_50801301_40_dialog_content = "Hah... How could I possibly abandon him at a time like this?",
  ui_story_5080_50801301_41_dialog_content = "I'm not leaving! I want to save the Berserker too!",
  ui_story_5080_50801301_42_dialog_content = "I can't just walk away either.",
  ui_story_5080_50801301_43_dialog_content = "Why have you all chosen a time like this to become so stubborn?",
  ui_story_5080_50801301_44_dialog_content = "Let's go deeper in, then.",
  ui_story_5080_50801301_45_dialog_content = "Captain?",
  ui_story_5080_50801301_46_dialog_content = "The mission must continue. We need to gather more information... and saving that Rediesel leader is also an option.",
  ui_story_5080_50801301_47_dialog_content = "Rediesel Technician, lend me your tools. Hatchling Two, give me your weapon.",
  ui_story_5080_50801301_48_dialog_content = "Huh? Me?",
  ui_story_5080_50801301_49_dialog_content = "Alright, I've improved your weapon. It might take some getting used to, but it should be easier to use now that you're injured.",
  ui_story_5080_50801301_50_dialog_content = "Eagle Hunter One, Two, Three—return!",
  ui_story_5080_50801301_51_dialog_content = "Eagle Hunter One and Three, it's Eagle Hunter Two's turn to lead.",
  ui_story_5080_50801301_52_dialog_content = "Get ready—continue the mission.",
  ui_story_5080_50801301_53_dialog_content = "My bow feels lighter. The bowstring feels more responsive...",
  ui_story_5080_50801301_54_dialog_content = "The captain remembered exactly what I like. She's so thoughtful, so why does she always keep her distance from us?",
  ui_story_5080_50801301_55_dialog_content = "As a captain, she has to complete the mission and keep her teammates alive.",
  ui_story_5080_50801301_56_dialog_content = "Minimizing her team's affection for her might be her last resort to prevent anyone else from getting hurt because of her.",
  ui_story_5080_50801301_57_dialog_content = "I understand the weight she's carrying.",
  ui_story_5080_50801301_58_dialog_content = "Sinsa!",
  ui_story_5080_50801301_59_dialog_content = "You idiot... Can you hear me?",
  ui_story_5080_50801301_60_dialog_content = "Sinsa?! Answer us!",
  ui_story_5080_50801301_61_dialog_content = "Roy, look down there! That spot next to the lava—is that Sinsa's red hair?",
  ui_story_5080_50801301_62_dialog_content = "Whether it is or not, I'm going down to check!",
  ui_story_5080_50801301_63_dialog_content = "Hey! That's lava! How can you just jump down there like that?! Hey!",
  ui_story_5080_50801301_64_dialog_content = "Forget it, I'm the one who's gonna surpass Sinsa someday, so how could I back down at a time like this?",
  ui_story_5080_50801301_65_dialog_content = "I'm jumping!",
  ui_story_5080_50801301_66_dialog_content = "Waaaahhhh—!",
  ui_story_5080_50801301_67_dialog_content = "There's lava everywhere!",
  ui_story_5080_50801301_68_dialog_content = "Get out of the way!",
  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5080_50801301_70_dialog_content = "You're crushing me, old man...",
  ui_story_5080_50801301_71_dialog_content = "Look, it's Sinsa! It's really Sinsa! He's alive!",
  ui_story_5080_50801301_72_dialog_content = "Sinsa, you—",
  ui_story_5080_50801301_73_dialog_content = "Wow... Look at all these dead Eclipsites... Did he kill them all by himself?",
  ui_story_5080_50801301_74_dialog_content = "Even with such major injuries after falling all the way down here, he still managed to kill so many of them.",
  ui_story_5080_50801301_75_dialog_content = "Yo, you guys came... I just strangled this big guy over here...",
  ui_story_5080_50801301_76_dialog_content = "Sinsa?!",
  ui_story_5080_50801301_77_dialog_content = "Sinsa, snap out of it. It's dead already, let go and come with us!",
  ui_story_5080_50801301_78_dialog_content = "Huh? Sinsa?!",
  ui_story_5080_50801301_79_dialog_content = "I didn't really eat well earlier... I'm hungry again...",
  ui_story_5080_50801301_80_dialog_content = "I really wanna go back and eat with everyone. Food always tastes better that way...",
  ui_story_5080_50801301_81_dialog_content = "Roy, I'm so sleepy. I must've been worrying too much these past few days.",
  ui_story_5080_50801301_82_dialog_content = "Let's head back for our victory feast. We shouldn't keep the others waiting too long...",
  ui_story_5080_50801301_83_dialog_content = "What's wrong with him? Check to see if he's okay—don't let him just pass out like this!",
  ui_story_5080_50801301_84_dialog_content = "... He's fine. He just tuckered himself out and fell asleep.",
  ui_story_5080_50801301_85_dialog_content = "He was out looking for people last night and didn't eat much when he came back, poor guy.",
  ui_story_5080_50801301_86_dialog_content = "Hmph, I knew this guy wasn't that fragile.",
  ui_story_5080_50801301_87_dialog_content = "Besides, I'm the only one who's allowed to beat him!",
  ui_story_5080_50801301_88_dialog_content = "Come on, put him on my back.",
  ui_story_5080_50801301_89_dialog_content = "When he wakes up and finds out he had to rely on me, he'll be so embarrassed!",
  ui_story_5080_50801301_90_dialog_content = "I'll leave him to you then, and I'll lead the way. Let's hurry back up—",
  ui_story_5080_50801301_91_dialog_content = "Where's his wrench?",
  ui_story_5080_50801301_92_dialog_content = "Maybe he lost it when he fell... I need to look for it...",
  ui_story_5080_50801301_93_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5080_50801301_94_dialog_content = "Did you hear that?",
  ui_story_5080_50801301_95_dialog_content = "Is that the sound of lava?",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>Thud, thud!</color>",
  ui_story_5080_50801301_97_dialog_content = "There it is again!",
  ui_story_5080_50801301_98_dialog_content = "... Footsteps! Brock, run!",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>Thud, thud, thud!</color>",
  ui_story_5080_50801301_100_dialog_content = "Run!!!",
  ui_story_5080_50801302_1_dialog_content = "Heeeeelp!!!",
  ui_story_5080_50801302_2_dialog_content = "Who's there?",
  ui_story_5080_50801302_3_dialog_content = "Who is that?",
  ui_story_5080_50801302_4_dialog_content = "Wow! It's that Illumina captain! Roy, get over here!",
  ui_story_5080_50801302_5_dialog_content = "What happened?",
  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>Thud, thud, thud, thud, thud, thud, thud, thud, thud, thud!</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>Roar—!</color>",
  ui_story_5080_50801302_8_dialog_content = "An Eclipsite?! No... it's the <color=#FFB400>target</color>!",
  ui_story_5080_50801302_9_dialog_content = "Thanks for the help, little Illumina lady.",
  ui_story_5080_50801302_10_dialog_content = "I'll lay down some suppressive fire. You guys scram, the rest are right behind!",
  ui_story_5080_50801302_11_dialog_content = "Hurry, Roy, we—",
  ui_story_5080_50801302_12_dialog_content = "Look out!",
  ui_story_5080_50801302_13_dialog_content = "Roar—!",
  ui_story_5080_50801302_14_dialog_content = "Sneaky sucker... It'd rather take a beating than let us through.",
  ui_story_5080_50801302_15_dialog_content = "What's that? That Eclipsite blocked the path?",
  ui_story_5080_50801302_16_dialog_content = "That thing... Is it the one that killed Attar...?",
  ui_story_5080_50801302_17_dialog_content = "Let me take care of this!",
  ui_story_5080_50801302_18_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>The ceiling is blown open by lightning, knocking the Eclipsite down, but this violent blast of power also causes the volcano to roar, and the earth begins to shake yet again.</color>",
  ui_story_5080_50801302_20_dialog_content = "This power... Bad news, people—the volcano's about to blow its top!",
  ui_story_5080_50801302_21_dialog_content = "Rediesel Girl, keep attacking!",
  ui_story_5080_50801302_22_dialog_content = "But that could trigger an eruption.",
  ui_story_5080_50801302_23_dialog_content = "It's already been awakened. If it gets out of here, the others will be in danger!",
  ui_story_5080_50801302_24_dialog_content = "I hit it dead on, but I don't feel like I did any damage... Where's its weak point?",
  ui_story_5080_50801302_25_dialog_content = "The Eagle Hunters have already scouted it. Its shell hasn't reached the true temperature of lava.",
  ui_story_5080_50801302_26_dialog_content = "And, any life form is most vulnerable when feeding.",
  ui_story_5080_50801302_27_dialog_content = "If we can extinguish its shell, it might attempt to absorb power. Then, it will expose its weak point!",
  ui_story_5080_50801302_28_dialog_content = "It was clearly bigger back then... How did it shrink hiding here all cozy for more than a decade...?",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>Death Recon!</color>",
  ui_story_5080_50801302_30_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>Rapid Torrent!</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>Ice Blossom!</color>",
  ui_story_5080_50801302_33_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_34_dialog_content = "It's injured! Our attacks are working!",
  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5080_50801302_36_dialog_content = "Crap, the wall's busted! Lava's pouring in!",
  ui_story_5080_50801302_37_dialog_content = "Be careful, it might absorb the lava's energy!",
  ui_story_5080_50801302_38_dialog_content = "Brock, haul Sinsa up top. Eve, watch yourself!",
  ui_story_5080_50801302_39_dialog_content = "Wahhhhhh!!! My bot's on fire!",
  ui_story_5080_50801302_40_dialog_content = "Zeta, we'll just slow them down. Come retreat with me for now!",
  ui_story_5080_50801302_41_dialog_content = "But, the heroine can't just exit the stage at a time like this!",
  ui_story_5080_50801302_42_dialog_content = "Listen, Zeta, you don't want me to worry, do you?",
  ui_story_5080_50801302_43_dialog_content = "Graaaaah—!",
  ui_story_5080_50801302_44_dialog_content = "The Eclipsites are bailing from their nest!",
  ui_story_5080_50801302_45_dialog_content = "Since the old guy said so... Dawn, I'll cover you—let's rally up some new pals!",
  ui_story_5080_50801302_46_dialog_content = "Don't even think about hurting my brother!",
  ui_story_5080_50801302_47_dialog_content = "Eve, fall back—Jeriah, you too...",
  ui_story_5080_50801302_48_dialog_content = "I'll keep it busy. You guys get Sinsa out of here!",
  ui_story_5080_50801302_49_dialog_content = "Jeriah?",
  ui_story_5080_50801302_50_dialog_content = "If it really is the same one that killed Attar... how could I possibly let it go?!",
  ui_story_5080_50801302_51_dialog_content = "Even though lava's flowing in, it's not absorbing it... Why?",
  ui_story_5080_50801302_52_dialog_content = "It looks like it's... even avoiding the lava?",
  ui_story_5080_50801302_53_dialog_content = "Wait, Vice, you're in a dangerous spot—get close to me!",
  ui_story_5080_50801302_54_dialog_content = "Carleen, use your power to create a foothold on its head!",
  ui_story_5080_50801302_55_dialog_content = "I'll cover you! Go for it!",
  ui_story_5080_50801302_56_dialog_content = "<color=#FFB400>Speakers!</color>",
  ui_story_5080_50801302_57_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_58_dialog_content = "Is it slowing down? Let me help too!",
  ui_story_5080_50801302_59_option_content = "Force Boost!",
  ui_story_5080_50801302_60_dialog_content = "Those depraved enough to break the wings of a bird shall pay the price!",
  ui_story_5080_50801302_61_dialog_content = "Now's the time! Are you ready, Little Princess?!",
  ui_story_5080_50801302_62_dialog_content = "<color=#FFB400>Ice Blossom!</color>",
  ui_story_5080_50801302_63_dialog_content = "Its magma shell is too hot, and we're not inflicting enough damage.",
  ui_story_5080_50801302_64_dialog_content = "It's working, we need to continue attacking...",
  ui_story_5080_50801302_65_dialog_content = "Eagle Hunter One, Eagle Hunter Two—forgive me.",
  ui_story_5080_50801302_66_dialog_content = "<color=#FFB400>Self-Destruct Attack!</color>",
  ui_story_5080_50801302_67_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_68_dialog_content = "(Oh no, its magma energy is too strong now. No matter what attack we use, it'll just bounce off.)",
  ui_story_5080_50801302_69_dialog_content = "It's broken free from my control... watch out, everyone!",
  ui_story_5080_50801302_70_dialog_content = "(My head... it hurts so much...)",
  ui_story_5080_50801302_71_dialog_content = "Hey, the cave's collapsing! You guys need to hurry up and get up here!",
  ui_story_5080_50801302_72_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5080_50801302_73_dialog_content = "It's getting hotter and hotter. At this rate...",
  ui_story_5080_50801302_74_dialog_content = "I've got the little princess. Take her and run!",
  ui_story_5080_50801302_75_dialog_content = "Oh no, Carleen and Jeriah are trapped!",
  ui_story_5080_50801302_76_dialog_content = "It might be a bit slow, but I'll make a path. You guys be careful!",
  ui_story_5080_50801302_77_dialog_content = "Why is this happening? We've already scanned it... Why is its energy still so overwhelming?",
  ui_story_5080_50801302_78_dialog_content = "Did I miscalculate?",
  ui_story_5080_50801302_79_dialog_content = "Can it continue to replenish its strength in the midst of battle?",
  ui_story_5080_50801302_80_dialog_content = "The lava's coming, Captain! Run!",
  ui_story_5080_50801302_81_dialog_content = "Go on without me! I must bear this responsibility... I'll cover your retreat!",
  ui_story_5080_50801302_82_dialog_content = "Bring it!",
  ui_story_5080_50801302_83_dialog_content = "<color=#FFB400>Rapid Torrent!</color>",
  ui_story_5080_50801302_84_dialog_content = "This way, that's right!",
  ui_story_5080_50801302_85_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_86_dialog_content = "Hatchling Two!",
  ui_story_5080_50801302_87_dialog_content = "Don't you dare touch Vice again!!!",
  ui_story_5080_50801302_88_option_content = "Force Boost!",
  ui_story_5080_50801302_89_dialog_content = "Hatchling Two, are you okay? Wake up!",
  ui_story_5080_50801302_90_dialog_content = "(The efficiency fanatic gave up a chance to attack for Vice...)",
  ui_story_5080_50801302_91_dialog_content = "Why do I feel so happy right now... even though my head hurts so much...?",
  ui_story_5080_50801302_92_dialog_content = "No time to worry about that now! Eve, you guys go!",
  ui_story_5080_50801302_93_dialog_content = "I'm coming!",
  ui_story_5080_50801302_94_dialog_content = "<color=#FFB400>Iron Fist!</color>",
  ui_story_5080_50801302_95_dialog_content = "Little Princess, I'll leave you to stabilize the bridge!",
  ui_story_5080_50801302_96_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_97_dialog_content = "It worked! I hit it from so far away!",
  ui_story_5080_50801302_98_dialog_content = "It's too hot—I can't see squat from up here.",
  ui_story_5080_50801302_99_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801302_100_dialog_content = "It's trying to escape.",
  ui_story_5080_50801302_101_dialog_content = "Don't even think about escaping!",
  ui_story_5080_50801302_102_dialog_content = "Don't chase it, Jeriah! The ground beneath us is about to be swallowed up by lava!",
  ui_story_5080_50801302_103_dialog_content = "... Don't be afraid, everyone... I'm here.",
  ui_story_5080_50801302_104_dialog_content = "The Speakers have found a weak spot in the wall. This way.",
  ui_story_5080_50801302_105_dialog_content = "Huff... huff... Ice Bridge, deploy...",
  ui_story_5080_50801302_106_dialog_content = "This is all the strength I've got left.",
  ui_story_5080_50801302_107_dialog_content = "I've got Hatchling Two on my back... Everyone, get out of here.",
  ui_story_5080_50801401_1_dialog_content = "<color=#FFB400>Ice Blossom!</color>",
  ui_story_5080_50801401_2_dialog_content = "It didn't break?",
  ui_story_5080_50801401_3_dialog_content = "The temperature of this wall is too high. It's hard to break through by force.",
  ui_story_5080_50801401_4_dialog_content = "It's all my fault... Eagle Hunter One and Three were lost in vain.",
  ui_story_5080_50801401_5_dialog_content = "It's too hot here—too hot to use explosives without careful calculation...",
  ui_story_5080_50801401_6_dialog_content = "Just give me a sec, and I'll work out a precise blast.",
  ui_story_5080_50801401_7_dialog_content = "Hey, Roy, you see that? They're stuck in that passage.",
  ui_story_5080_50801401_8_dialog_content = "I can't get a good shot in from here...",
  ui_story_5080_50801401_9_dialog_content = "Hold up, Eve, your power's too volatile for something like this!",
  ui_story_5080_50801401_10_dialog_content = "Only Sinsa can pull this off—I've gotta wake him up!",
  ui_story_5080_50801401_11_dialog_content = "Roy, bring out all the rations!",
  ui_story_5080_50801401_12_dialog_content = "Huh? What are you planning on doing to the guy...?",
  ui_story_5080_50801401_13_dialog_content = "Hohoho! Isn't it obvious? I'm gonna stuff him full of food!",
  ui_story_5080_50801401_14_dialog_content = "Munch, munch, munch, munch, munch, munch...",
  ui_story_5080_50801401_15_dialog_content = "Stop! Are you trying to choke him?!",
  ui_story_5080_50801401_16_dialog_content = "<size=45>Stop it already!</size>",
  ui_story_5080_50801401_17_dialog_content = "Vice... Vice... Don't scare me like that...",
  ui_story_5080_50801401_18_dialog_content = "Hatchling Two, Hatchling Two—wake up.",
  ui_story_5080_50801401_19_dialog_content = "Eagle Hunter Two, activate emergency mode immediately! Set the defibrillator to level two! Charging!",
  ui_story_5080_50801401_20_dialog_content = "<color=#FFB400>Zap!</color>",
  ui_story_5080_50801401_21_dialog_content = "Ugh...",
  ui_story_5080_50801401_22_dialog_content = "Thank goodness you're okay...",
  ui_story_5080_50801401_23_dialog_content = "Hatchling Two! Can you hear my voice? Don't worry, I'll get you out of here...",
  ui_story_5080_50801401_24_dialog_content = "Captain...",
  ui_story_5080_50801401_25_dialog_content = "Hatchling Two? Hatchling Two?",
  ui_story_5080_50801401_26_dialog_content = "...Enough, Rachel!",
  ui_story_5080_50801401_27_dialog_content = "If you want to awaken her heart, at least call her by her name!",
  ui_story_5080_50801401_28_dialog_content = "Say her name! She's not \"Hatchling Two,\" she's got a name–Vice!",
  ui_story_5080_50801401_29_dialog_content = "Caelestite One...",
  ui_story_5080_50801401_30_dialog_content = "It doesn't matter what happens to me, but Vice...",
  ui_story_5080_50801401_31_dialog_content = "She idolizes you and respects you. She was over the moon just getting to team up with you.",
  ui_story_5080_50801401_32_dialog_content = "And yet, you've never once called her by her name!",
  ui_story_5080_50801401_33_dialog_content = "...",
  ui_story_5080_50801401_34_dialog_content = "Her name is Vice! She'd stay up all night working on mission reports for you, exhausted but always so excited...",
  ui_story_5080_50801401_35_dialog_content = "Even though you never called her by name, just talking to her senior officer made her day!",
  ui_story_5080_50801401_36_dialog_content = "Vice adores her superiors—she lives for their praise. She's done nothing wrong... It's just a name! What are you so afraid of...?",
  ui_story_5080_50801401_37_dialog_content = "Please, at least... at least now, call her by her name...",
  ui_story_5080_50801401_38_dialog_content = "I... can't afford to form any more unnecessary attachments...",
  ui_story_5080_50801401_39_dialog_content = "Little bird of prey...",
  ui_story_5080_50801401_40_dialog_content = "We've already deviated from the mission... I can't... can't drag anyone else down anymore...",
  ui_story_5080_50801401_41_dialog_content = "... I'm sorry, she did so well... It's all my fault...",
  ui_story_5080_50801401_42_dialog_content = "I'm scared of becoming a burden again... I don't want anyone else to die because of me...",
  ui_story_5080_50801401_43_dialog_content = "If I form new bonds... if more of my people die because of my orders... I... can't accept that...",
  ui_story_5080_50801401_44_dialog_content = "No! I'm not trying to blame anyone!",
  ui_story_5080_50801401_45_dialog_content = "You've always hidden your kindness while genuinely caring for everyone all along. Why keep it concealed?",
  ui_story_5080_50801401_46_dialog_content = "It's because when you sincerely care for others, they're willing to risk their lives to protect you.",
  ui_story_5080_50801401_47_dialog_content = "How can you call that an unnecessary attachment...?",
  ui_story_5080_50801401_48_dialog_content = "Caelestite One, you wouldn't understand...",
  ui_story_5080_50801401_49_dialog_content = "How could I not understand?! I've watched helplessly as others sacrificed themselves for me! How could I not understand?!",
  ui_story_5080_50801401_50_dialog_content = "I lost my entire race, and the friends I finally found... all because of me...",
  ui_story_5080_50801401_51_dialog_content = "I understand the pain of losing people, the loneliness, and guilt...",
  ui_story_5080_50801401_52_dialog_content = "I genuinely appreciate everyone who's helped me. Their support allows Vice, me, and all our friends to keep going.",
  ui_story_5080_50801401_53_dialog_content = "I don't think these attachments are unnecessary at all.",
  ui_story_5080_50801401_54_dialog_content = "Just being able to meet everyone was a truly wonderful experience... I'd want to call out their names and talk to them again if I could.",
  ui_story_5080_50801401_55_dialog_content = "PlayerName...",
  ui_story_5080_50801401_56_dialog_content = "Enough... Caelestite One...",
  ui_story_5080_50801401_57_dialog_content = "People sacrifice themselves for others because they hold a deep love in their hearts.",
  ui_story_5080_50801401_58_dialog_content = "The ones who covered you, and Vice, they weren't doing it for the mission!",
  ui_story_5080_50801401_59_dialog_content = "They just wanted to protect you... and the fact that you survived is more than enough to make them happy.",
  ui_story_5080_50801401_60_dialog_content = "Just like the captain of the Freebird Squad... she must've held so much love for her team, she was willing to tarnish her reputation just to bring them back.",
  ui_story_5080_50801401_61_dialog_content = "Sacrifice is about protecting the people behind you...",
  ui_story_5080_50801401_62_dialog_content = "For those who finally understand each other, isn't that reason enough...?",
  ui_story_5080_50801401_63_dialog_content = "Don't say any more... I...",
  ui_story_5080_50801401_64_dialog_content = "Rachel, you know it in your heart... You've often risked your life for us…",
  ui_story_5080_50801401_65_dialog_content = "Was it really all about efficiency?",
  ui_story_5080_50801401_66_dialog_content = "You're just afraid of someone getting hurt... that's why you try so hard to protect everyone...",
  ui_story_5080_50801401_67_dialog_content = "If that's the case... why resist forming connections...?",
  ui_story_5080_50801401_68_dialog_content = "PlayerName... don't cry... you've already overexerted yourself...",
  ui_story_5080_50801401_69_dialog_content = "... We need to prepare for the explosion, just wait a little longer.",
  ui_story_5080_50801401_70_dialog_content = "Little bird of prey... no, Rachel.",
  ui_story_5080_50801401_71_dialog_content = "Desert skies often see migratory birds... even when they stray off alone, they eventually return to the flock.",
  ui_story_5080_50801401_72_dialog_content = "I... didn't understand that before. But now, I realize that choosing to be a bird of prey still means I can have friends.",
  ui_story_5080_50801401_73_dialog_content = "I... I... I don't need friends...",
  ui_story_5080_50801401_74_dialog_content = "You're so... stubborn...",
  ui_story_5080_50801401_75_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5080_50801401_76_dialog_content = "What happened? Was that an explosion?",
  ui_story_5080_50801401_77_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801401_78_dialog_content = "Look out!",
  ui_story_5080_50801401_79_dialog_content = "Rachel! I'm coming!",
  ui_story_5080_50801401_80_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801401_81_dialog_content = "Damn, it's attacking the floor.",
  ui_story_5080_50801401_82_dialog_content = "Speakers, take the little princess up!",
  ui_story_5080_50801401_83_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5080_50801401_84_dialog_content = "The wall's blown open! Come with me!",
  ui_story_5080_50801401_85_dialog_content = "PlayerName and the others are still down there!",
  ui_story_5080_50801401_86_dialog_content = "Rooooaaaar!",
  ui_story_5080_50801401_87_dialog_content = "You won't... hurt my friends again!",
  ui_story_5080_50801401_88_dialog_content = "PlayerName! Get out of here with Carleen and the others!",
  ui_story_5080_50801401_89_dialog_content = "Rachel... you... finally opened up…",
  ui_story_5080_50801401_90_dialog_content = "Perhaps the body is more honest than the mind... PlayerName, in the moment I shielded you from that attack...",
  ui_story_5080_50801401_91_dialog_content = "Those stubborn words escaped me.",
  ui_story_5080_50801401_92_dialog_content = "So... let's go.",
  ui_story_5080_50801401_93_dialog_content = "The lava's coming! Caelestite, take my hand!",
  ui_story_5080_50801401_94_dialog_content = "Merry, Louis, Louis, Tarsi... My companions, please lend me your strength.",
  ui_story_5080_50801401_95_dialog_content = "Let my friends go!",
  ui_story_5080_50801401_96_dialog_content = "No... I won't run away...",
  ui_story_5080_50801401_97_dialog_content = "PlayerName?!",
  ui_story_5080_50801401_98_dialog_content = "I said I appreciate everyone who's helped me... I cherish these connections above all else...",
  ui_story_5080_50801401_99_dialog_content = "So I won't give up on any of my friends, Rachel.",
  ui_story_5080_50801401_100_dialog_content = "...You truly are an insubordinate soldier.",
  ui_story_5080_50801401_101_dialog_content = "But, PlayerName, I'm glad...",
  ui_story_5080_50801401_102_dialog_content = "I'm honored to be part of the same team as all of you.",
  ui_story_5080_50801401_103_dialog_content = "Let's go up together.",
  ui_story_5080_50801401_104_dialog_content = "Carleen, use your last bit of strength to reinforce our footing!",
  ui_story_5080_50801401_105_dialog_content = "Jeriah, the Speakers should be able to support the collapsing wall, right?",
  ui_story_5080_50801401_106_dialog_content = "Fleur, you're in charge of attacking it head-on.",
  ui_story_5080_50801401_107_dialog_content = "Let's fight side by side.",
  ui_story_5080_50801402_1_dialog_content = "The lava's getting more turbulent, my <color=#FFB400>Ice Path</color> is... about to break!",
  ui_story_5080_50801402_2_dialog_content = "Just a little more, its armor is almost out of energy!",
  ui_story_5080_50801402_3_dialog_content = "No! PlayerName, Rachel!",
  ui_story_5080_50801402_4_dialog_content = "(Oh no... the lava's cut off the path. We're all split up...)",
  ui_story_5080_50801402_5_dialog_content = "Forget about us... I'm spent... you guys get out through the hole Fleur blasted...",
  ui_story_5080_50801402_6_dialog_content = "What kind of nonsense is that? Hang in there. We will make it.",
  ui_story_5080_50801402_7_dialog_content = "Of all places... Trying to create another ice bridge here... it'll be nigh impossible.",
  ui_story_5080_50801402_8_dialog_content = "<size=40>Grah!!!</size>",
  ui_story_5080_50801402_9_dialog_content = "I won't back down, monster... even if all I have left is this pistol...",
  ui_story_5080_50801402_10_dialog_content = "<color=#e8d9bb>Bang, bang, bang!</color>",
  ui_story_5080_50801402_11_dialog_content = "<color=#e8d9bb>Rachel's bullets hit the Eclipsite one by one, but they're blocked by its last bit of heat.</color>",
  ui_story_5080_50801402_12_dialog_content = "<color=#e8d9bb>Click—</color>",
  ui_story_5080_50801402_13_dialog_content = "Out of ammo...",
  ui_story_5080_50801402_14_dialog_content = "I'm out of weapons, but I still have my fists.",
  ui_story_5080_50801402_15_dialog_content = "PlayerName, hide behind me and don't move an inch!",
  ui_story_5080_50801402_16_dialog_content = "Rachel... get going... I can't move anymore...",
  ui_story_5080_50801402_17_dialog_content = "I... will never abandon you!",
  ui_story_5080_50801402_18_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5080_50801402_19_dialog_content = "Another lava eruption, this volcano looks like it's about to... wait, what's that?!",
  ui_story_5080_50801402_20_dialog_content = "A wrench... Sinsa's wrench?! How did it get here?",
  ui_story_5080_50801402_21_dialog_content = "Perfect timing.",
  ui_story_5080_50801402_22_dialog_content = "Stop, Rachel, that wrench is too heavy for you! Don't hurt yourself!",
  ui_story_5080_50801402_23_dialog_content = "Huff... Huff... We're back... Ah!",
  ui_story_5080_50801402_24_dialog_content = "Wait, she's actually lifting Sinsa's wrench! Now that's just showing off!",
  ui_story_5080_50801402_25_dialog_content = "I... ha... hate it when team members show off...",
  ui_story_5080_50801402_26_dialog_content = "But I do love showing off myself.",
  ui_story_5080_50801402_27_dialog_content = "Grah!!!",
  ui_story_5080_50801402_28_dialog_content = "Don't you dare hurt my teammates!",
  ui_story_5080_50801402_29_dialog_content = "Grooo—!!!",
  ui_story_5080_50801402_30_dialog_content = "How's that even possible? I never thought I'd see someone other than Sinsa swinging that wrench...",
  ui_story_5080_50801402_31_dialog_content = "Awoo... Awoo... Awoo...!!!",
  ui_story_5080_50801402_32_dialog_content = "It's not dead yet?!",
  ui_story_5080_50801402_33_dialog_content = "Then... let's do it one more time...",
  ui_story_5080_50801402_34_dialog_content = "(This is bad... I can sense Rachel's body has reached its limit... She's pushing too hard... just a little bit more, and...)",
  ui_story_5080_50801402_35_dialog_content = "I... will never give up... One more time!",
  ui_story_5080_50801402_36_dialog_content = "Grah!!!",
  ui_story_5080_50801402_37_dialog_content = "Ice Bridge... Hurry!",
  ui_story_5080_50801402_38_dialog_content = "She's out of strength... If this keeps up... both of them will...",
  ui_story_5080_50801402_39_dialog_content = "What's all the racket?! Can't a guy get some rest around here?!",
  ui_story_5080_50801402_40_dialog_content = "You... Sinsa?!",
  ui_story_5080_50801402_41_dialog_content = "Hey, little lady, you've got some spirit.",
  ui_story_5080_50801402_42_dialog_content = "Being able to lift this wrench means you've got real strength.",
  ui_story_5080_50801402_43_dialog_content = "Using that strength to protect others shows you've got an even brighter will.",
  ui_story_5080_50801402_44_dialog_content = "Come on! For the <color=#FFB400>justice</color> in your heart, wield that <color=#FFB400>supreme power</color>!",
  ui_story_5080_50801402_45_dialog_content = "<size=45>Hyaaaaaaah—!!!</size>",
  ui_story_5080_50801402_46_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5080_50801402_47_dialog_content = "People from completely different worlds, lifting that wrench for the hearts they guard...",
  ui_story_5080_50801402_48_dialog_content = "Those two silhouettes...",
  ui_story_5080_50801402_49_dialog_content = "Don't even think about hurting them!",
  ui_story_5080_50801402_50_dialog_content = "You won't get past me!",
  ui_story_5080_50801402_51_dialog_content = "Even the one who couldn't understand you at first, now lifts that wrench—",
  ui_story_5080_50801402_52_dialog_content = "Heh... your will lives on to this day... Attar...",
  ui_story_5080_50801402_53_dialog_content = "It lives on as... <color=#FFB400>the Rediesel Wrench</color>.",
  ui_story_5080_50801402_54_dialog_content = "Finally done and dusted... Here comes the lava, let's move.",
  ui_story_5080_50801402_55_dialog_content = "The last ice bridge is up. Let's go.",
  ui_story_5080_50801402_56_dialog_content = "Hey—! Over here!",
  ui_story_5080_50801402_57_dialog_content = "This way! I've thrown a grappling hook up there, we can climb out!",
  ui_story_5080_50801402_58_dialog_content = "PlayerName... let's go... ugh!",
  ui_story_5080_50801402_59_dialog_content = "Hey now, are you alright? Pushing yourself too hard with all those injuries—you've got nothing left in you, have you?",
  ui_story_5080_50801402_60_dialog_content = "Guess you've got no choice. Need a hand from this Rediesel bandit?",
  ui_story_5080_50801402_61_dialog_content = "...",
  ui_story_5080_50801402_62_dialog_content = "Hey!",
  ui_story_5080_50801402_63_dialog_content = "<color=#e8d9bb>A stone grazes past the two and plummets into the lava.</color>",
  ui_story_5080_50801402_64_dialog_content = "... Who says I can't stand up? Need a hand from this Illumina soldier?",
  ui_story_5080_50801402_65_dialog_content = "Hahahaha! You're way cuter than you let on.",
  ui_story_5080_50801402_66_dialog_content = "A pebble like that is no big deal... but I shouldn't make Eve worry about my wound.",
  ui_story_5080_50801402_67_dialog_content = "Much obliged.",
  ui_story_5080_50801402_68_dialog_content = "Sorry... but can someone give me a hand? I've overdone my psychic ability. I'm totally conked...",
  ui_story_5080_50801402_69_dialog_content = "...",
  ui_story_5080_50801402_70_dialog_content = "Heh...",
  ui_story_5080_50801402_71_dialog_content = "Hahaha!",
  ui_story_5080_50801402_72_dialog_content = "Stop laughing over there, let's get a move on!",
  ui_story_5080_50801402_73_dialog_content = "<color=#e8d9bb>Rumble, rumble!</color>",
  ui_story_5080_50801402_74_dialog_content = "Oh ho! Finally out! Fresh air and a perfect temperature!",
  ui_story_5080_50801402_75_dialog_content = "Whoa! How'd you guys get so fast?!",
  ui_story_5080_50801402_76_dialog_content = "Looks like letting you two run ahead was the right call. That path-finding ability is really something...",
  ui_story_5080_50801402_77_dialog_content = "Zeta led the way.",
  ui_story_5080_50801402_78_dialog_content = "Wh-What of it?! I'm a rally racing legend! So what if I'm not a caving pro!",
  ui_story_5080_50801402_79_dialog_content = "Hahahaha!",
  ui_story_5080_50801402_80_dialog_content = "Hey, Berserker! No laughing!",
  ui_story_5080_50801402_81_dialog_content = "Well, of course, we gotta laugh, little Zeta.",
  ui_story_5080_50801402_82_dialog_content = "You?! Even you wish to bully this great hero...?!",
  ui_story_5080_50801402_83_dialog_content = "We can actually make it back in time for the feast! Seriously!",
  ui_story_5080_50801402_84_dialog_content = "What are we dilly-dallying here for? They might start without us!",
  ui_story_5080_50801402_85_dialog_content = "What? With the Greta Hero Zeta here? I'll get you back in a flash!",
  ui_story_5080_50801402_86_dialog_content = "Get in the car!",
  ui_story_5080_50801402_87_dialog_content = "Hello... Jonah?",
  ui_story_5080_50801402_88_dialog_content = "Azure?",
  ui_story_5080_50801402_89_dialog_content = "Oh my... I rarely come back, and when I do, the place is dead.",
  ui_story_5080_50801402_90_dialog_content = "Wait! What's that over there?",
  ui_story_5080_50801402_91_dialog_content = "<color=#e8d9bb>Bang!!! Bang, bang, bang!</color>",
  ui_story_5080_50801402_92_dialog_content = "<color=#e8d9bb>An explosion from a trap sets off a chain reaction among all the landmines. In a matter of moments, the entire camp is unrecognizable.</color>",
  ui_story_5080_50801402_93_dialog_content = "That's the minefield...",
  ui_story_5080_50801402_94_dialog_content = "What's going on?",
  ui_story_5080_50801402_95_dialog_content = "How did the camp end up in this state? Uh... are we still having a party tonight?",
  ui_story_5080_50801402_96_dialog_content = "Ahhhhhhh!",
  ui_story_5080_50801402_97_dialog_content = "You idiots! What have you done?!",
  ui_story_5080_50801402_98_dialog_content = "Just a tiny miscalculation, boss!",
  ui_story_5080_50801402_99_dialog_content = "Stop running! Stand still! I'm gonna teach you a lesson!",
  ui_story_5080_50801402_100_dialog_content = "Alright, alright, stop beating the kid for now. Let's see what's still edible here, shall we?",
  ui_story_5080_50801402_101_dialog_content = "Wahaaah! My beautiful stage...!",
  ui_story_5080_50801402_102_dialog_content = "Don't cry, let me see if I can fix it...",
  ui_story_5080_50801402_103_dialog_content = "Heh, I never thought I'd see you have such a rough day, witch girl!",
  ui_story_5080_50801402_104_dialog_content = "Surely you must have no idea what kind of feats Zeta the Great is capable of accomplishing?!",
  ui_story_5080_50801402_105_dialog_content = "... Meh, forget it... I'm glad to see you, big sis.",
  ui_story_5080_50801402_106_dialog_content = "What is all this?",
  ui_story_5080_50801402_107_dialog_content = "Really—",
  ui_story_5080_50801402_108_dialog_content = "Hey? Rachel! Rachel!",
  ui_story_5080_50801402_109_dialog_content = "What's up? Let me take a look...",
  ui_story_5080_50801402_110_dialog_content = "Oh, she's fine. She was just so relaxed that she passed out.",
  ui_story_5080_50801402_111_dialog_content = "Her drone's broken again? Hmph, Odi, watch and learn as I flex my exquisite repair skills!",
  ui_story_5080_50801402_112_dialog_content = "How could it be your turn with me here?",
  ui_story_5080_50801402_113_dialog_content = "Is this... Gannon City?",
  ui_story_5080_50801402_114_dialog_content = "When did I return home...?",
  ui_story_5080_50801402_115_dialog_content = "Captain! Captain!",
  ui_story_5080_50801402_116_dialog_content = "I-I...",
  ui_story_5080_50801402_117_dialog_content = "White Swan... no, Merry, you...",
  ui_story_5080_50801402_118_dialog_content = "Ah, it's been so long... Hmm?!",
  ui_story_5080_50801402_119_dialog_content = "Captain, you... Why are you crying?",
  ui_story_5080_50801402_120_dialog_content = "Sorry, I'm sorry... I've been wanting to tell you this for so long.",
  ui_story_5080_50801402_121_dialog_content = "I'm not a good captain... I let you... let you...",
  ui_story_5080_50801402_122_dialog_content = "Hahaha, never thought the captain would ever shed tears so freely.",
  ui_story_5080_50801402_123_dialog_content = "It's my first time seeing it... and hopefully, it's my last.",
  ui_story_5080_50801402_124_dialog_content = "You're the one who survived, Captain. Isn't that just great?",
  ui_story_5080_50801402_125_dialog_content = "We're so happy we could save you.",
  ui_story_5080_50801402_126_dialog_content = "And now you're even more perfect than before! I mean, you saved everyone, didn't you?",
  ui_story_5080_50801402_127_dialog_content = "You're the ultimate captain now.",
  ui_story_5080_50801402_128_dialog_content = "You guys...",
  ui_story_5080_50801402_129_dialog_content = "I'm so glad I got to meet you, Captain.",
  ui_story_5080_50801402_130_dialog_content = "Out of all the squads, I got to be chosen by you... I'm so lucky.",
  ui_story_5080_50801402_131_dialog_content = "So you have to be happy too, Captain.",
  ui_story_5080_50801402_132_dialog_content = "Where are you guys going? Come back here! Listen to me...",
  ui_story_5080_50801402_133_dialog_content = "Time to go back, Captain. We're not the ones you need to keep safe now.",
  ui_story_5080_50801402_134_dialog_content = "Please live well... Laugh more—that's all we want!",
  ui_story_5080_50801402_135_dialog_content = "Wait, everyone, don't go!",
  ui_story_5080_50801402_136_dialog_content = "Captain...",
  ui_story_5080_50801402_137_dialog_content = "W-Wait for me!",
  ui_story_5080_50801402_138_dialog_content = "Captain...!",
  ui_story_5080_50801402_139_dialog_content = "You...",
  ui_story_5080_50801402_140_dialog_content = "Vice?",
  ui_story_5080_50801402_141_dialog_content = "Captain...?",
  ui_story_5080_50801402_142_dialog_content = "You're okay... What a relief.",
  ui_story_5080_50801402_143_dialog_content = "Wait! Did you just... say my name?",
  ui_story_5080_50801402_144_dialog_content = "Waaah! Captain! Captain!!!",
  ui_story_5080_50801402_145_dialog_content = "<color=#e8d9bb>Vice, overwhelmed with joy, hugs Rachel tightly, not caring how stiff the recipient of her hug is.</color>",
  ui_story_5080_50801402_146_dialog_content = "(But... that sincere heart definitely won't go unrequited.)",
  ui_story_5080_50801402_147_dialog_content = "It's okay now... Everything's okay...",
  ui_story_5080_50801402_148_dialog_content = "Thank you, Vice.",
  ui_story_5080_50801402_149_dialog_content = "Thank you, everyone.",
  ui_story_5080_50801500_1_dialog_content = "We killed that Eclipsite to save ourselves, but now, the earthquake has subsided, and the volcano hasn't erupted.",
  ui_story_5080_50801500_2_dialog_content = "You mean... there's still something suppressing the volcano's energy?",
  ui_story_5080_50801500_3_dialog_content = "It's just a guess, but before we left, the Speakers found—",
  ui_story_5080_50801500_4_dialog_content = "The spot where you flattened that Eclipsite had been pierced through. There was another layer below, with its own pathway.",
  ui_story_5080_50801500_5_dialog_content = "A pathway within the volcano's core?",
  ui_story_5080_50801500_6_dialog_content = "But now it's all covered in lava, so we might not be able to investigate it.",
  ui_story_5080_50801500_7_dialog_content = "... Roy reckons that Eclipsite wasn't the one from back then.",
  ui_story_5080_50801500_8_dialog_content = "Indeed. If it were not for the terrain, things wouldn't have been so difficult. If this was the one from back then, Attar wouldn't have died...",
  ui_story_5080_50801500_9_dialog_content = "It seems everything is closely related to the true depths of the volcano.",
  ui_story_5080_50801500_10_dialog_content = "Our true <color=#FFB400>enemy</color>... might be hiding there.",
  ui_story_5080_50801500_11_dialog_content = "Let's investigate together once the lava cools and everyone's injuries heal.",
  ui_story_5080_50801500_12_dialog_content = "It must be quite a bother for the Rediesel Wrench, sleeping above such an active volcano?",
  ui_story_5080_50801500_13_dialog_content = "Who's to say... We're all just a big bunch of fools living in the moment. Is there really anyone among us who'd worry so much about something like that?",
  ui_story_5080_50801500_14_dialog_content = "The stage is fixed... I've been working on it non-stop, and boy, am I tired!!!",
  ui_story_5080_50801500_15_dialog_content = "Don't worry, just leave the next bit to me! Let my passion burn through the night sky—!",
  ui_story_5080_50801500_16_dialog_content = "Huh? Zeta?! You, you...",
  ui_story_5080_50801500_17_dialog_content = "Why'd you make yourself up like a ghost?",
  ui_story_5080_50801500_18_dialog_content = "Eh? This was all witch girl's idea, making Zeta up like a grown-up!",
  ui_story_5080_50801500_19_dialog_content = "You mean... that witch girl!!!",
  ui_story_5080_50801500_20_dialog_content = "Don't run! Didn't you say you'd dance with me? We're about to go on stage for the final showdown!",
  ui_story_5080_50801500_21_dialog_content = "Brock, you saw it too, right? Everyone's hungry.",
  ui_story_5080_50801500_22_dialog_content = "The fastest veggie washer will no doubt be hailed the true hero who solved this crisis—a hero worthy of everyone's respect.",
  ui_story_5080_50801500_23_dialog_content = "Oh, oh, oh! You don't need to tell me twice—I've been training for this, just watch!",
  ui_story_5080_50801500_24_dialog_content = "Really? Wow, I wish everyone were this gullible... Hey! I've got a veggie washer here! Interested?",
  ui_story_5080_50801500_25_dialog_content = "The camp's a mess... I wanna help too.",
  ui_story_5080_50801500_26_dialog_content = "Me too.",
  ui_story_5080_50801500_27_dialog_content = "Get outta the way! Nobody's stealing my thunder!",
  ui_story_5080_50801500_28_dialog_content = "Just let him do it, if you want a peaceful life.",
  ui_story_5080_50801500_29_dialog_content = "Azure? Azure? Where did you go?",
  ui_story_5080_50801500_30_dialog_content = "I've practically emptied the warehouse. You need to have a real drink with me tonight!",
  ui_story_5080_50801500_31_dialog_content = "Seriously, what a rowdy crowd...",
  ui_story_5080_50801500_32_dialog_content = "I'm not some real old-timer, just a little brat who stumbled into all this halfway.",
  ui_story_5080_50801500_33_dialog_content = "Astra's so vast... but this is the only place that took me and Eve in when we had nowhere to go.",
  ui_story_5080_50801500_34_dialog_content = "We've finally come this far. We can finally rely on ourselves to carry on and live together as a family.",
  ui_story_5080_50801500_35_dialog_content = "No more worrying about pleasing anyone else or fearing rejection.",
  ui_story_5080_50801500_36_dialog_content = "You know what? This is the first time I've heard you say this.",
  ui_story_5080_50801500_37_dialog_content = "We're all such weirdos, just like grains of sand desperately grinding together. If it's true that blood runs thicker than water, then we must've mixed our blood together a long time ago.",
  ui_story_5080_50801500_38_dialog_content = "So, I'm happy to spend every day with these guys.",
  ui_story_5080_50801500_39_dialog_content = "No matter what challenges come our way, we always come together to forge a happy life. That's what freedom means to us!",
  ui_story_5080_50801500_40_dialog_content = "And to preserve our way of life, I'll raise my wrench time and again to fend off anyone who messes with us!",
  ui_story_5080_50801500_41_dialog_content = "You're an extraordinary leader, Sinsa.",
  ui_story_5080_50801500_42_dialog_content = "Now, I have a favor to ask. My mission is complete, but I'm still not satisfied.",
  ui_story_5080_50801500_43_dialog_content = "If danger still lurks nearby, I want to face it alongside everyone else here.",
  ui_story_5080_50801500_44_dialog_content = "Besides, the old leader saved my aunt, and I want to repay the debt.",
  ui_story_5080_50801500_45_dialog_content = "So, let me ask you now—do you understand the meaning of \"sacrifice\"?",
  ui_story_5080_50801500_46_dialog_content = "Heh...",
  ui_story_5080_50801500_47_dialog_content = "Huh? Why are you looking at us?",
  ui_story_5080_50801500_48_dialog_content = "I've made up my mind. To spare my teammates constant worry, I won't speak lightly of sacrifice.",
  ui_story_5080_50801500_49_dialog_content = "But... if we're ever in danger, I'll give my life for those by my side.",
  ui_story_5080_50801500_50_dialog_content = "No matter what, I wish to protect those who walk with me.",
  ui_story_5080_50801500_51_dialog_content = "Yeah... Illumina soldiers shouldn't just act for the sake of the mission or for honor.",
  ui_story_5080_50801500_52_dialog_content = "But because we want to protect everything in our lives.",
  ui_story_5080_50801500_53_dialog_content = "Rachel...",
  ui_story_5080_50801500_54_dialog_content = "Even if I must become a blazing fire to light the way and ensure the futures of those around me—this is the true purpose of Illumina!",
  ui_story_5080_50801500_55_dialog_content = "My ancestors were helped by others and sacrificed for others in turn, and I won't be an exception!",
  ui_story_5080_50801500_56_dialog_content = "From now on, I'll fight to protect my heartfelt desires and become an unyielding line of defense for Illumina.",
  ui_story_5080_50801500_57_dialog_content = "Your words sound kind of the same as they always have, but your eyes tell a different story.",
  ui_story_5080_50801500_58_dialog_content = "You sure you're ready to start making your own choices now?",
  ui_story_5080_50801500_59_dialog_content = "The creed of Illumina is \"one for all, all for one.\"",
  ui_story_5080_50801500_60_dialog_content = "Even so, we can still make our own decisions through our own will. We can decide what it is we fight for, and what we're willing to sacrifice our lives for.",
  ui_story_5080_50801500_61_dialog_content = "This kind of resolve could never be untrue... Ah!",
  ui_story_5080_50801500_62_dialog_content = "Can you still find the Illumina in your heart?",
  ui_story_5080_50801500_63_dialog_content = "What's wrong, Captain Rachel? Are your injuries acting up?",
  ui_story_5080_50801500_64_dialog_content = "...No, don't worry, Vice.",
  ui_story_5080_50801500_65_dialog_content = "I just... finally know how to answer that question.",
  ui_story_5080_50801500_66_dialog_content = "What question...?",
  ui_story_5080_50801500_67_dialog_content = "Heh... looks like you finally know what you're looking for.",
  ui_story_5080_50801500_68_dialog_content = "Alright, I agree to let you lend a hand with the investigation.",
  ui_story_5080_50801500_69_dialog_content = "But with those injuries, don't think about rushing in just yet.",
  ui_story_5080_50801500_70_dialog_content = "Stay here tonight, enjoy a good meal, and rest up.",
  ui_story_5080_50801500_71_dialog_content = "Hmm... But...",
  ui_story_5080_50801500_72_dialog_content = "But?",
  ui_story_5080_50801500_73_dialog_content = "Even though we're allies, if the Rediesel Wrench causes trouble again, I'll deal with you the same way I'd deal with anyone!",
  ui_story_5080_50801500_74_dialog_content = "If you sully the will that wrench represents, I'll make you hand it over.",
  ui_story_5080_50801500_75_dialog_content = "Uh...",
  ui_story_5080_50801500_76_dialog_content = "If you want it, come and take it yourself.",
  ui_story_5080_50801500_77_dialog_content = "Honestly, your crazy Illumina brain's got a few screws loose.",
  ui_story_5080_50801500_78_dialog_content = "Hahahaha!",
  ui_story_5080_50801500_79_dialog_content = "What are you laughing at?",
  ui_story_5080_50801500_80_dialog_content = "This is the first time I've seen you look so helpless, Sinsa! Hahahaha!",
  ui_story_5080_50801500_81_dialog_content = "Give me a break...",
  ui_story_5080_50801500_82_dialog_content = "Boss! Boss! Look at this!",
  ui_story_5080_50801500_83_dialog_content = "We found it while cleaning up the wreckage—it looks like it might be the old boss's diary.",
  ui_story_5080_50801500_84_dialog_content = "We discovered it in a little box that got blown open by the blast... Looks like it's been hidden all this time.",
  ui_story_5080_50801500_85_dialog_content = "... Understood. For now, let's just put it away.",
  ui_story_5080_50801500_86_dialog_content = "It's party time after all. We'll worry about all the other stuff tomorrow—let's have some fun!",
  ui_story_5080_50801500_87_dialog_content = "Got it! Hey! Stop pushing... Ouch!",
  ui_story_5080_50801500_88_dialog_content = "Now it's my turn to laugh! Hahahaha!",
  ui_story_5080_50801500_89_dialog_content = "My little bird of prey, please wait a moment.",
  ui_story_5080_50801500_90_dialog_content = "What's wrong?",
  ui_story_5080_50801500_91_dialog_content = "I want to tell you the final part of the story Attar shared with me.",
  ui_story_5080_50801500_92_dialog_content = "After she saved her teammate and abandoned her mission, she left Illumina. Aimless, she wandered the world for a while.",
  ui_story_5080_50801500_93_dialog_content = "She coincidentally arrived in this same desert where she had failed her mission, knowing that her enemy still lingered.",
  ui_story_5080_50801500_94_dialog_content = "She said she was born in this desert. She knows that this desert is a lawless place and that it's free. It's just that she's never lived here before.",
  ui_story_5080_50801500_95_dialog_content = "So she wanted to see it for herself. At the very least, she wanted to find a resting place for her dead team members.",
  ui_story_5080_50801500_96_dialog_content = "...",
  ui_story_5080_50801500_97_dialog_content = "She encountered bandits while wandering the desert, and by some trick of fate, she led them to fight the Eclipsites, picking up that legendary wrench to battle them.",
  ui_story_5080_50801500_98_dialog_content = "For those people, she raised her wrench, united the desert bandits, and put an end to the chaos in this barren land.",
  ui_story_5080_50801500_99_dialog_content = "She led those people to settle in the oasis and learned the legendary story behind the wrench.",
  ui_story_5080_50801500_100_dialog_content = "And thus, she stained the wrench with rediesel extracted from the oasis, officially establishing the Rediesel Wrench.",
  ui_story_5080_50801500_101_dialog_content = "She lived well, not only finding true freedom but ultimately sacrificing everything to protect it.",
  ui_story_5080_50801500_102_dialog_content = "Why... are you telling me all this?",
  ui_story_5080_50801500_103_dialog_content = "Please tell your aunt when you return.",
  ui_story_5080_50801500_104_dialog_content = "Her captain didn't just aimlessly desert her nation. Throughout her journey in life, she wielded her weapon for the freedom of others, until the very end.",
  ui_story_5080_50801500_105_dialog_content = "I hope this information brings some solace to your aunt.",
  ui_story_5080_50801500_106_dialog_content = "Thank you... I really don't know how else to express my gratitude.",
  ui_story_5080_50801500_107_dialog_content = "Sing, little bird of prey! Can't you hear the song?",
  ui_story_5080_50801500_108_dialog_content = "The song...?",
  ui_story_5080_50801500_109_dialog_content = "Burn brightly, beautiful paradise, our home!",
  ui_story_5080_50801500_110_dialog_content = "Sing, sing, even if tomorrow's world is riddled with wounds!",
  ui_story_5080_50801500_111_dialog_content = "Raise your voice in the song... That is... the power of life.",
  ui_story_5080_50801500_112_dialog_content = "Captain Rachel! Over here! The feast is about to begin!",
  ui_story_5080_50801500_113_dialog_content = "Ah... I'll be right over!",
  ui_story_5080_50801500_114_dialog_content = "... It's also time for me to go...",
  ui_story_5080_50801500_115_dialog_content = "Where are you off to? Hey, take this.",
  ui_story_5080_50801500_116_dialog_content = "This is...",
  ui_story_5080_50801500_117_dialog_content = "Cactus with grilled crystal scorpion liver. It's delicious! I'm guessing you've never tried it before.",
  ui_story_5080_50801500_118_dialog_content = "You've explored so much, in so many places I didn't even know existed.",
  ui_story_5080_50801500_119_dialog_content = "Talk about stating the obvious...",
  ui_story_5080_50801500_120_dialog_content = "Hey... Jeriah, you should come back home too, once in a while. Let's have a big meal together.",
  ui_story_5080_50801500_121_dialog_content = "... It looks like there's no way out of this feast,",
  ui_story_5080_50801500_122_dialog_content = "So what else is there to say? Come on!",
  ui_story_5080_50801500_123_dialog_content = "Rachel, over here! I saved you a seat.",
  ui_story_5080_50801500_124_dialog_content = "Once the meat is grilled, grab your share while you can—these guys generally don't have time for pleasantries!",
  ui_story_5080_50801500_125_dialog_content = "Thank you... Thank you all.",
  ui_story_5080_50801500_126_dialog_content = "For what? This is nothing, really.",
  ui_story_5080_50801500_127_dialog_content = "No... I'm grateful for the way you've constantly made such an effort to accept me, despite my flaws.",
  ui_story_5080_50801500_128_dialog_content = "Let's shake hands—it's an Illumina tradition.",
  ui_story_5080_50801500_129_dialog_content = "... Okay!",
  ui_story_5080_50801500_130_dialog_content = "Curious, isn't it? Despite you being a Caelestite, why do I feel such a sense of familiarity when I'm with you?",
  ui_story_5080_50801500_131_dialog_content = "And you never judge me. You seem at ease with Illuminans.",
  ui_story_5080_50801500_132_dialog_content = "(Where should I begin? It's been a long journey... with Gram, Revy, Reinhardt, Barton, and the others...)",
  ui_story_5080_50801500_133_dialog_content = "PlayerName, let's do this together, like I just said!",
  ui_story_5080_50801500_134_dialog_content = "Right!",
  ui_story_5080_50801500_135_dialog_content = "Splendor Illumina!! A salute to you!",
  ui_story_5080_50801500_136_dialog_content = "Thank you for saving me and Vice!",
  ui_story_5080_50801500_137_dialog_content = "Such a fine military salute... Heh, it seems you've both been through so much. This must be why you are such legendary companions.",
  ui_story_5080_50801500_138_dialog_content = "Now I understand why the Grand Marshal called you incredible.",
  ui_story_5080_50801500_139_dialog_content = "But for now, you're my companions too...",
  ui_story_5080_50801500_140_dialog_content = "Let's enjoy this dinner together, everyone!",
  ui_story_5080_50801500_141_dialog_content = "<color=#e8d9bb>The coarse song of the Rediesel Wrench, though unrefined, exudes a sense of unbridled freedom. It ignites the desert, echoing through the night in a frenzied melody.</color>",
  ui_story_5080_50801500_142_dialog_content = "Merry... Louis... Tarsi... Lina... can you hear it?",
  ui_story_5080_50801500_143_dialog_content = "They say this desert embraces all souls... So...",
  ui_story_5080_50801500_144_dialog_content = "Surely it embraces you too.",
  ui_story_5080_50801500_145_dialog_content = "Fly... in this night of freedom.",
  ui_story_5080_50801500_146_dialog_content = "Until your souls find rest."
}
return config
